window.TURATH_JK(55,{"1":["لها ثلاثة أسماء معروفة وهي: فاتحة الكتاب، وأم القرآن، والسبع المثاني.","وتسمى أيضا بأم الكتاب.","قال البخاري رحمه الله تعالى في تفسير سورة الفاتحة: \"وسميت أم الكتاب، لأنه يبدأ بكتابتها في المصاحف، ويبدأ بقراءتها في الصلاة\".","وقد كره بعض السلف تسميتها بأم الكتاب وقالوا: أم الكتاب هو اللوح المحفوظ، مع أنه جاء ذكرها بأم الكتاب في الأحاديث الصحيحة.","وتسمى أيضا كما جاء في الآثار: الكنـز، والوافية، والشافية، والكافية، والحمد، والحمد لله، والصلاة، والشفاء، والأساس، والشكر، والدعاء.","ذكرها الحافظ ابن حجر في الفتح (8/106) وقال: \"جمعتُها من الآثار\".","قال بعض العلماء: إنّ سورة الفاتحة تشتمل على معان جليلة.","منها: إثبات التوحيد بأنواعه الثلاثة فقوله: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ فيه إثبات توحيد الربوبية، وردٌّ على الملاحدة الذين يقولون: إن الكون ليس له خالق، وإنّ الطبيعة هي التي خلقت العالم.وقوله: الرَّحْمَنِ الرَّحِيمِ فيه إثبات الأسماء والصفات، وفيه ردٌّ على الجهمية والمعتزلة ومنكري الصفات.وقوله: إِيَّاكَ نَعْبُدُ فيه إثبات توحيد الألوهية، وفيه ردٌّ على المشركين الذين يؤمنون بالربوبية، ويشركون غيرَه في العبادات.","وقوله: وَإِيَّاكَ نَسْتَعِينُ فيه ردٌّ على من يستغيثُ بالأولياء وأصحاب القبور.","ومنها: إثبات البعث كما في قوله: مَالِكِ يَوْمِ الدِّينِ وفيه ردٌّ على منكري البعث الذين يقولون: أَإِذَا مِتْنَا وَكُنَّا تُرَابًا ذَلِكَ رَجْعٌ بَعِيدٌ [سورة ق: 3] وإثبات الجزاء والحساب.","ومنها: الردّ على الملل والنحل كما في قوله تعالى: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ (6) صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ (7)","فقوله تعالى: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ: طريق الأنبياء والمرسلين.","وقوله: غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ هم الذين علموا ولم يعملوا به مثل اليهود الذين علموا ببعثة النبي صلى الله عليه وسلم، ووجدوا وصفَه في التوراة، ولكنهم أنكروا لما جاءهم، فغضبَ الله عليهم.","وقوله: وَلَا الضَّالِّينَ أي: الذين اختاروا طريق الضلالة بدون علم، وهم النصارى الذين اتبعوا بوليس الرسول بدون علم من تعليمات المسيح عليه السلام وحواريه، فأضلّهم الله تعالى، ويدخل فيهم المبتدعة الذين يعملون البدعة بدون علم، ويخالفون قول الله عزوجل: فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ [سورة محمد: ١٩].فبدأ بالعلم قبل العمل.","ولهذه المعاني وغيرها سميت سورة الفاتحة بأم القرآن، لأن القرآن جُلَّه يدور على هذه المعاني التي تضمّنتْها هذه السورة."],"3":["بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ (1) الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ (2) الرَّحْمَنِ الرَّحِيمِ (3) مَالِكِ يَوْمِ الدِّينِ (4) إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ (5) اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ (6) صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ (7)","بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ليست آية من سورة الفاتحة ولا غيرها من السور في أصح أقوال أهل العلم، وإنما تكتب قبل كل سورة للتبرك، وللفصل بين السور، والحجة في ذلك قول أنس بن مالك: صليتُ مع رسول الله صلى الله عليه وسلم وأبي بكر وعمر وعثمان، فلم أسمع أحدًا منهم يقرأ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ .","رواه مسلم (399)، وفي رواية عنده: فكانوا يستفتحون بــ : الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ لا يذكرون بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ في أول قراءة ولا في آخرها.","رَبِّ الْعَالَمِينَ العالم العاقل أربعة: الإنس والجن والملائكة والشياطين.","وأما العالم غير العاقل فلا يُعَدُّ ولا يُحصى، فكلُّ جمادٍ ونباتٍ وحيوانٍ عالمٌ، فهو ربّ العالمين في جميع صوره.","قال تعالى: تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُ كَانَ حَلِيمًا غَفُورًا [الإسراء: ٤٤]","والآيات في هذا المعني كثيرة جدا.","قوله: الرَّحْمَنِ الرَّحِيمِ","الرَّحْمَنِ لجميع خلقه، الرَّحِيمِ للمؤمنين منهم لقوله تعالى: ﴿وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا [سورة طه: ٥] يعمُّ جميعَ خلقه برحمته.وقال: وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا﴾ [سورة الأحزاب: ٤٣]","فالرحمن أشدُّ مبالغةً في رحمته ولذا لا يوصف أحد به، بخلاف الرحيم فإنه يوصف غيره أيضا كقوله تعالى: لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ بِالْمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ [التوبة: ١٢٨]"],"7":["رُوِيَ عن معقل بن يسار أن رسول الله صلى الله عليه وسلم قال: ((البقرة سنام القرآن، وذروته، نزل مع كل آية منها ثمانون ملكا، واستخرجت اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة: ٢٥٥] من تحت العرش، فوصلت بها، أو فوصلت بسورة البقرة، وياسين قلب القرآن، لا يقرؤها رجل يريد الله والدار الآخرة إلا غفر له، واقرؤوها على موتاكم))","روه أحمد (20300)، والطبراني في الكبير (20/511)، والنسائي في اليوم والليلة (1075) كلهم من حديث معتمر بن سليمان، عن أبيه، عن رجل، عن أبيه، عن معقل بن يسار فذكره.","وفيه رجل وأبوه مبهمان.","ولا ينفع التصريح بهما في الرواية الثانية عند أحمد (20301) عن عارم حدثنا عبد الله بن المبارك، حدثنا سليمان التميمي، عن أبي عثمان – وليس بالنهدي، عن أبيه، عن معقل بن يسار قال: قال رسول الله صلى الله عليه وسلم: ((اقرؤوا على موتاكم)) يعني ياسين.","ومن هذا الوجه أخرجه أيضا أبو داود (3121) وابن ماجه (1448).","وفيه أبو عثمان وأبوه مجهولان وسبق تخريجه مفصلا.","ورُوِيَ أيضا عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: ((لكل شيء سنام، وإن سنام القرآن سورة البقرة، وفيها آية هي سيدة آي القرآن، هي آية الكرسي))","رواه الترمذي (2878) والحاكم (2/259) كلاهما من حديث زائدة، عن حكيم بن جبير، عن أبي صالح، عن أبي هريرة فذكره واللفظ للترمذي.","قال الترمذي: هذا حديث غريب لا نعرفه إلا من حديث حكيم بن جبير، وقد تكلم شعبة في حكيم بن جبير وضعّفه.","قلت: وهو كما قال، فقد تكلم فيه أيضا أحمد وابن معين وأبو حاتم والنسائي وغيرهم.","وأما الحاكم فقال: \"هذا حديث صحيح الإسناد\"، وهو ذهول منه أو تساهل.","وكذلك لا يصح ما رُوي عن سهل بن سعد قال: قال رسول الله صلى الله عليه وسلم: ((إن لكل شيء سناماً، وإن سنام القرآن سورة البقرة، من قرأها في بيته ليلاً لم يدخل الشيطان بيته ثلاث ليال، ومن قرأها نهاراً، لم يدخل الشيطان بيته ثلاثة أيام))","رواه ابن حبان (780)، والطبراني في الكبير (6/163) كلاهما من حديث الأزرق بن علي بن جهم، حدثنا حسان بن إبراهيم، حدثنا خالد بن سعيد المدني، عن أبي حازم، عن سهل بن سعد فذكره.","وخالد بن سعيد المدني ضعيف لا يتابع على حديثه كما قال العقيلي.وقال ابن المديني: \"لا يعرف\".","تنبيه: \"خالد بن سعيد\"تحرف في معجم الطبراني إلى \"سعيد بن خالد\".","ومجموع هذه الأحاديث تدل على أن لها أصلا، ولكن لما لم يكن فيه أصل ثابت، لم أخرجه في الجامع الكامل."],"13":["الم: القول الصحيح في الحروف المقطعات هي أسماء السور، والأسماء لا تعلل ولا تفسر، وعليه أكثر أهل العلم.","وقيل: لها معنى ولكن الله تبارك وتعالى استأثر بعلمه.","وقيل: لها معنى عرف بالتتبع وإمعان النظر، ثم اختلف القائلون بهذا القول مما يطول ذكره.وأحسن ما قيل فيه: إن القرآن مركب من هذه الحروف التي يتخاطبون بها وتحداهم القرآن أن يأتوا بمثله ولو آية، ومن أسرار هذه الحروف أنها جاءت بحرف واحد مثل: ص، ن، ق وبحرفين مثل: حم وبثلاثة حروف مثل: الم وبأربعة مثل: المر، المص وبخمسة مثل: كهيعص","وكلامهم كان من حرف إلى خمسة أحرف لا أكثر من ذلك ومثال حرف كقول الشاعر:","قلنا لها قفي لنا قالت قاف لا تحتسبي أنا فينا الإيجاف","قالت قاف – أي وقفت.","وذكر ابن جرير وغيره أمثلة أخرى."],"14":["الكتاب هو: القرآن الكريم","وقوله: هُدًى لِلْمُتَّقِينَ أي التفاصيل الواردة في القرآن من الأوامر والنواهي لا يستفيد منها إلا المتقون مثل قوله تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت: ٤٤ ]","وأما غير المتقين من الكفار والمشركين فلهم قوله تعالى: يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمْ بُرْهَانٌ مِنْ رَبِّكُمْ وَأَنْزَلْنَا إِلَيْكُمْ نُورًا مُبِينًا [النساء: ١٧٤]","وقال الله تعالى قَدْ جَاءَكُمْ مِنَ اللَّهِ نُورٌ وَكِتَابٌ مُبِينٌ [المائدة: ١٥]","وقال تعالى: الر كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ [إبراهيم: ١ ]","فالقرآن هدى للناس جميعا لمن أراد الاهتداء به، وللمؤمنين المتقين خصوصا في معرفة الأحكام والشرائع."],"15":["قوله: يُؤْمِنُونَ بِالْغَيْبِ الغيب: يعني كل ما غاب عن الناس، ولا يمكن إدراكه بالحواس مثل وجود الله تعالى، والملائكة واليوم الآخر، وصفة الجنة والنار، وما أعده الله تعالى من الحياة بعد الموت إلى غير ذلك مما ذكر في القرآن والسنة الصحيحة.","وقوله: وَيُقِيمُونَ الصَّلَاةَ إقامة الصلاة هي أداء الصلاة كاملة ابتداء من إسباغ الوضوء، وقراءة القرآن، وإتمام الركوع والسجو، والتشهد والصلاة على النبي صلى الله عليه وسلم مع المحافظة على مواقيتها."],"16":["قوله: خَتَمَ اللَّهُ عَلَى قُلُوبِهِمْ وذلك جزاء منه على تماديهم في الباطل، وتركهم الحق، لا أنه تعالى ختم على قلوبهم ابتداء، بل خلقهم كغيرهم على الفطرة، وهداهم النجدين، فلما اختاروا الباطل بمحض إرادتهم ختم الله على قلوبهم جزاء وفاقا.","قال القرطبي: وأجمعت الأمة على أن الله عزوجل قد وصف نفسه بالختم والطبع على قلوب الكافرين مجازاة لكفرهم كما قال: بَلْ طَبَعَ اللَّهُ عَلَيْهَا بِكُفْرِهِمْ [النساء: ١٥٥]، وذكرَ حديث تقليب القلوب: «يا مقلّب القلوب ثبّتْ قلوبنا على دينك«."],"17":["قوله: يُخَادِعُونَ اللَّهَ أي يظنون أنهم بإظهار الإيمان وإبطان الكفر يخدعون الله.","فردَّ الله عليهم بقوله: وَمَا يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ وَمَا يَشْعُرُونَ"],"18":["قوله: فِي قُلُوبِهِمْ مَرَضٌ هو: مرض الشك والنفاق، لا مرض الجسم، وأصل المرض هو الضعف، فالمراد هنا ضعف في الدين لا ضعف في البدن.","وقوله: فَزَادَهُمُ اللَّهُ مَرَضًا أي كلما ازدادوا في شكهم ونفاقهم، ازدادوا في مرضهم."],"19":["قوله: لَا تُفْسِدُوا فِي الْأَرْضِ الفساد في الأرض: يكون بالكفر، والعمل بالمعصية، قال به جماعة من الصحابة منهم ابن مسعود وابن عباس، لأن عمارة الأرض لا تكون إلا بالطاعة.","وقوله: قَالُوا إِنَّمَا نَحْنُ مُصْلِحُونَ أي: نحن على الهدى والرشاد، فقال الله تعالى: أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ ألا: كلمة تنبيه، ينبّه بها المخاطب.أي: أنهم على الكفر والضلال والنفاق فهم مفسدون حقا وإن كانوا يدّعون أنهم يحسنون صنعاً.","وَلَكِنْ لَا يَشْعُرُونَ من جهلهم وبغضهم لله ولرسوله ولكتابه."],"20":["قوله تعالى: وَإِذَا قِيلَ لَهُمْ أي: للمنافقين الذين أظهروا الإسلام وأبطنوا الكفر فإنهم كانوا يقولون فيما بينهم لا عند المؤمنين، هل نحن نؤمن كما آمن هؤلاء السفهاء – يعني أصحاب محمد؟ فرد الله عليهم بقوله: أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ والسفيه: هو خفيف العقل، الذي يجهل مصالح نفسه، فيضرها وهذه الصفة منطبقة عليهم."],"21":["قوله: إِلَى شَيَاطِينِهِمْ: إلى بمعنى الباء أي: برؤسائهم وبكبرائهم، وهم أحبار اليهود والكفار والمشركون.والمراد بالشياطين هنا شياطين الإنس، لأن الشياطين يكونون من الإنس كما يكونون من الجن لقوله تعالى: وَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الْإِنْسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا [الأنعام: ١١٢]، وشياطين الإنس هم من يظهر أمام الناس بأنه مخلص له في عمله وقوله، وهو من أفسق الناس وأفسدهم.","وقوله: إِنَّمَا نَحْنُ مُسْتَهْزِئُونَ: أي نسخر بأصحاب محمد فنقول لهم: نحن مؤمنون كما أنتم مؤمنون.","وردّ الله عليهم بقوله: اللَّهُ يَسْتَهْزِئُ بِهِمْ: أي على وجه المقابلة لا على وجه الإطلاق، لأنه في حال المقابلة، يدل على القوة والكمال والعدل، دون حال الابتداء فإنه يدل على الذم، ولذا روي عن ابن عباس: \"يسخر بهم للنقمة منهم\".","وكذلك قوله تعالى: وَمَكَرُوا وَمَكَرَ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ [آل عمران: ٥٤] وكذلك قوله تعالى: يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ [النساء: ١٤٢] وأشباه ذلك كثير في كتاب الله.وقوله: وَيَمُدُّهُمْ: أي يملى لهم، ويمهلهم."],"22":["ضرب الله مثل المنافقين بأنهم لو كانوا مؤمنين حقا لكان مثلهم مثل الذي استوقد ناراً فأضاءت ما حوله، ولكنهم لم يؤمنوا، وإنما كفروا ونافقوا فصاروا كالذي ذهب الله بنوره فصار كل شيء له ظلمات، وفي هذه الظلمات هو مثل الصم الذي لا يسمع الخير، والبكم الذي لا ينطق بالحق، والأعمى الذي لا يبصر الحق فمهما أفهمتهم فهم لا يرجعون إليه."],"23":["الصيب: هو المطر كما جاء في الصحيح."],"24":["قوله: اعْبُدُوا رَبَّكُمُ أي وحدوا ربكم لأنه هو الخالق، فهو المستحق للعبادة وحده.","وقوله: وَأَنْزَلَ مِنَ السَّمَاءِ السماء هو كل ما علا فوقك.والمراد به هنا: السحاب. وقوله: أَنْدَادًا جمع ند، وهو نظير وشبيه."],"25":["تحدى الله في مكة والمدينة في غير موضع من القرآن أن يأتوا بمثل القرآن فقال: قُلْ فَأْتُوا بِكِتَابٍ مِنْ عِنْدِ اللَّهِ هُوَ أَهْدَى مِنْهُمَا أَتَّبِعْهُ إِنْ كُنْتُمْ صَادِقِينَ [القصص: ٤٩]","وقال: قُلْ لَئِنِ اجْتَمَعَتِ الْإِنْسُ وَالْجِنُّ عَلَى أَنْ يَأْتُوا بِمِثْلِ هَذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا [الإسراء: ٨٨]","وقال: أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ [هود: ١٣]","وقال: أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ [يونس: ٣٨].وكل هذه الآيات مكية.","وتحداهم في المدينة: وَإِنْ كُنْتُمْ فِي رَيْبٍ مِمَّا نَزَّلْنَا عَلَى عَبْدِنَا فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ","وبقي هذا التحدي قائما إلى يومنا هذا، وسيستمر إلى يوم القيامة فليس لمخلوق أن يأتي بمثل كلام الخالق؛ لأن النبي صلى الله عليه وسلم خص بهذا القرآن، وهو من أكبر الآيات البينات لنبوة محمد صلى الله عليه وسلم كما جاء في الصحيح:"],"26":["قوله: مِنْ قَبْلُ أي في الدنيا كما قال به ابن مسعود وابن عباس وغيرهما من السلف، وقول من قال: إنه في الجنة قول مرجوح.","قوله: وَأُتُوا بِهِ مُتَشَابِهًا: أي في الاسم، مع اختلاف الطعام كما جاء عن ابن عباس قال: ليس في الجنة شيء يشبه ما في الدنيا.","رواه ابن أبي حاتم في تفسيره (10/66) وابن جرير في تفسيره كلاهما من حديث الأعمش، عن أبي ظبيان، عن ابن عباس فذكره.وإسناده صحيح.","وأبو ظبيان هو حصين بن جندب.","وقيل: التشابه في ثمار الدنيا في اللون، وليس في الاسم والطعام.وقيل غير ذلك: وكله صحيح لا يعارض بعضه بعضاً فإن الآية تشمل كل هذه الوجوه.","وقوله: مُطَهَّرَةٌ: أي من الحيض، أما في بقية الأذى من البول والبراز وغيرها فهنّ مثل الرجال كما جاء في الصحيح:"],"27":["اعترض الكفار على ضرب الله المثل في قوله: مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ نَارًا وفي قوله: أَوْ كَصَيِّبٍ مِنَ السَّمَاءِ فرد الله عليهم بقوله: إِنَّ اللَّهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا لأن ضرب الأمثال من أفصح الكلام ولذا قال الله تعالى في موضع آخر: وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ [العنكبوت: ٤٣]","وقوله تعالى: إِنَّ اللَّهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا يعني يصح ضرب المثل بالصغير كما يصح بالكبير، لأن المقصود من ضرب المثل تقريب المعاني وإفهامه بغض النظر عن كونه حقيراً أو عظيماً، ولذا إذا ضرب الله مثلا يزداد المؤمن إيمانا، والكافر كفراً، والمنافق نفاقا.","وقوله: الَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ مِنْ بَعْدِ مِيثَاقِهِ أي هم المنافقون الذين أعلنوا بإسلامهم، فلما ضرب الله مثلا ارتابوا فيه، فنقضوا عهد الله وهو الإيمان بالله، وتركوا أوامره، وأفسدوا في الأرض، فهم الخاسرون في الدنيا والآخرة."],"28":["ثم أقام الله الحجة عليهم بأنهم كانوا في أصلاب آبائهم ميتين، ثم أخرجهم أحياء، ثم يميتهم موت الدنيا، ثم يحييهم حياة الآخرة، فيعترفون يوم القيامة بحياتين وميتتين كما في سورة غافر: قَالُوا رَبَّنَا أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَى خُرُوجٍ مِنْ سَبِيلٍ [غافر: ١١]"],"29":["هذا دليل آخر لعظمة الله وقدرته.وقوله: لَكُمْ: دليل على الانتفاع بما خلق الله في السموات والأرض، والله تعالى لا يمتن علينا بخلقه إلا أن يكون فيه نفع لنا، ففيه إشارة إلى الابتعاد عن كل ما فيه ضرر للإنسان سواء كان من الخبائث التي ورد تحريمها في النصوص، أو من الفساد الذي يدمر كوكب الأرض.","وقوله: ثُمَّ اسْتَوَى إِلَى السَّمَاءِ أي قصد وأقبل، لأن الاستواء إذا تعدى بـ\"إلى\" فمعناه قصد، وإذا تعدى بـ\"على\" فمعناه ارتفع كما في قوله تعالى: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف: ٥٤] وإذا ذكر بدون حرف يكون معناه الكمال والتمام كقوله تعالى عن موسى: وَلَمَّا بَلَغَ أَشُدَّهُ وَاسْتَوَى [القصص: ١٤]","وهنا ذكر بحرف \"إلى\" فمعناه إن الله بعد أن خلق لكم ما في الأرض جميعا لتنتفعوا بها قصد إلى خلق السماوات السبع مع شموسها، وأقمارها، ونجومها، وفضائها، ومن فيهنّ لتنتفعوا بها.","وقوله: وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ أي أنه يعلم احتياجكم ولذا خلق لكم ما في الأرض وما في السموات.وهنا لا يقصد الله سبحانه وتعالى أن يبين أدوار خلق الأرض والسماوات، بل المقصود فيه امتنانه على عباده بأن هذه المخلوقات خلقها الله تعالى لينتفع بها الإنسان."],"30":["هذا امتنان آخر على بني آدم بأن الله جعل في الأرض خلقا يخلف بعضهم بعضا، هذا الخلق قد يكون من جنس البشر وقد يكون من غيره كالجن والملائكة لتستمر عمارة الأرض إلى ما شاء الله.","والخليفة: من يخلف، وليس المراد فيه آدم بعينه، ولو كان هو المراد لما نسب الملائكة الإفساد وسفك الدماء إليه.","وقوله: وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ التسبيح معروف، والتقديس هو التنـزيه والتعظيم مثل قولهم: سبّوح قدوس، وهو شامل لجميع أنواع العبادة لله تعالى من خضوع وخشوع وصلاة وغيرها."],"31":["أمرَ اللهُ الملائكةَ لسجود آدم قبل خلقه كما جاء في سورة الحجر [28-29]: وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِنْ صَلْصَالٍ مِنْ حَمَإٍ مَسْنُونٍ (28) فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِنْ رُوحِي فَقَعُوا لَهُ سَاجِدِينَ (29) وكما في سورة ص [71-72] إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِنْ طِينٍ (71) فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِنْ رُوحِي فَقَعُوا لَهُ سَاجِدِينَ (72)","وأما قوله تعالى: ﴿وَلَقَدْ خَلَقْنَاكُمْ ثُمَّ صَوَّرْنَاكُمْ ثُمَّ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ لَمْ يَكُنْ مِنَ السَّاجِدِينَ﴾ [سورة الأعراف: ١١]","(ثُمَّ) الأخير للعطف، وليس للترتيب، أي أن الله يُخبرنا بأنه خلقَنا وصوَّرنا وأمرَ الملائكةَ لسجودِ آدم، وكان هذا الأمرُ قبل خلقه كما سبق في الآيات الأخرى.","وأنَّ الأمرَ للسجودِ كان للملائكة، ودخلَ فيه الجنُّ تبعًا لهم، لأنه لم يكن قبل آدم مخلوقٌ عاقلٌ غير الملائكة والجنّ، وكان إبليس من الجنّ كما جاء في سورة الكهف [50]: وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ","أي: أبى واستكبر، قَالَ لَمْ أَكُنْ لِأَسْجُدَ لِبَشَرٍ خَلَقْتَهُ مِنْ صَلْصَالٍ مِنْ حَمَإٍ مَسْنُونٍ [سورة الحجر].واحتجَّ بقوله: أَنَا خَيْرٌ مِنْهُ خَلَقْتَنِي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ طِينٍ [ص]","قوله: وَكَانَ مِنَ الْكَافِرِينَ أي أصبح من الكافرين بعد إنكاره لحكم الله تعالى."],"35":["قوله: وَإِذْ قُلْنَا ادْخُلُوا هَذِهِ الْقَرْيَةَ القرية هي الأرض المقدسة أي بيت المقدس كما جاء في سورة المائدة: يَا قَوْمِ ادْخُلُوا الْأَرْضَ الْمُقَدَّسَةَ الَّتِي كَتَبَ اللَّهُ لَكُمْ وَلَا تَرْتَدُّوا عَلَى أَدْبَارِكُمْ فَتَنْقَلِبُوا خَاسِرِينَ (21) قَالُوا يَا مُوسَى إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَنْ نَدْخُلَهَا حَتَّى يَخْرُجُوا مِنْهَا فَإِنْ يَخْرُجُوا مِنْهَا فَإِنَّا دَاخِلُونَ (22) قَالَ رَجُلَانِ مِنَ الَّذِينَ يَخَافُونَ أَنْعَمَ اللَّهُ عَلَيْهِمَا ادْخُلُوا عَلَيْهِمُ الْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَالِبُونَ وَعَلَى اللَّهِ فَتَوَكَّلُوا إِنْ كُنْتُمْ مُؤْمِنِينَ (23) قَالُوا يَا مُوسَى إِنَّا لَنْ نَدْخُلَهَا أَبَدًا مَا دَامُوا فِيهَا فَاذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ (24) [المائدة: ٢١ - ٢٤]","وقوله: سُجَّدًا: أي خاضعا وراكعا لتعذر حمله على حقيقته.","وقوله: وَقُولُوا حِطَّةٌ: أي مغفرة، روي ذلك عن ابن عباس.","أخرجه الحاكم (2/262) وقال: \"صحيح على شرط الشيخين\"."],"36":["قوله عَلَى طَعَامٍ وَاحِدٍ: أي على المنّ والسلوى، وهما وإنْ كانَ اثنين، ولكن لا يتبدّل ولا يتغيّر كل يوم فهو كطعامٍ واحدٍ.","قوله: مِنْ بَقْلِهَا وَقِثَّائِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا البقل والقثّاء والعدس والبصل كلها معروفة.","واختلف في قوله: وَفُومِهَا فقيل: هو الثوم، وكان في قراءة ابن مسعود: (وثُومها) بالثاء، وكذلك فسّره غيرُ واحدٍ من السلف. وقيل: هو الحنطة. قال ابن عباس: وَفُومِهَا قال: \"الفُوم الحنطة بلسان بني هاشم\".","والذي يظهر أن هذا هو الصواب، لأنهم قد يحتاجون إليه لصُنْعِ الطعام، فإنّ طلب البقول يستلزم طلب الحنطة، لأنّ البقولَ وحدَها لا يُصنع منها الطعامُ.","وأما الثوم –بالثاء- فهو يندرِجُ تحتَ البصل، لأنهما من فصيلٍ واحدٍ.","وقوله: اهْبِطُوا مِصْرًا أي مصرًا من الأمصار مثل أمصار فلسطين، ولكن في قراءة أُبَيّ بن كعب وابن مسعود: ((اهبطوا مصرَ)) من غير صرفٍ، والمراد منه مصر فرعون.","ولمّا لم يدخلوا مصرًا من الأمصار، ولا مصرَ فرعون فلم يُستجابوا في طلبهم، بل وبَّخَهم سبحانه وتعالى فقال: أَتَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنَى بِالَّذِي هُوَ خَيْرٌ"],"37":["في هذه الآيات إشارة واضحة إلى قصة وقعت في بني إسرائيل في عهد موسى عليه السلام، وقد روي عن بعض الصحابة والتابعين ما سمعوا من اليهود، ومن أصحها إسنادا ما روي عن عبيدة بن عمرو السلماني المخضرم المتوفى سنة (70هـ) قال: كان رجل في بني إسرائيل عقيم لا يولد له، وكان له مال كثير، وكان ابن أخيه وارثه، فقتله ثم احتمله ليلاً فوضعه على باب رجل منهم، ثم أصبح يدعيه عليهم، حتى تسلحوا وركب بعضهم إلى بعض، فقال ذوو الرأي والنُّهى: علام يقتل بعضكم بعضا، وهذا رسول الله صلى الله عليه وسلم فيكم؟ فأتوا موسى فذكروا ذلك له فقال: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً فقالوا: أتتخذونا هزوا؟ قال: أعوذ بالله أن أكون من الجاهلين.قال: فلو لم يعترضوا البقرة، لأجزت عنهم أدنى بقرة، ولكنهم شدّدوا فشدّد عليهم حتى انتهوا إلى البقرة التي أمروا بذبحها فوجدوها عند رجل ليس له بقرة غيرها، فقال: والله لا أنقصها من ملء جلدها ذهباً، فأخذوها بملء جلدها ذهباً فذبحوها فضربوه ببعضها فقام، فقالوا: من قتلك؟ فقال: هذا، لابن أخيه، ثم مال ميتاً، فلم يعط من ماله شيء، ولم يورث قاتل بعده.","رواه ابن أبي حاتم في تفسيره (1/136) عن الحسن بن محمد بن الصباح، ثنا يزيد بن هارون، أنبا هشام بن حسان، عن محمد بن زيد، عن عبيدة، فذكره."],"39":["قوله: أُمِّيُّونَ جمع أمي وهو الذي لم يتعلم القراءة والكتابة وقد جاء في الحديث."],"40":["قوله تعالى: يَكْتُبُونَ الْكِتَابَ أي اليهود والنصارى الذين كتبوا كتبهم بأيديهم ونسبوها إلى الله تعالى."],"41":["المخاطبون هم اليهود"],"42":["وسبب زعم اليهود بأن جبريل عدوٌّ لهم: أنهم كانوا يرون أن جبريل كان يأتي بالعذاب كلما خالفوا أمر الله، وكان دائما مع أعدائهم في حروبهم، فكان سببا لهزيمتهم، فردَّ اللهُ على افتراءاتهم بقوله: قُلْ مَنْ كَانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ بِإِذْنِ اللَّهِ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَى لِلْمُؤْمِنِينَ كيف يكون جبريلُ عدوًّا لهم مع أنه لا ينزل إلا بإذن الله، والكتاب الذي نزل به على محمّد يصدّق كتابهم الذي عندهم، وفيه هدى وبشرى للمؤمنين."],"43":["قوله: هَارُوتَ وَمَارُوتَ: هما ملكان في رأي جمهور أهل العلم، وكانا يعلّمان الناسَ السحرَ امتحانًا لهم مع بيان قبحه، بأنه يفرّق بين المرء وزوجته، فوجدا أن كثيرا من الناس مقبلين على تعليم السحر، ولم يكن من قصدهما تعليم السحر وممارسته، فإن ذلك من عمل الشيطان، وقد أخبرا نحن فتنة، ولكن الناس لم ينتهوا، فبدؤوا يتعلمون منهما ما يفرّقون به بين المَرْءِ وزوجتِه.","وقد رويت أحاديث كثيرة في قصة هاروت وماروت ولا يصح منها شيء.","ومن أشهرها ما رواه الإمام أحمد (6178)، والبزار –كشف الأستار (2938) وابن حبان (6186) والبيهقي (10/4-5) كلهم من حديث يحيى بن أبي بكير، عن زهير بن محمد، عن موسى بن جبير، عن نافع، عن ابن عمر أنه سمع نبي الله صلى الله عليه وسلم يقول: ((إن آدم لما أهبطه الله تعالى إلى الأرض، قالت الملائكة: أي رب، أتجعل فيها من يفسد فيها ويسفك الدماء، ونحن نسبح بحمدك ونقدس لك؟ قال: إني أعلم ما لا تعلمون، قالوا: ربنا نحن أطوع لك من بني آدم، قال الله تعالى للملائكة: هلموا ملكين من الملائكة، حتى يهبط بهما إلى الأرض، فننظر كيف قالوا: ربنا، هاروت وماروت، فأهبطا إلى الأرض، ومثلت لهما الزهرة امرأة من أحسن البشر، فجاءتهما، فسألاه نفسها، فقالت: لا والله، حتى تكلما بهذه الكلمة من الإشراك، فقالا: والله لا نشرك بالله أبداً، فذهبت عنهما، ثم رجعت بصبي تحمله، فسألاها نفسها، فقالت: لا والله حتى تقتلا هذا الصبي، فقالا: والله لا نقتله أبداً، فذهبت، ثم رجعت بقدح خمر تحمله، فسألاها نفسها، فقالت: لا والله حتى تشربا هذا الخمر، فشربا، فسكرا، فوقعا عليها، وقتلا الصبي، فلما أفاقا، قالت المرأة: والله ما تركتما شيئاً مما أبيتماه علي إلا قد فعلتما حين سكرتما، فخيرا بين عذاب الدنيا والآخرة، فاختارا عذاب الدنيا.","وموسى بن جبير هو الأنصاري ذكره ابن أبي حاتم في الجرح والتعديل (8/139) ولم يقل فيه شيئا، وذكره ابن حبان في ثقاته (7/451) وقال: \"يخطئ ويخالف\".","وقال البزار: \"رواه بعضهم عن نافع، عن ابن عمر موقوفا، وإنما أتى رفع هذا الحديث عندي من زهير لأنه لم يكن بالحافظ\".","قلت: وهو كذلك؛ فإن الثقات لم يرفعوه، وزهير بن محمد هو: التميمي أبو المنذر، ضعّفه النسائي، وقال الحاكم: في حديثه بعض المناكير، ووثّقَه الآخرون.وقد جاء موقوفا أيضا عن كعب الأحبار، وهو ما رواه عبد الرزاق في تفسيره (97) عن الثوري، عن موسى بن عقبة، عن سالم، عن ابن عمر، عن كعب الأحبار نحوه.","والخلاصة فيه كما قال الحافظ ابن كثير في تفسيره: \"وقد روي في قصة هاروت وماروت عن جماعة من التابعين كمجاهد، والسدّي، والحسن البصري وقتادة وأبي العالية والزهري والربيع بن أنس ومقاتل بن حيان وغيرهم\".","وقصّها خلقٌ من المفسرين من المتقدمين والمتأخرين، وحاصلها راجع في تفصيلها إلى أخبار بني إسرائيل، إذْ ليس فيها حديث مرفوع صحيح متصل الإسناد إلى الصادق المعصوم الذي لا ينطق عن الهوى، وظاهر سياق القرآن إجمال القصة من غير بسط، ولا إطناب فيها، فنحن نؤمن بما ورد في القرآن الكريم على ما أراده الله تعالى، والله أعلم بحقيقة الحال\" اهـ.","وقوله: وَمَا كَفَرَ سُلَيْمَانُ أي لم يتعلم السحر ولم يعلمه الناس.","وقوله: وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا أي بتعليمهم السحر لإضلالهم وإغوائهم.","وقوله: وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ أي وكذلك أخذ اليهود السحر من الملكين هاروت وماروت مع أنهما قالا: إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ أي أن الله جعلَنا لكم فتنة فلا تأخذوا منا السحر، ولكن لم يسمعوا، بل أخذوا منهم ما يفرّقون به بين المرء وزوجه.","وبهذا ظهر أن اليهود كانوا قد أخذوا السحر من الشياطين الذين همّهم الإضلال والإفساد كما أخذوا السحر من الملكين الكريمين امتحانا لتوافقه بأهوائهم وتركوا تعاليم الأنبياء والرسل.","ولذا قال الله تعالى: وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ","وقد أكثر المفسرون من ذكر الإسرائيليات في هذا المقام وفي أكثرها غرابة ونكارة كما بيّنها أهل العلم، وليس فيها شيء ثابت عن النبي صلى الله عليه وسلم، ولذا أعرضتُ عن ذكرها."],"45":["نهى الله سبحانه وتعالى في هذه الآية الكريمة عن كثرة سؤال النبي صلى الله عليه وسلم عن الأشياء قبل وقوعها كما قال الله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ [المائدة: ١٠١]"],"48":["قوله: مَثَابَةً لِلنَّاسِ أي يثوبون، روى ابن أبي حاتم (1191) بإسناده عن ابن عباس قال: يثوبون إليه، ثم يرجعون.","قلت: هو من ثاب يثوب ثوبا وثوبانا، رجع بعد ذهابه.","ومثابة – يعني مرجعا، فإن الحجاج والمعتمرين يتفرقون عنه، ثم يثوبون إليه.","وقوله: مَقَامِ إِبْرَاهِيمَ هو الحجر الذي عليه أثر قدميه."],"49":["الْقَوَاعِدَ جمع قاعدة وهي الأساس."],"50":["قوله: رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِنْهُمْ أي من بني إسماعيل، وهو نبينا محمد صلى الله عليه وسلم فإنه لم يبعث من بني إسماعيل غيره، كما لن يُبعث بعده أحد إلى يوم القيامة."],"51":["قوله تعالى: نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَهًا وَاحِدًا وإسماعيل عليه السلام كان عما ليعقوب وقد تسمي العرب العم أباً، لأنه بمنزلة الأب، وصحّ ذلك في الحديث الآتي:"],"54":["قلت: لا تزال النصوص في العهد القديم تؤكّد على خروج نبي يكون وصفه كذا، ولايكون من إخوتهم الأشقّاء، ففي سفر التثنية، الإصحاح 18 الفقرة (18): أني أقيم لهم نبيا من وسط إخوتهم مثلك، وأجعل كلامي في فمه، فيكلمكم بكل ما أوصيه به.","وقوله: إخوتهم أي: من بني إسماعيل، وليس من بني إسحاق.","وقوله: مثلك أي: مثلك في الشريعة الكاملة، وليس بين موسى عليه السلام وبين نبينا محمد صلى الله عليه وسلم نبيٌّ جاء بالشريعة الكاملة، وأما عيسى عليه السلام فكان على شريعة التوراة.","وفي سفر التثنية أيضا الإصحاح 33 الفقرة: 2: قال: جاء الرب من سيناء، وأشرق من سعير، وتلألأ من جبل فاران.","وفي هذه الفقرة ذكر ثلاثة من الأنبياء، كلّم الله موسى في سيناء، ووُلدَ عيسى عليه السلام في سعير وهو جبل في فلسطين، ووُلدَ النبي صلى الله عليه وسلم في فاران وهو اسم جبل بمكة.","وقد ذكرتُ فقراتٍ كثيرةً من العهدين القديم والجديد في كتابي: \"دراسات في اليهودية والمسيحية\".","يروى عن عمر بن الخطاب أنه قال لعبد الله بن سلام: أتعرفُ محمدًا كما تعرف ولدك؟ قال: نعم وأكثر، نزل الأمين من السماء على الأمين في الأرض بنعته فعرفته، وإني لا أدري ما كان من أمه.","وقوله: وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ والكتمان إما كان بالإخفاء أو بالتغيير الخاطئ."],"58":["قوله: أَنْدَادًا: واحدها ندّ أي: شركاء."],"60":["قوله: الْمَيْتَةَ وَالدَّمَ: عام يشمل كل ميتة ودم، ولكن استثني من الميتة: السمك والجراد، ومن الدم: الكبد والطحال، فإنها حلال."],"61":["قوله تعالى: وَآتَى الْمَالَ عَلَى حُبِّهِ ذَوِي الْقُرْبَى"],"66":["قوله تعالى: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ"],"68":["فيه رخصة للمسلمين ورفع الحرج الذي كان في ابتداء الإسلام فإنه إذا كان أحدهم أفطر يحل له الأكل والشرب والجماع إلى صلاة العشاء أو ينام قبل ذلك، فمتى نام أو صلى العشاء حرم عليه الطعام والشراب والجماع إلى الليلة القابلة فوجدوا في ذلك مشقة كبيرة فرفع الله هذه المشقة."],"74":["قوله تعالى: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ"],"75":["قوله تعالى: فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ"],"84":["هذه حكاية عن الأمم السابقة.","والبأساء: الفقر، والضراء: السقم"],"86":["نزلَ الحكمُ في الخمر في ثلاث مراحل:","المرحلة الأولى:","قوله تعالى: يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِنْ نَفْعِهِمَا وَيَسْأَلُونَكَ مَاذَا يُنْفِقُونَ قُلِ الْعَفْوَ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ [البقرة: ٢١٩]","قوله: \"منافع للناس\" أي فيه تجارة نافعة، والطربُ للنفوس عند شُرْبها، وإنْ كان إثمُها أكبرُ لوقوع العداوة والبغضاء بين الناس كما نصَّ اللهُ سبحانه وتعالى في سورة المائدة.","والمرحلة الثانية:","قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ [النساء: ٤٣] فكان الناسُ يشربون الخمر في غير أوقات الصلاة.","والمرحلة الثالثة:","قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ (90) إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ (91) [المائدة: ٩٠ – ٩١]","قال عمر بن الخطاب رضي الله عنه: انتهينا انتهينا.كما عند أحمد (378).","وفي هذه الآية تصريح في تحريم الخمر إلى الأبد، ولو نزل تحريم الخمر في المرحلة الأولى لقال بعضُ الناس: لا ندعُ الخمرَ."],"87":["قوله: أَذًى هو قذر.","وقوله: أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ أي من الجماع دون إخراجهن من البيوت.","وقوله: حَيْثُ أَمَرَكُمُ اللَّهُ يعني الفرج دون الدبر.","ويقال: إن السائل الذي سأل رسول الله صلى الله عليه وسلم عن ذلك كان ثابت بن الدحداح الأنصاري."],"88":["قوله: حَرْثٌ أي موضع الولد.","وقوله: فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ أي كيف شئتم مقبلة ومدبرة إذا كان في صمام واحد.وفيه رد على اليهود كما جاء في حديث جابر الآتي:"],"89":["هذا أمر من الله سبحانه وتعالى للمطلقات المدخول بهن من ذوات الأقراء، وبعد ثلاثة قروء إن شاءت تتزوج ولا حرج عليها وهي للحرة بخلاف الأمة فإن عدتها قُرْءان على أصح أقوال اهل العلم، وشذَّ بعضهم فقالوا: حكمها حكم الحرة لعموم الآية.","ووقع الخلاف في المراد بالأقراء.","فذهب جمهور أهل العلم إلى أنه الحيض، ورُوي فيه عن فاطمة بنت أبي حبيش أنها سألتْ رسول الله صلى الله عليه وسلم، فشكتْ إليه الدمَ فقال لها رسول الله صلى الله عليه وسلم: إنما ذلك عرق فانظري إذا أتى قُرْؤُكِ فلا تصلّي، فإذا مرَّ قُرْؤُكِ فتطهري، ثم صلّيْ ما بين القُرْء إلى القُرْءِ.","رواه أبو داود (280) وفيه المنذر بن المغيرة مجهول ليس بمشهور كما قال أبو حاتم، وهذا وإنْ لم يصح ولكن يُستأنس به.","وذهب مالك وأكثر أهل المدينة أن المراد به الأطهار.","وقال أهل اللغة: القُرْء هو الوقت، فهو شامل للاثنين الحيض والطهر، وإنما الخلاف في المراد من الآية ما هو على القولين، ولكلٍّ أدلة وموضعه كتب الفقه.","قوله تعالى: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ","أي لكل واحد من الرجل والنساء حقوق وواجبات وإليه أشار النبي صلى الله عليه وسلم في خطبة الحج."],"91":["قوله: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ","هذا إرشادٌ من الله تعالى للوالدات: أن يُرْضِعْنَ أولادَهُنَّ سنتينِ كاملتينِ.","ويجوزُ للأمِّ أن تستمرَّ على إرضاع ولدِها بعد السنتين حتى ينتهي منها اللبنُ، أو يستغني منه الرضيع، والعادة أنَّ غالبَ النساءِ ينتهي منهن اللبن قبل إكمال السنة الثالثة.","وقوله: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا","أي يجوز النقصُ من إرضاعِ السنتين إذا لم يَلْحَقْ بالطفلِ ضَرَرٌ.","فِصَالًا أي فطامًا، يعني إذا بدأ الطفلُ يعيشُ على غير اللبن.","وفي الآية الكريمة إشارةٌ إلى أنَّ مدّة استحقاق الأجرة على الرضاعة هي سنتان فقط، فمتى أتمَّ الطفلُ حولين كاملين لم يكن للمرضع الأمّ الحقُّ في المطالبة بأجرة الرضاعة بعد السنتينِ، لأنّ الوجوبَ في مُدّة الرضاعةِ هي سنتان فقط.","وفي الآية أيضا إشارةٌ إلى أنّ المُحَرِّمَ من الرضاعة ما كان حولين كاملين، أو دونهما، فإنْ ارتضعَ المولودُ وعمرُه فوق سنتين، لم يُحَرِّم عند أكثر أهل العلم.","وقال أبو حنيفة: إنَّ مدّةَ الرضاعةِ سنتانِ ونصف سنة، أي ثلاثون شهرًا لاحتياج الطفلِ إلى هذه المدة للتدرّجِ من اللبن إلى الطعامِ المعتادِ، وتفصيلُ ذلك في كتابِ الرضاعةِ."],"92":["لا خلاف بين أهل العلم أن المرأة المتوفى عنها زوجها سواء كانت مدخولة أو غير مدخولة عدتها أربعة أشهر وعشراً.","أما المدخول بها فهي المقصود من الآية، ويلحق بها غير المدخول بها لعمومها."],"93":["قوله تعالى: وَالصَّلَاةِ الْوُسْطَى هي صلاة العصر."],"94":["قوله: فَرِجَالًا أَوْ رُكْبَانًا أي مستقبلي القبلة وغير مستقبليها."],"95":["قال أكثر المفسرين إن هذه الآية منسوخة نسختها الآية وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا المتقدمة في ترتيب المصحف، فلماذا كتبت الآية المنسوخة؟ قد أشكل ذلك على بعض أهل العلم."],"96":["في الآية الكريمة إشارة إلى قصة وقعت في بني إسرائيل حيث وقع فيهم وباء شديد، قيل: إنه الطاعون، فخرجوا فرارا من الموت إلى مكان ظنوا أنهم آمنون فيه، فأماتهم الله جميعا، فعوملوا بنقيض قصدهم وجاءهم الموت سريعا في آن واحد ولم ينفعهم الفرار من الموت، ومن هذا القبيل ما جاء في الحديث الصحيح الآتي:"],"97":["طالوت: هو رجل من جنود ملك من ملوك بني إسرائيل، ولم يكن سبط يهوذا الذي كان فيهم الملك، وكان عدد جنوده الذي جاوزوا معه النهر على عدد أصحاب بدر كما جاء في الصحيح:"],"99":["ومعنى السنة: النعاس، وهو أول النوم."],"108":["قوله: لِلْفُقَرَاءِ الَّذِينَ أُحْصِرُوا وهم المهاجرون.","وقوله: ضَرْبًا أي سفرا لطلب الرزق، لأنهم هاجروا إلى الله ورسوله إلى المدينة، ولا يرغبون أن يسافرون منها إلى بلد الكفر والشرك.","وقوله: يَحْسَبُهُمُ الْجَاهِلُ أي لحالهم وشؤونهم لعدم سؤالهم."],"109":["قوله: لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ أي لا يقومون من قبورهم يوم القيامة إلا حال كونهم تتخبطهم الشياطبن من المس.","وقال ابن عباس: آكل الربا يبعث يوم القيامة مجنونا يخنق.","وقال أيضا: يقال يوم القيامة لآكل الربا: خذ سلاحك للحرب، وقرأ: لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ قال: وذلك حين يقوم من قبره."],"110":["قوله: بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ أي مواجهة الله ورسوله.","وروي عن ابن عباس قال: يقال يوم القيامة لآكل الربا: خذ سلاحك للحرب.","وقوله: وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ هذا أصل في البيوع الفاسدة فإن الضمان فيه هو أصل المال لا الربح، ولذا وضع النبي صلى الله عليه وسلم ربا الجاهلية، وأمرهم بأخذ رأس المال كما جاء في حديث جابر عند مسلم وغيره."],"111":["قوله: إِلَى مَيْسَرَةٍ أي اليسر.","فيه الترغيب في الصبر على المعسر الذي لا يجد وفاءً."],"114":["قوله: عَلَى سَفَرٍ مسافرين، والسفر ليس بشرط في الرهن، وإنما خرج الكلام في الآية مخرج الغالب، لعدم وجود المكاتب وأدوات الكتابة، وإلا فإن الرهن يجوز أيضا في الحضر، كما ثبت في الصحيح.","قال ابن عباس: أو وجدوه، ولم يجدوا قرطاساً أو دواة أو قلماً فرهن مقبوضة.","وقوله: فَرِهَانٌ مَقْبُوضَةٌ أي إن الرهن لا يلزم إلا بالقبض وهو رأي جمهور أهل العلم."],"115":["لما نزلت هذه الآية اشتد ذلك على أصحاب رسول الله صلى الله عليه وسلم كما جاء في الحديث الآتي:"],"117":["أي: أن آيات الله منها المحكم مثل الأوامر والنواهي، وأخبار الماضين، وقصص الأنبياء، وخلق السموات والأرض وغيرها.وهذا مما يعلمه جميعُ من خوطبوا بالقرآن، وهنّ أم الكتاب في معرفة أصول الدين وأحكامه وجاء في سورة القمر [17]: لَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ","ومنها المتشابه الذي يشتبهُ حكمه على البعض دون البعض، فإذا عُطِفَ على الله وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ وَالرَّاسِخُونَ فِي الْعِلْمِ فمعناه أن المتشابه أيضا يعلم تأويلَه وتفسيرَه مَنْ منحهم اللهُ ذهنًا ثاقبًا، وفهمًا سليمًا، والكتابُ والسنّةُ وأقوالُ السلف تدلّ على أن جميع القرآن مما يمكن علمُه وفهمُه وتدبّره، فإنّه لا يجوز أن ينزّل الله كتابًا لا يعلم معناه، وكان ابن عباس رضي الله عنهما يقول: أنا من الراسخين الذين يعلمون تأويله.","وقد ثبت تفسيرجميع القرآن من السلف والخلف.","وقوله: كُلٌّ مِنْ عِنْدِ رَبِّنَا","أي المحكم والمتشابه، ولكن حقيقة الشيء وكُنْهه علمُها عند الله، والراسخون في العلم لا يخوضون فيها، ففي هذه الحالة يجب الوقفُ على إِلَّا اللَّهُ مثل حقيقة صفات الله تعالى، وكيفيّتها، وحقيقة صفة الجنة والنار، وحقيقة أهوال يوم القيامة وغيرها من الغيبيات التي لا تُدرك بالحواسّ الموجودة لدى الإنسان.","وقد سئل الإمام مالك عن قوله تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه: ٥]","فقال السائل: كيف استوى؟ فقال مالك: \"الاستواءُ معلومٌ، والكيفُ مجهولٌ، والإيمانُ به واجبٌ، والسؤالُ عنه بدعةٌ\".","هكذا يقال في سائر الصفات والغيبيات.","ولكن أهل الزيغ والضلال يُثيرون الفتنة باتّباعهم المتشابهات وتفسيرها، وإخراجها عن المعنى الصحيح إلى المعنى الذي يريدونه من التشبيه، والتحريف، والتكييف، والتأويل، والتعطيل، ويخالفون في ذلك الراسخين في العلم من أهل السنة والجماعة الذين يجعلون حقيقة الأمر وكيفيّتها إلى الله سبحانه وتعالى.","وعن هولاء قال النبي صلى الله عليه وسلم كما في الحديث الآتي:"],"119":["قتل الأنبياء من الكبائر.","وأما ما روي عن أبي عبيدة بن الجراح قال: قلت: يا رسول الله، أي الناس أشد عذابا يوم القيامة؟ قال: ((رجل قتل نبيا، أو رجل أمر بالمنكر، ونهى عن المعروف))، ثم قرأ رسول الله صلى الله عليه وسلم: إِنَّ الَّذِينَ يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ الَّذِينَ يَأْمُرُونَ بِالْقِسْطِ مِنَ النَّاسِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ إلى قوله: وَمَا لَهُمْ مِنْ نَاصِرِينَ ثم قال رسول الله صلى الله عليه وسلم: ((يا أبا عبيدة! قتلت بنو إسرائيل ثلاثة وأربعين نبيا، من أول النهار في ساعة واحدة، فقام مائة وسبعون رجلا من بني إسرائيل، فأمروا من قتلهم بالمعروف ونهوهم عن المنكر، فقتلوا جميعا من آخر النهار من ذلك اليوم، فهم الذين ذكر الله عز و جل)) فهو ضعيف.","رواه ابن جرير في تفسيره (5/291)، والبزار (1285)، وابن أبي حاتم (2/620) كلهم من طريق محمد بن حمير، حدثني أبو الحسن مولى لبني أسد، عن مكحول، عن قبيصة بن ذؤيب الخزاعي، عن أبي عبيدة بن الجراح، فذكره.","وقال البزار: \"لا نعلم له عن أبي عبيدة غير هذه الطريق، ولم نسمع أحدا سمى أبا الحسن هذا الذي روى عنه محمد بن حمير\" يعني: أبو الحسن مجهول.","تنبيه: تحرف \"محمد بن حمير\" في تفسير ابن أبي حاتم إلى \"محمد بن حمزة\"."],"120":["قوله: إِلَّا أَنْ تَتَّقُوا مِنْهُمْ تُقَاةً أي: فله أن يتقيهم بظاهره لا بباطنه، كما حكاه البخاري في الأدب باب المداراة مع الناس، عن أبي الدرداء أنه قال: إنا لنكشر في وجوه أقوام وقلوبنا تلعنهم.","وقال ابن عباس: ليس التقية بالعمل، وإنما التقية باللسان.","وقال البخاري: قال الحسن: التقية إلى يوم القيامة."],"121":["عمران: هو والد مريم، وكان اسم والد موسى وهارون أيضا عمران، فلعله سمى به تيمّنا، كما أن امرأة عمران سمّت المولودة باسم مريم تيمّنا بتسمية أخت موسى وهارون.","قوله: مُحَرَّرًا أي: مخلصا ومفرغا للعبادة، ولخدمة بيت المقدس.","وقوله: إخبارا عن أم مريم: وَإِنِّي أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ الشَّيْطَانِ الرَّجِيمِ فاستجاب الله دعاءها كما جاء في الحديث الصحيح:"],"122":["قوله: نَبَاتًا حَسَنًا أي: في بدنها وخلقها.","وقوله: وَكَفَّلَهَا زَكَرِيَّا لا لفقرها كما يقال، بل لأن زكريا عليه السلام كان إمام بيت المقدس، فصار كفيلا لها ومسئولا عنها، ثم هو زوج خالتها.","وقوله: وَجَدَ عِنْدَهَا رِزْقًا أي: بدون اكتساب وسعي منها.","وقوله: قَالَتْ هُوَ مِنْ عِنْدِ اللَّهِ أي: كرامة ومعجزة."],"123":["أي لما رأى زكريا أن الله يرزق مريم بدون سعي منها طمع في الولد، وكان شيخا كبيرا، فدعا ربه.","وقوله: ذُرِّيَّةً طَيِّبَةً أي: ولدا صالحا، له ذرية ونسل وعقب.","وقوله: وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِنَ الصَّالِحِينَ سيدا أي: متقدما في العبادة والصلاح. وقوله: وَحَصُورًا أي: مشغولا بالعبادة، ولم يجد فرصة للزواج ليكون له نسل وعقب.","وأما تفسير أنه لا يشتهي النساء، أو أنه غير قادر على النكاح، أو أنه لا ذكر له، أو كان ذكره مقطوعا، أو كان مثل التراب، أو مثل هدبة الثوب، أو مثل الأنملة، فهذا كله عيب، وإنما يكون الفضل إذا كان قادرا عليه، ثم اختار لنفسه الاشتغال بالعبادة ومجاهدة النفس.فلم يجد فرصة للزواج إلى أن استشهد، لأن الله وصفه بهذين الوصفين في مقام المدح، لا مقام النقص والذم.","قوله تعالى: وَيُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلًا وَمِنَ الصَّالِحِينَ"],"124":["أي كان عيسى عليه السلام دعا إلى التوراة التي أنزلها الله تعالى على موسى عليه السلام، وإلى الإنجيل الذي أنزله الله تعالى على عيسى عليه السلام، فكانت دعوته خالصة لبني إسرائيل دون غيرهم، خلافا لما يدعيه النصارى بأن دعوته كانت عامة للناس جميعا."],"125":["قوله: مُتَوَفِّيكَ: أوفي أجلك في الدنيا.","وقوله: وَرَافِعُكَ إِلَيَّ أي: رافعك بعد استيفاء أجلك في الدنيا إليَّ حيا، وهو ثلاث وثلاثون سنة.","هذا رأي جمهور أهل العلم بأن الله تعالى رفع عيسى عليه السلام حيا إلى السماء قبل أن يصل إليه قومُه، وشُبّه لهم الاسخريوطي فصلبوه.لأن الله تعالى قال في سورة النساء: بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ [النساء: ١٥٨] أي: رفعه حيّا.","وقال ابن عباس: إِنِّي مُتَوَفِّيكَ أي: مميتك.","وقال غيره من أهل العلم: إنه توفاه الله بعد ثلاث ساعات، أو ثلاثة أيام، أو سبع ساعات، ثم أحياه الله تعالى، ورفعه إليه حيا.","وهذه الأقوال فيه محاكاة للنصارى الذين يزعمون أنه بعد الصلب دفن، ثم قام من قبره بعد ثلاثة أيام، وبقي يلتقي بتلاميذه أربعين يوما، ثم رفع إلى السماء.","ونقل ابن كثير عن الأكثر: أن المراد بالوفاة هاهنا النوم، كما قال الله تعالى: وَهُوَ الَّذِي يَتَوَفَّاكُمْ بِاللَّيْلِ وَيَعْلَمُ مَا جَرَحْتُمْ بِالنَّهَارِ [الأنعام: ٦٠] وقال تعالى: اللَّهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَى عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَى إِلَى أَجَلٍ مُسَمًّى إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ [الزمر: ٤٢]","وقوله: وَمُطَهِّرُكَ مِنَ الَّذِينَ كَفَرُوا أي: رفعي إياك إلى السماء من اليهود الذين أرادوا إذلالك وإهانتك."],"126":["نزلت هذه الآيةُ في وفد نجران، فإنهم لما قدموا جعلوا يُحاجّون في عيسى، ويزعمون فيه ما يزعمون من البُنُوّة والألوهية، فأمرَ اللهُ رسولَه أن يُباهلَ من عاندَ الحقَّ، فتولّوا وأعرضوا ونكلوا، وعلموا أنهم إن لاعنوه رجعوا إلى أهليهم وأولادهم فلم يجدوا أهلاً ولا مالاً.","والمباهلةُ في اللغة: مِنْ باهلَه مباهلةً، لَعنَ كلٌّ منهما الآخرَ."],"133":["قال مجاهد يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا فَرِيقًا مِنَ الَّذِينَ أُوتُوا الْكِتَابَ قال: كان جماع قبائل الأنصار بطنين: الأوس والخزرج، وكان بينهما في الجاهلية حرب ودماء وشنآن، حتى منَّ الله عليهم، وألف بينهم بالإسلام.قال: فبينا رجل من الأوس ورجل من الخزرج قاعدان يتحدثان ومعهما يهودي جالس، فلم يزل يذكرهما بأيامهما والعداوة التي كانت بينهم حتى استبا ثم اقتتلا.قال: فنادى هذا قومه وهذا قومه، وخرجوا بالسلاح، وصف بعضهم لبعض، قال: ورسول الله صلى الله عليه وسلم يومئذ شاهد بالمدينة، فجاء رسول الله صلى الله عليه وسلم فلم يزل يمشي بينهم إلى هؤلاء وهؤلاء ليسكنهم حتى رجعوا ووضعوا السلاح، فأنزل الله تعالى في ذلك القرآن: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تُطِيعُوا فَرِيقًا مِنَ الَّذِينَ أُوتُوا الْكِتَابَ يَرُدُّوكُمْ بَعْدَ إِيمَانِكُمْ كَافِرِينَ.","رواه ابن أبي حاتم في تفسيره (3/719) عن الحسن بن أبي الربيع، أنبأ عبد الرزاق، أنبأ جعفر بن سليمان، عن حميد الأعرج، عن مجاهد، فذكره."],"135":["فيه أمر من الله تعالى بتكوين جماعة من العلماء والدعاة عملهم الأمر بالمعروف والنهي عن المنكر، وهو من وظيفة الحاكم، كما قال الله سبحانه وتعالى: الَّذِينَ إِنْ مَكَّنَّاهُمْ فِي الْأَرْضِ أَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ وَلِلَّهِ عَاقِبَةُ الْأُمُورِ [الحج: ٤١] وقد اهتم حكام المسلمين من فجر التاريخ بنصب الحسبة استجابة للنداء الرباني."],"137":["قوله: لَيْسُوا سَوَاءً أي: أهل الكتاب كلهم ليسوا سواء، بل فيهم الفسقة الفجرة، كما سبق قوله تعالى: مِنْهُمُ الْمُؤْمِنُونَ وَأَكْثَرُهُمُ الْفَاسِقُونَ [آل عمران: ١١٠]، وفيهم من آمن بالله ورسوله واليوم الآخـر مثل عبد الله بن سلام، وأسد بن عبيد، وثعلبة بن سعد، وأسيد بن سعية، وغيرهم، فوصفهم الله تعالى بقوله: يَتْلُونَ آيَاتِ اللَّهِ آنَاءَ اللَّيْلِ وَهُمْ يَسْجُدُونَ فيه بيان لصلاتهم في أوقات الليل وطول تهجدهم وتلاوتهم لكتاب الله إلى آخر ما ذكر من أوصافهم.","وقوله: مِنْ أَهْلِ الْكِتَابِ أي: أي كانوا من أهل الكتاب، والآن هم مسلمون، وروي فيه عن ابن عباس نحوه، رواه ابن إسحاق، قال: حدثني محمد بن أبي محمد، عن عكرمة أ و سعيد بن جبير، عن ابن عباس، فذكره.","رواه ابن أبي حاتم في تفسيره، وابن جرير في تفسيره (5/691).","وشيخ ابن إسحاق مجهول."],"138":["قوله: بِطَانَةً أي: خاصة، وفيه نهي عن تولية غير المسلمين أعمالا حساسة في دولة الإسلام، لأنهم كما قال تعالى: لَا يَأْلُونَكُمْ خَبَالًا لا يتركون فرصة لضرركم سواء من أنفسهم أو من مساعدة الأعداء عليكم."],"139":["المراد بهذه الوقعة يوم أحد، وقيل: الأحزاب، والأول أصح، وبه قال ابن عباس وغير واحد من التابعين.","قوله: تُبَوِّئُ الْمُؤْمِنِينَ مَقَاعِدَ لِلْقِتَالِ أي: ترتبهم ميمنة وميسرة، وتجهزهم للقتال.","وقوله: إِذْ هَمَّتْ طَائِفَتَانِ مِنْكُمْ أَنْ تَفْشَلَا وَاللَّهُ وَلِيُّهُمَا"],"143":["غَلَّ يغُلُّ غُلولاً معناه: خانَ يخونُ خيانةً يعني: ما كان لنبيٍّ أن يخونَ أمّته سواء في التوجيه والإرشاد أو في الغنيمة، فيه ردٌّ على المنافقين الذين خرجوا مع المسلمين إلى غزوة أُحُد، ثم انصرفوا من وسط الطريق، فلما وقعت الهزيمةُ للمسلمين قال المنافقون: نحن نصحنا محمدًا وأصحابَه أن لا يخرجوا من المدينة للقتال، ولكنهم لم يقبلوا نصيحتنا، وأن محمدًا خان أمته، وجعلهم يهلكون، فردَّ الله عليهم بأن الأنبياء لا يخونون أمتهم، لأن الغلول منتفٍ عن الأنبياء وأخلاقهم، ولأن ذلك جرم عظيم، ومن يغلل يأت بما غلَّ يوم القيامة سواء في التوجيه والإرشاد أو في الغنيمة، والأنبياء عليهم السلام لا يأتون مثله.","وما وقع في غزوة أُحد سببُه أن أصحابَه خالفوا أمر النبي صلى الله عليه وسلم ، وهذا التفسير يناسبُ سياق الآية الكريمة، فإنها تُحدّث عن غزوة أُحُدٍ.","وأما ما رواه أبو داود(3971)، والترمذي (3009) أنّ قطيفة حمراء فُقدتْ يوم بدر فقال بعضُ الناس: لعلّ رسولَ الله صلى الله عليه وسلم أخذها، فأنزل الله تعالى: وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ.","فهو مع جودة إسناده بالمتابعات، في متنه نكارة، فإنّ ذكرَ بدر في سياق آية أُحُد لا معنى له، علاوة على ذلك ففي إسناده خُصيف وهو ابن عبد الرحمن ضعيف.","ورواه ابن مردويه من طريق أبي عمرو بن العلاء، عن مجاهد، عن ابن عباس قال: اتّهمَ المنافقون رسول الله صلى الله عليه وسلم بشيءٍ فُقِدَ فأنزل الله عزوجل: وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ.","وهذا يقوّي ما قبله مع اضطراب في معناه، ولكن فيه ذكر للمنافقين الذين قالوا: إن محمدًا غلّ، ومن المعلوم أن المنافقين لم يكونوا من أصحاب بدر، بل لقد ورد في الحديث القدسي أن النبي صلى الله عليه وسلم قال: «لعلّ اللهَ قد اطَّلعَ على من شهِدَ بدرًا، فقال: اعملوا ما شئتم، فقد غفرتُ لكم».متفق عليه.البخاري (4274) ومسلم (2494).","وأما أصحابُ محمد صلى الله عليه وسلم فمن المستبعد أن يتّهموا النبيَّ صلى الله عليه وسلم بالخيانة في التوجيه والنصح وغنيمة المال، فالصحيح في تفسير الآية ما ذكرتُه.والله تعالى أعلم."],"156":["المرابطة لها معنيان:","أحدهما: المداومة على العبادة، والثبات عليها، مثل انتظار الصلاة بعد الصلاة كما جاء في الصحيح:"],"158":["قوله: وَخَلَقَ مِنْهَا زَوْجَهَا وهي حوّاء."],"160":["النحلة: هي الفريضة من المهر، يدفعها الرجل إلى المرأة، عن طيب نفس، كما يمنح المنيحة، فإن طابت هي بعد تسميته، وأذنت له أن يأكل منه شيئا فلا بأس بذلك لقوله تعالى: فَإِنْ طِبْنَ لَكُمْ عَنْ شَيْءٍ مِنْهُ نَفْسًا فَكُلُوهُ هَنِيئًا مَرِيئًاز","والأحاديث الواردة في ذلك لا تصح، منها ما رواه ابن أبي حاتم في تفسيره (3/860) عن أبي صالح قال: كان الرجل إذا زوج ابنته أخذ صداقها دونها فنهاهم الله عن ذلك، ونزلت هذه الآية. وهو مرسل."],"163":["يعني كما أن الذي يترك وراءه ذرية ضعافا يخاف عليهم فكذلك إنْ ولي اليتيم فعليه أن يخاف الله في مال اليتيم ولا يأكله باطلا، لأن الله تعالى حذر بعده من أكل أموال اليتامى ظلما فقال: إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا"],"165":["كان في بداية الإسلام أن المرأة إذا زنت، وثبت زناها بالبينة، وهي أربعة شهداء كانت تحبس في بيت عقابا لها حتى الموت، ثم جعل الله لهن سبيلا في سورة النور، وهو الجلد والرجم، وهذا السبيل لا يختص بالمرأة بل يتعداها إلى الرجل أيضا بخلاف الحبس، فإن ذلك كان للمرأة وحدها."],"166":["قوله: وَاللَّذَانِ أي: رجل وامرأة.","وقوله: فَآذُوهُمَا أي بالضرب بالنعال والعصي والتعيير.","وقوله: فَإِنْ تَابَا وَأَصْلَحَا أي: أظهرا توبتهما وإقلاعهما عن الفاحشة.","فَأَعْرِضُوا عَنْهُمَا أي: عن الضرب والتعيير. هذا في حق من لم يثبت زناهما بالبينة، وهي أربعة شهـداء من المسلمين العدول. وأما من ثبت زناهما بالبينة فحكم المرأة الحبس حتى الموت كما مضى، والرجل له الأذى بأنواعها."],"167":["قوله: بِجَهَالَةٍ ليس المراد به عدم العلم بالتحريم، وإنما المراد منه عدم المبالاة بعقاب الله تعالى، كان عمله عمدا أو خطأ.","روي عن قتادة قال: \"اجتمع أصحاب رسول الله صلى الله عليه وسلم فرأوا أن كل شيء عصي به فهو جهالة، عمدا كان أو غيره\".","وقوله: ثُمَّ يَتُوبُونَ مِنْ قَرِيبٍ أي ما لم يغرغر."],"169":["فيه جواز كثرة المهر، وإن كان الأفضل التخفيف في ذلك، وقد أراد عمر بن الخطاب أن ينهى عن كثرة المهر، ثم رجع عن ذلك، كما مرَّ ذكره في كتاب النكاح."],"172":["الطول: المال الكافي من المهر والإنفاق على الزوجة.","قوله: وَآتُوهُنَّ أُجُورَهُنَّ بِالْمَعْرُوفِ أي: مهورهن، فإنه يجب المهر للأمة، كما يجب للحرة.","وقوله: وَلَا مُتَّخِذَاتِ أَخْدَانٍ أي غير مرتبطة بأخلاء وأصدقاء للزنا.","وقوله: فَإِذَا أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَاحِشَةٍ وهو التفسير الصحيح المناسب لسياق الآية.والإحصان هنا: التزويج، وبه قال ابن عباس، وأصحابه.والتفسير الآخر: الإحصان هو الإسلام، وبه قال أيضا جماعة من الصحابة، ورجَّحه الشافعي.","وفي مسألة حد الأمة اختلاف كثير مر ذكره في كتاب الحدود، وخلاصتها: أنها إذا زنت تجلد خمسين قبل الإحصان وبعده، وقوله تعالى: فَإِذَا أُحْصِنَّ لمزيد من التأكيد، أي: إذا كانت على المتزوجة خمسون فعلى غير المتزوجة أولى أن تكون خمسون، ولا يزاد عليه.","وقوله: ذَلِكَ لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ أي: إنما يباح نكاح الإماء لمن خاف على نفسه الوقوع في الزنا، بالشروط الآتية، وهي:","1.أن لا يجد الرجل سعة في المال.","2.أن يخاف على نفسه الوقوع في الزنا.","3.أن تكون الأمة من المؤمنات.","4.أن تنكح بإذن سيدها.","5.أن تدفع لها المهر كالحرة.","6.أن تكون من المحصنات، أي: عفائف من الزنا.وغير مسافحات ولا متخذات أخدان. فإذا تمت هذه الشروط جاز له نكاحهن، وإن صبر فهو خير له من تزوجه الأمة، لئلَّا يكون أولاده أرقاء لسيدها."],"173":["أي: أن الله خفف على هذه الأمة فأجاز نكاح الأمة، الذي كان محرما في الشرائع السابقة، لما علم الله من ضعف الإنسان في نفسه وضعف عزمه، وخاصة في أمر النساء."],"174":["قوله: بِالْبَاطِلِ شامل لجميع الأموال المحرمة المكتسبة عن طريق الغصب والسرقة والقمار والربا وغيرها من المنهيات.","وقوله: تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ شامل لجميع التجارات الخالية عن المحرمات الشرعية. وقوله: وَلَا تَقْتُلُوا أَنْفُسَكُمْ أي بأكل الأموال المحرمة، وهو شامل لجميع صور قتل الإنسان نفسه، ومنها فعل الأخطار المفضية إلى التهلكة، مثل قيادة السيارة بالسرعة الجنونية."],"175":["أي: إن اجتنبتم الكبائر التي نهيتم عنها نكفر عنكم صغائر الذنوب."],"178":["قوله: قَوَّامُونَ أي: حاكمها ورئيسها ومؤدبها، لأن الله فَضَّله عليها في قوله: وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة: ٢٢٨].","وقوله: بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ أي: أن الرجال أفضل من النساء، والرجل خير من المرأة في إدارة شؤون الحياة لضعفها في خلقتها، وأما عند الله إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات: ١٣] .","وقوله: وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ أي: لا تجامعوهن، كما فسره ابن عباس وغيره.وقال غيره: لا يكلمها.","وروي عن ابن عباس: لا تجامعوهن ولا تكلموهن.","وأما ما روي عن أبي حرة الرقاشي، عن عمه أن النبي صلى الله عليه وسلم فال: ((فإن خفتم نشوزهن فاهجروهن في المضاجع)).قال حماد: يعني النكاح.فهو ضعيف.","رواه أبو داود (2144) عن موسى بن إسماعيل، حدثنا حماد، عن علي بن زيد، عن أبي حرة الرقاشي، به، فذكره.","وعلي بن زيد هو ابن جدعان ضعيف باتفاق أهل العلم.","وقوله: وَاضْرِبُوهُنَّ أي: ضربا غير مبرح."],"179":["مهمة الحكمين الإصلاح بين الزوجين، ومعرفة المسيء من غيره، فإذا تبين لهما أحوالهما فلهما أن يغرما المسيء ويؤبخاه، وهل لهما الخيار في التفريق بينهما أم لا؟ فالآية لم تتطرق إلى التفريق، ولذا قال الإمام أحمد: ليس لهما الحكم بالتفريق بينهما.","وقال غيره وهم أكثر الفقهاء: أن لهما الخيار في التفريق بينهما، لأن الإصلاح قد يقتضي التفريق، وهو خير لهما."],"180":["قوله: وَلَا تُشْرِكُوا بِهِ شَيْئًا"],"181":["قوله: وَيَكْتُمُونَ مَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ","أي: لا يظهرون نعمة الله التي أنعم الله عليهم في مأكلهم وملبسهم، وبذلها للفقراء والمساكين، وقد جاء في الحديث أن الله يحب أن يُرى أثر نعمته على عبده."],"183":["والشهيد هنا الأنبياء، كما قال تعالى: ﴿وَأَشْرَقَتِ الْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ الْكِتَابُ وَجِيءَ بِالنَّبِيِّينَ وَالشُّهَدَاءِ وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ﴾ [سورة الزمر: 69]","وقال تعالى: وَيَوْمَ نَبْعَثُ فِي كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِمْ مِنْ أَنْفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَى هَؤُلَاءِ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ (89) [النحل: ٨٩]."],"184":["قوله: لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى كان قبل تحريم الخمر."],"185":["قوله: يُحَرِّفُونَ الْكَلِمَ أي: يغيرون اللفظ، أو يؤولون الكلام على غير تأويله، أو هما جميعا، ومن تحريفهم للفظ ذكر إسماعيل عليه السلام وذريته بأبشع الصفات وأقبحها، وتحريفهم بالمعنى مثل تنزيل صفات النبي محمد صلى الله عليه وسلم على غيره."],"186":["قوله: دُونَ ذَلِكَ أي: الذنوب. لِمَنْ يَشَاءُ من عباده، أي: أن صاحب الذنوب تحت مشيئة الله تعالى، أما الشرك فلن يغفر الله من مات مشركا إذا لم يتب منه."],"187":["قوله: الَّذِينَ يُزَكُّونَ أَنْفُسَهُمْ قيل: هم اليهود.","وقيل: اليهود والنصارى كما جاء في التنزيل: وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا مَنْ كَانَ هُودًا أَوْ نَصَارَى [البقرة: ١١١].","وقوله: يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ الْجِبْتُ قيل: السحر، وقيل: الشيطان، وقيل: الشرك، وقيل: الأصنام، وقـالوا: الجبت يطلق على الصنم والكاهن والساحر.","وروي عن قَبيصة بن المخارق قال: سمعت رسول الله صلى الله عليه وسلم يقول: ((العيافة والطيرة والطرق من الجبت)).","رواه أبو داود (3907)، وأحمد (20603، 20604)، والبيهقي في الكبرى (8/139) كلهم من طريق عوف بن أبي جميلة الأعرابي، عن حيان أبي العلاء، عن قطن بن قبيصة، عن أبيه، فذكره. وقال عوف: العِيافة: زجر الطير.والطرق: الخط يُخَطُّ في الارض.والجبت من الشيطان.","وفي الإسناد حيان أبو العلاء، قيل: حيان بن أبي العلاء، وقيل: حيان بن عمير، وقيل غير ذلك، ولم يوثقه أحد، وإنما ذكره ابن حبان في \"الثقات\" على قاعدته المعروفة، ولذا قال الحافظ في التقريب: \"مقبول\" أي: عند المتابعة، ولم أجده."],"188":["قوله: بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ أي: بسبب نضج جلودهم، لأن الإحسان بالألم مرتبط بالجلود دون اللحوم.وقد جاء وصف جلود الكفار في النار."],"189":["قوله: الْأَمَانَاتِ هي شاملة لجميع الأمانات الواجبة على الإنسان، سواء كانت في حق الله تعالى أو في حق الآدميين، ومن الأمانات أن النبي صلى الله عليه وسلم رد مفتاح الكعبة إلى عثمان بن طلحة بعد أن وقع في يد علي بن أبي طالب، وطلب من النبي صلى الله عليه وسلم أن يجمع لرهطه الحجابة مع السقاية."],"192":["فيه توجيه وإرشاد للعصاة والمذنبين أن لا يقنطوا من رحمة الله تعالى، بل عليهم أن يأتوا إلى رسول الله صلى الله عليه وسلم فيستغفروا الله عنده، ويسألوا الرسول صلى الله عليه وسلم أن يستغفر لهم، فإنهم إذا فعلوا ذلك تاب الله عليهم وغفر لهم، كما قال تعالى: لَوَجَدُوا اللَّهَ تَوَّابًا رَحِيمًا هذا في حياته صلى الله عليه وسلم، وأما بعد مماته فانتهى هذا الأمر."],"194":["يخبر الله تعالى عن أكثر الناس أنهم لو أمروا بقتل أنفسهم أو الخروج من ديارهم لم يفعله إلا القليل منهم، فليحمدوا ربهم أنه لم يأمرهم بالأوامر الشاقة على النفوس، بل عافاهم عن ذلك، كما قال أبو إسحاق السبيعي: لما نزلت وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ اقْتُلُوا أَنْفُسَكُمْ أَوِ اخْرُجُوا مِنْ دِيَارِكُمْ مَا فَعَلُوهُ إِلَّا قَلِيلٌ مِنْهُمْ قال رجل: لو أمرنا لفعلنا.والحمد لله الذي عافانا، فبلغ ذلك النبي صلى الله عليه وسلم فقال: ((إن من أمتي لرجالا، الإيمان أثبت في قلوبهم من الجبال الرواسي)).","رواه ابن جرير الطبري في تفسيره (7/207) وهو مرسل.","وقال السدي: افتخر ثابت بن قيس بن شماس ورجل من اليهود، فقال اليهودي: والله لقد كتب الله علينا أن اقتلوا أنفسكم، فقتلنا أنفسنا، قال ثابت: والله لو كتب علينا أن اقتلوا أنفسكم، لقتلنا أنفسنا، فأنزل الله تعالى في هذا وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَهُمْ وَأَشَدَّ تَثْبِيتًا","رواه ابن أبي حاتم في تفسيره (3/996) عن أحمد بن عثمان بن حكيم الأودي، ثنا أحمد بن مفضل، ثنا أسباط، عن السدي، قال: فذكره.","وفيه مع الانقطاع أسباط وهو ابن نصر الهمداني، ضعَّفه جمهور أهل العلم.","والسدي هو إسماعيل بن عبد الرحمن الكبير، وهو صدوق لا بأس به.","وقوله: وَلَوْ أَنَّهُمْ فَعَلُوا مَا يُوعَظُونَ بِهِ لَكَانَ خَيْرًا لَهُمْ وَأَشَدَّ تَثْبِيتًا أي: أنهم لو اقتصروا على أمر الله تعالى ونهيه، ولم يطمعوا ما لم يأمرهم الله تعالى أو نهى عنه لكان خيرا لهم في الدنيا والآخرة؛ فإن من تكلف بعمل لم يأمره الله تعالى أو اجتنب من شيء لم ينه الله تعالى عنه، فقد وقع في حرج شديد، ولا يستطع القيام به."],"197":["لما كان المسلمون في مكة أمروا بالصلاة والصدقات -أي: غير الزكاة المفروضة، لأنها فرضت في المدينة- وأعمال البر، ولم يؤمروا بالجهاد لقلة عددهم، ولكن كان بعض المؤمنين يودون لو فرض عليهم القتال كما يدل عليه الحديث الآتي."],"199":["قوله: وَيَقُولُونَ طَاعَةٌ هم المنافقون الذين يقولون بلسانهم للرسول صلى الله عليه وسلم: إنا آمنا بك فمرنا نطيعك وهم يبطنون الكفر.","وقوله: فَإِذَا بَرَزُوا أي: فإذا خرجوا.","وقوله: بَيَّتَ طَائِفَةٌ مِنْهُمْ أي: قدّروا في الليل غير ما قالوا في النهار، وكل ما قدِّر في الليل فهو تبييت.","وقوله: فَأَعْرِضْ عَنْهُمْ أي: اصفح عنهم، ولا تعاقبهم، وقيل: لا تخبر بأسمائهم؛ لأنهم قد يحدثون فتنة وشغبا بين المؤمنين."],"200":["والتدبر هو التفكر والنظر، ودبر كل شيء آخره.","قوله: وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا أي: تناقضا وتفاوتا واضطرابا لأنه تنزيل من حكيم حميد.وقيل: لَوَجَدُوا فِيهِ أي في الأخبار عن الغيب بما كان، وبما يكون اختلافا كثيرا.","والخلاصة فيه أن القرآن لا يعارض بعضه بعضا، بل يصدّق بعضه بعضا كما جاء في الحديث الآتي:"],"201":["المراد بالشفاعة هنا السعي بين الناس بالخير، ومن السعي أن يشفع ذو جاه لمن دونه وقد جاء في الصحيح :"],"202":["والتحية هي دعاء الحياة، والمراد بالتحية هنا السلام.","وقوله: فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا الزيادة مندوبة، والمماثلة مفروضة.فإذا قال: السلام عليكم، فقل: وعليكم السلام ورحمة الله وبركاته.فإذا قال: السلام عليكم ورحمة الله وبركاته،فالأفضل أن يرد عليه كذلك ويقف عند قوله: \"وبركاته\".واختلف في الزيادة على بركاته فلم يثبت فيه شيء مرفوعا، وإنّما ورد فيه آثار من الصحابة بالجواز وبالمنع."],"209":["أي يتجاوز الله عنهم على ترك هجرتهم، عَسَى من الله واجب، لأنّه للإطماع، والله تعالى إذا أطمع عبدا في شيء أوصله إليه."],"210":["وقوله: : مُرَاغَمًا أي متحولا يتحول إليه.","وهذا خاص بالمسلم الذي يعيش في دار الكفر، ولا يستطيع أن يعبد الله وحده، ولا يؤدّي شعائر الإسلام، فيجب عليه أن يهاجر منها فإن أرض الله واسعة، يجد فيها مراغما كثيرة كما وعد الله بخلاف الّذي في دار الكفر وله حرية في العبادة وأداء شعائر الإسلام فلا يجب عليه الهجرة منها.بل قد يكون البقاء فيها خير له للدعوة إلى الله سبحانه وتعالى."],"211":["قوله: فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ الجناح يستعمل في الرخص لا يكون فيه حتما؛ لأن الأصل إتمام الصلاة فالقصر رخصة في السفر.","ولكن قول عائشة كما مضى في الصلاة: ((فرضت الصلاة ركعتين ركعتين في الحضر والسفر، فأقرت صلاة السفر، وزيد في صلاة الحضر)).","وقول عمر بن الخطاب: ((صلاة السفر ركعتان، وصلاة الجمعة ركعتان، والفطر والأضحى ركعتان تمام غير قصر على لسان رسول الله صلى الله عليه وسلم)) يدل على أن ركعتين في السفر ليس بقصر.ولذا ذهب بعض أهل العلم إلى أن القصر المراد منه قصر الكيفية لا الكمية؛ لأن أصل الصلاة في السفر هي الثنتان فكيف يكون المراد بالقصر هنا قصر الكمية بأن تكون واحدة واحدة.","وقال غيرهم: قصر الصلاة بمعنى تخفيف الكمية من صلاة الحضر أي من أربع ركعات إلى ركعتين.وذلك في صلاة الظهر والعصر والعشاء فقط دون التخفيف في الصبح والمغرب، وفي حال الخوف ركعة كما في حديث ابن عباس:"],"213":["أي إذا انتهيتم من الصلاة المفروضة فاذكروا الله بالتسبيح والتحميد والتهليل والتمجيد على كل حال."],"214":["قيل: نزلت هذه الآية في أحد وذلك أنّ أبا سفيان وأصحابه لمّا رجعوا يوم أحد، بعث رسول الله صلى الله عليه وسلم طائفة في آثارهم، فشكوا ألم الجراحات.فقال الله تعالى: وَلَا تَهِنُوا أي لا تضعفوا في طلب أبي سفيان وأصحابه.","وقوله: فَإِنَّهُمْ أي الكفار.","وإليه تشير أيضا آية سورة آل عمران (139): وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنْتُمُ الْأَعْلَوْنَ إِنْ كُنْتُمْ مُؤْمِنِينَ أي إن صرتم على جراحاتكم فتكون لكم العاقبة بالنصرة والظفر.وهو قوله تعالى: وَأَنْتُمُ الْأَعْلَوْنَ إِنْ كُنْتُمْ مُؤْمِنِينَ."],"215":["قوله: بِمَا أَرَاكَ اللَّهُ أي بما ألهم الله إليك.وذكر في سبب نزوله قصة بني أبيرق","رُوي عن قتادة بن النعمان قال: \"كان أهل بيتٍ منَّا يقال لهم: بَنُو أُبَيْرق: بِشْرٌ وبشير ومبَشِّرٌ، وكان بشير رجلا منافِقا، يقول الشِّعْرَ يَهْجُو به أصحاب النبي صلى الله عليه وسلم، ثم يَنْحَلُهُ بعض العرَبِ، ثم يقول: قال فلان كذا وكذا، قال فلان كذا وكذا، فإذا سمع أَصحابُ رسول الله صلى الله عليه وسلم ذلك الشِّعْرَ، قالوا: واللهِ، ما يقول هذا الشِّعْرَ إلا هذا الخَبيثُ - أو كما قال الرجل - وقالوا: \"ابنُ الأُبَيْرق قالها، وكانوا أهلَ بيتِ حاجةٍ وفاقةٍ في الجاهلية والإسلامِ، وكان النَّاسُ إنما طعامهم بالمدينة التمرُ والشَّعِيرُ، وكان الرجلُ إذا كان له يَسارٌ فقدمت ضافِطةٌ من الشام، من الدَّرمَك، ابتاع الرجلُ منها، فخصَّ بها نفسه، وأما العيالُ: فإنما طعامهم التمرُ والشعيرُ.","فقدمت ضافِطَةٌ من الشام، فابتاع عَمِّي رِفاعَةُ بنُ زيد حِمْلا من الدَّرمك، فجعله في مَشْرَبةٍ له، وفي المشربة سلاحٌ: دِرْعٌ وسيف، فَعُدِي عليه من تحت البيت فَنُقِبَتِ المشربةُ، وأُخذَ الطعام والسلاح، فلما أصبح أتاني عَمِّي رِفاعَةُ، فقال: يا بن أخي! إنه قد عُدِيَ علينا في ليلتنا هذه، فنُقِبتْ مَشرَبتُنا، فذُهِبَ بطعامنا وسلاحنا.قال: فتحَسّسْنَا في الدارِ، وسألنا، فقيل لنا: قد رأينا بني أُبيرق استوقدوا في هذه الليلة، ولا نرى فيما نرى إلا على بعض طعامكم، قال: وكان بنُو أُبيرق قالوا- ونحن نسأل في الدَّار-: والله ما نَري صاحبكم إلا لَبِيدَ ابنَ سَهْلٍ- رجل منَّا له صلاحٌ وإسلامٌ- فلمَّا سمع لبيدٌ اختَرط سيفَه.وقال: أَنا أَسرِق؟ فَوالله ليخالطنَّكم هذا السيف، أَو لتُبِّينُنَّ هذه السرقة، قالوا: إليك عنا أيها الرجل، فما أنت بصاحبها، فسألنا في الدار، حتى لم نَشُكَّ أنهم أصحابها، فقال لي عمي: يا ابن أخي لو أتيْتَ رسول الله صلى الله عليه وسلم فذكرتَ ذلك لَهُ؟ قال قتادة: فأتيتُ رسول الله صلى الله عليه وسلم فقلتُ: إن أهل بيت منَّا، أَهلَ جفاءٍ عَمَدُوا إلى عمي رفاعة بن زيد فنقَّبُوا مَشْرَبَة لهُ، وأخذوا سلاحه وطعامه، فليَرُدُّوا علينا سلاحنا، فأمَّا الطعام فلا حاجة لنا فيه.","فقال النبيُّ صلى الله عليه وسلم: ((سآمرُ في ذلك)).فلما سمعَ بَنُو أُبَيْرِقَ أَتَوْا رجلا منهم، يقال له: أسِيْر بن عروة.فكلَّموه في ذلك، فاجتمع في ذلك أناسٌ من أَهل الدار، فقالوا: يارسول الله! إن قتادة بن النعمان وعمَّهُ عمدا إلى أَهل بيت منَّا أهلِ إسلامٍ وصلاحٍ يرمونهم بالسرقةِ من غير بَيِّنَةٍ ولا ثَبتٍ.","قال قتادة: فأتيتُ رسول الله صلى الله عليه وسلم فكلَّمته.فقال: ((عمدْتَ إلى أَهل بيت ذُكرَ منهم إسلامٌ وصلاحٌ، ترميهم بالسرقة من غير ثبتٍ ولا بينة؟)).قال: فرجعت ،ولودِدْتُ أَنِّي خرجت من بعض مالي، ولم أكلِّم رسولَ اللهِ صلى الله عليه وسلم في ذلك، فأتاني عمي رفاعةُ، فقال: يا ابن أَخى! ما صنعتَ؟ فأَخبرتُه بما قال لي رسولُ الله صلى الله عليه وسلم، فقال: اللَّهُ المستعانُ، فلم يَلْبَثْ أن نزل القرآنُ إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ وَلَا تَكُنْ لِلْخَائِنِينَ خَصِيمًا (105) بني أُبَيْرق وَاسْتَغْفِرِ اللَّهَ مما قلت لقتادة إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا (106) وَلَا تُجَادِلْ عَنِ الَّذِينَ يَخْتَانُونَ أَنْفُسَهُمْ إِنَّ اللَّهَ لَا يُحِبُّ مَنْ كَانَ خَوَّانًا أَثِيمًا (107) يَسْتَخْفُونَ مِنَ النَّاسِ وَلَا يَسْتَخْفُونَ مِنَ اللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَى مِنَ الْقَوْلِ وَكَانَ اللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا (108) هَا أَنْتُمْ هَؤُلَاءِ جَادَلْتُمْ عَنْهُمْ فِي الْحَيَاةِ الدُّنْيَا فَمَنْ يُجَادِلُ اللَّهَ عَنْهُمْ يَوْمَ الْقِيَامَةِ أَمْ مَنْ يَكُونُ عَلَيْهِمْ وَكِيلًا (109) وَمَنْ يَعْمَلْ سُوءًا أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ يَجِدِ اللَّهَ غَفُورًا رَحِيمًا (110) [النساء:105-110] أي: لو استغفروا الله لغفرَ لهم وَمَنْ يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُ عَلَى نَفْسِهِ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا (111) وَمَنْ يَكْسِبْ خَطِيئَةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِ بَرِيئًا فَقَدِ احْتَمَلَ بُهْتَانًا وَإِثْمًا مُبِينًا (112) قولهم للبَيدٍ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ لَهَمَّتْ طَائِفَةٌ مِنْهُمْ أَنْ يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّا أَنْفُسَهُمْ وَمَا يَضُرُّونَكَ مِنْ شَيْءٍ وَأَنْزَلَ اللَّهُ عَلَيْكَ الْكِتَابَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُ وَكَانَ فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا (113) لَا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَاحٍ بَيْنَ النَّاسِ وَمَنْ يَفْعَلْ ذَلِكَ ابْتِغَاءَ مَرْضَاتِ اللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا (114) [سورة النساء:111- 114]، فلَّما نزل القرآن، أتى رسولُ الله صلى الله عليه وسلم بالسلاح، فَرَدَّهُ إلى رفاعة، قال قتادة: لما أتيتُ عمِّي بالسلاح- وكان شيخا قد عسا، أو عشا- الشك من أبي عيسى- في الجاهلية، وكنت أرى إسلامه مدخولا.","فلما أتيته بالسلاح قال لي: يا ابن أخي! هو في سبيل الله، فعرفتُ أنَّ إِسلامه كان صحيحا.فلما نزلَ القرآنُ لِحقَ بُشَيْرٌ بالمشركين، فنزل على سُلافة بنت سعد بن سُمَيَّةَ، فأنزل الله: وَمَنْ يُشَاقِقِ الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُ الْهُدَى وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ نُوَلِّهِ مَا تَوَلَّى وَنُصْلِهِ جَهَنَّمَ وَسَاءَتْ مَصِيرًا (115) إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا (116) [سورة النساء:115-116]، فلمَّا نزل على سُلافةَ، رماها حَسَّانُ بن ثابتٍ بأبياتٍ من شِعْره، فأخذَتْ رَحْلَهُ فَوَضَعَتْهُ عَلى رأسها، ثم خرجت به فرمت به في الأبطَحِ، ثم قالت: أَهْدَيْتَ لي شِعْرَ حسَّان، ما كنتَ تأتيني بخير.","رواه الترمذي (3036)، وابن جرير الطبري (7/458-461) كلاهما عن الحسن بن أحمد بن أبي شعيب أبي مسلم الحراني، قال: ثنا محمد بن سلمة، قال: ثنا محمد بن إسحاق، عن عاصم بن عمر بن قتادة، عن أبيه عن جده قتادة بن النعمان فذكره.","وكذا رواه ابن أبي حاتم بعضه في تفسيره (4/1059-1060)","قال الترمذي: \"هذا حديث غريب لا نعلم أحدا أسنده غير محمد بن سلمة الحراني، وروى يونس بن بكير وغير واحد هذا الحديث عن محمد بن إسحاق، عن عاصم بن عمر بن قتادة، مرسلا لم يذكروا فيه: عن أبيه عن جده.وقتادة بن النعمان هو: أخو أبي سعيد الخدري لأمّه، وأبو سعيد الخدري: سعد بن مالك بن سنان\".اهـ","كذا قال! وهو الصواب، وأما ما رواه الحاكم (4/385-386) عن أبي العباس محمد بن يعقوب، ثنا أحمد بن عبد الجبار، ثنا يونس بن بكير، حدثني محمد بن إسحاق، حدثني عاصم بن عمر بن قتادة، عن أبيه، عن جده، فذكره.فهو شاذٌّ.","هكذا رواه يونس بن بكير، عن ابن إسحاق موصولا، والصحيح أنّ يونس بن بكير رواه مرسلا كما قال الترمذي، والخطأ فيه من أحمد بن عبد الجبار، فإنه خالف.","كل من رواه عن يونس بن بكير، فلم يقل فيه: \"عن أبيه، عن جده\".فقوله هنا: \"عن أبيه، عن جده\" شاذ.إلّا أنّ هذه القصة رويت بأسانيد أخرى، بعضها موصولة وبعضها مرسلة.ذكرها معظم أصحاب التفسير، فإن كان يقوى بعضها بعضا كما هو معروف عند المحققين فإنّ هذه القصة تدل على أنّ لها أصلا."],"216":["قوله: النَّجْوَى هي الإسرار في كلام الناس، إن كان في خير فخير، وإن كان في شرّ فشر.وقوله: إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَاحٍ يعني هذه الأنواع من النجوى ممدوحة."],"217":["قوله: يُشَاقِقِ الرَّسُولَ أي يتبع غير شريعته، سواء زاد فيها ما لم يأت به النبي صلى الله عليه وسلم، مثل أن يأخذ بالأحاديث الضعيفة والموضوعة والمنكرة أو نقص منها مثل أن يترك الأحاديث الصحيحة الثابتة بحجج واهية فهؤلاء جميعا ممن شاقوا الرسول صلى الله عليه وسلم.","وقوله: وَيَتَّبِعْ غَيْرَ سَبِيلِ الْمُؤْمِنِينَ والمؤمنون حقا هم الصحابة، ثم التابعون، ثم أتباعهم إلى يوم الدين.فهؤلاء هم الذين أُمِرنا بإتّباع سبيلهم؛ لأنه اجتماعهم على شيء ضامن من الخطأ."],"218":["أي ليس لكم ولا لهم النجاة بمجرد التمني، بل العبرة بالإيمان بالله ورسوله وطاعتهما.ومن تلكم الأماني الجردة عن الإيمان والعمل أماني أهل الكتاب قال تعالى: ﴿وَقَالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا مَنْ كَانَ هُودًا أَوْ نَصَارَى تِلْكَ أَمَانِيُّهُمْ [سورة البقرة:111] وقال تعالى: وَقَالَتِ الْيَهُودُ وَالنَّصَارَى نَحْنُ أَبْنَاءُ اللَّهِ وَأَحِبَّاؤُهُ﴾ [سورة المائدة:18]","وروي عن ابن عباس قوله: لَيْسَ بِأَمَانِيِّكُمْ وَلَا أَمَانِيِّ أَهْلِ الْكِتَابِ إلى قوله وَلَا نَصِيرًا تخاصم أهل الأديان، فقال أهل التوراة: كتابنا خير الكتب، أنزل قبل كتابكم، ونبينا خير الأنبياء.وقال أهل الإنجيل مثل ذلك.وقال أهل الإسلام: لا دين إلّا الإسلام، كتابنا نسخ كل كتاب، ونبينا خاتم الأنبياء، وأُمرتم وأمرنا أن نؤمن بكتابكم، ونعمل بكتابنا فقضى الله بينهم فقال: لَيْسَ بِأَمَانِيِّكُمْ الآية.","وخيَّر بين أهل الأديان فقال: ﴿وَمَنْ أَحْسَنُ دِينًا مِمَّنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ وَاتَّبَعَ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَاتَّخَذَ اللَّهُ إِبْرَاهِيمَ خَلِيلًا﴾ [سورة النساء: ١٢٥]","رواه ابن جرير الطبري (7/510)، وفي إسناده مجاهيل لا يعرفون.وروي نحوه عن مسروق والضحاك، والسدي وغيرهم.","ومعنى الأية: إنّ الدين ليس بالتحلي ولا بالتمني.وليس كل من ادّعى شيئا، حصل له بمجرد دعواه، ولا كل من قال: إنّه هو المحق.سمع قوله بمجرد ذلك حتى يكون له من الله برهان.","وقوله: مَنْ يَعْمَلْ سُوءًا عام لكل معصية صغيرة كانت أو كبيرة من المسلمين أو من الكفار، ولكن جاء التخصيص في قوله: إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا [سورة النساء: ١١٦] فما بقي إلّا الشرك، فمن يشرك بالله، ولم يتب منه فإنّه يجز بشركه.","وروي عن ابن عباس قوله: من يشرك يجز به وهو السوء، ولا يجد له من دون الله وليا ولا نصيرا، إلّا أن يتوب قبل موته فيتوب الله عليه.","رواه ابن جرير الطبري وغيره بإسناد حسن."],"219":["يعني أخلص العمل لربه عزّ وجل، وعمل بما شرع الله على لسان رسوله، واتبع الدين الذي كان عليه إبراهيم عليه السلام؛ لأنّ الله اتخذ إبراهيم خليلا أي وليا فلا يقبل بعد كل هذا إلّا الإسلام الذي هو الحنيفية.","والخلة هي أرفع مقامات المحبة؛ لأنه كما قال تعالى: وَإِبْرَاهِيمَ الَّذِي وَفَّى [سورة النجم:37] أي أنّه قام بجميع ما أمر به عن عبادة الله، والتضحية في سبيل الله، وبناء بيت الله."],"220":["قوله: وَمَا يُتْلَى عَلَيْكُمْ فِي الْكِتَابِ يعني آيات الفرائض في أول هذه السورة.","وقوله: وَالْمُسْتَضْعَفِينَ مِنَ الْوِلْدَانِ أي ما كانوا يورِّثون النساء والصبي حتى يحتلم فأنزل الله تعالى أول سورة النساء من الفرائض."],"221":["قوله: وَالصُّلْحُ خَيْرٌ أي من الفراق فإنّ المرأة إن صالحت زوجها وتنازلت عن بعض حقوقها فذلك خير لها."],"222":["وقوله: وَلَنْ تَسْتَطِيعُوا أي في المحبة والميل والشهوة والجماع، وإن كان القَسم حاصلا ليلة وليلة.","قوله: فَلَا تَمِيلُوا كُلَّ الْمَيْلِ أي فإذا ملتم إلى واحدة منهن، فلا تبالغوا في الميل إليها كلية ، فتبقى الأخرى كالمعلقة.وقد جاء التحذير في حديث أبي هريرة من الميل الذي يكون فيه بخس الحق دون ميل القلوب."],"223":["وقوله: وَلَوْ عَلَى أَنْفُسِكُمْ أي اشهدوا على أنفسكم ولو عاد ضررها عليكم.وفيه حث على بيان الحق ولا تأخذهم في الله لومة لائم.","وقوله: أَوِ الْوَالِدَيْنِ وَالْأَقْرَبِينَ وكذلك أداء الشهادة على الوالدين والأقربين من الأولاد والإخوان وغيرهم فحكم الله مقدم على جميع الحقوق.","وقوله: وَإِنْ تَلْوُوا أي تحرفوا الشهادة وتغيروها لتبطلوا الحق.","\"واللَّي\" هو التحريف وتعمد الكذب ومنه قوله تعالى: وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُونَ أَلْسِنَتَهُمْ بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللَّهِ وَمَا هُوَ مِنْ عِنْدِ اللَّهِ وَيَقُولُونَ عَلَى اللَّهِ الْكَذِبَ وَهُمْ يَعْلَمُونَ [آل عمران:78]"],"224":["فيه إخبار عن المنافقين الذين يتربصون بالمؤمنين دوائر السوء، فالله يَعِد المؤمنين بحسن العاقبة، ولن يكون للكافرين سبيلا على المؤمنين.وقد تحقق ذلك في عهد النبوة وفي عهد الخلفاء الراشدين.","وإن أريد به العموم إلى يوم القيامة فالمقصود بالمؤمنين هم المؤمنون حقا.فمتى تحقق ذلك، واستقام المؤمنون على ذلك تكون لهم الغلبة والنصر كما حصل لهم في الماضي.وفيه تطمين للمؤمنين."],"225":["قوله: وَهُوَ خَادِعُهُمْ أي مجازيهم على خدعتهم، لأن الله لا يخادع.","وقوله: وَإِذَا قَامُوا إِلَى الصَّلَاةِ أي أنّ قيامهم إلى الصلاة، يكون متثاقلا؛ لأنهم لا يريدون وجه الله وإنما يعملون رياء، ولذا إذا سنحت لهم الفرصة غابوا عن الصلاة مثل صلاة العشاء وصلاة الفجر لعدم رؤيتهم كما ثبت في الصحيح."],"226":["قوله: مُذَبْذَبِينَ بَيْنَ ذَلِكَ يعني المنافقين، متحيرين بين الإيمان والكفر، فهم مع المؤمنين ظاهرا، ومع الكفار باطنا.فلا هم بمؤمنين مخلصين، ولا هم بمشركين مصرحين بالشرك من أجل الشك الذي لا يفارقهم، والمصالح الدنيوية التي تحول بين الإيمان والكفر وقد جاء في الصحيح:"],"227":["في هذه الآية تحذير من موالاة الكافرين، بعد أن وصف الله المنافقين الذين هم موالون للكفار، حرم على المؤمنين موالاتهم جميعا.","وقد جاء في سورة آل عمران: ﴿لَا يَتَّخِذِ الْمُؤْمِنُونَ الْكَافِرِينَ أَوْلِيَاءَ مِنْ دُونِ الْمُؤْمِنِينَ وَمَنْ يَفْعَلْ ذَلِكَ فَلَيْسَ مِنَ اللَّهِ فِي شَيْءٍ إِلَّا أَنْ تَتَّقُوا مِنْهُمْ تُقَاةً وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ وَإِلَى اللَّهِ الْمَصِيرُ﴾ [سورة آل عمران:28]","والموالاة كلمة جامعة شاملة، مدلولاتها تختلف حسب الزمان والمكان ومن لم ينته من موالاتهم، جعل إيمانه معرضا للفساد؛ لقوله تعالى: أَتُرِيدُونَ أَنْ تَجْعَلُوا لِلَّهِ عَلَيْكُمْ سُلْطَانًا مُبِينًا أي حجة على فساد إيمانهم.","قال ابن عباس: \"كل سلطان في القرآن حجة\".رواه ابن أبي حاتم في تفسيره (4/1097) عن أبيه، ثنا مالك بن إسماعيل، ثنا سفيان بن عيينة، عن عمرو بن دينار، عن عكرمة، عن ابن عباس فذكره.وإسناده صحيح."],"229":["قوله: لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ أي القول القبيح إلّا من ظُلم، فيجوز للمظلوم أن يخبر عن ظلم الظالم وأن يدعو عليه.","وروي عن عائشة قالت: \"سُرقتْ ملحفة لها، فجعلت تدعو على من سرقها، فجعل النبي صلى الله عليه وسلم يقول: ((لا تُسبِّخي عنه)).","قال أبو داود: ((لا تُسبِّخي عنه)) أي لا تُخففي عنه.","رواه أبو داود (1497)، وأحمد (14183) كلاهما من حديث الأعمش، عن حبيب بن أبي ثابت، عن عطاء، عن عائشة فذكرته.","قال يحيى القطان: \"حديث حبيب، عن عطاء ليس بمحفوظ\".نقله العقيلي في الضعفاء.وذكر منها هذا الحديث.","ورواه سفيان، عن حبيب واختلف عليه.فرواه وكيع عنه كما عند أحمد (25052)، ويحيى كما عند النسائي في الكبرى (7318) كلاهما عن سفيان، عن حبيب بن أبي ثابت، عن عطاء بن أبي رباح، عن عائشة موصولا.","ورواه عبد الرحمن بن مهدي عنه مرسلا رواه النسائي في الكبرى (7319)، والموصول أصح."],"230":["قوله: قَبْلَ مَوْتِهِ أي قبل موت عيسى عليه السلام.وذلك عند نزوله من السماء في آخر الزمان.وقد جاء في الصحيح:"],"231":["ينهى الله تعالى أهل الكتاب عن الغلو والإطراء.فإن النصارى غلوا في عيسى بن مريم.فرفعوه فوق المنزلة التي أعطاه الله إياها.حتى جعلوه إلها من دون الله.فعبدوه كما يعبدون الله.ولذا نهى رسول الله صلى الله عليه وسلم أتباعه أن يغلوا فيه."],"234":["قوله: أَوْفُوا بِالْعُقُودِ أي بالعهود كما قال ابن عباس.رواه ابن جرير في تفسيره (8/6) بإسناد حسن.وبه قال جماعة من أهل العلم.","وقيل: ما أحل وما حرم، وما فرض وما حدّ في القرآن كله، فلا تغدروا، ولا تنكثوا.روي أيضا عن ابن عباس بإسناد حسن.وقيل: معناه عقود الجاهليـة يعنى الحِلْف، وفي معنـاه أحاديث ذكرت في مواضعها.","وقوله: بَهِيمَةُ الْأَنْعَامِ هي: الإبل، والبقر، والغنم.","وقوله: إِلَّا مَا يُتْلَى عَلَيْكُمْ أي الآية الثالثة، وهي قوله تعالى: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ"],"236":["قوله: وَالْمُنْخَنِقَةُ هي التي تموت بالخنق باليد أو بالحبل أو بأيّ وجه آخر.","وقوله: وَالْمَوْقُوذَةُ هي التي تُضرب بشيء ثقيل غير محدد أو ينهدم عليها شيء حتى تموت."],"238":["قوله: إِذْ جَعَلَ فِيكُمْ أَنْبِيَاءَ أي إنّ جدكم الأعظم إبراهيم، ثم أبنائه إسماعيل وإسحاق، ثم من أولاد إسحاق يعقوب، ومن أولاده يوسف، وموسى نفسه وهارون، هؤلاء كلهم من أنبيائكم (وإن كان بنو إسرائيل لم يعترفوا بنبوة إسماعيل عليه السلام؛ فإنّ موسى عليه السلام كان معترفا به؛ لأصل ثابت: لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ومدوّنو التوراة إنْ لم يشيروا إلى ذلك، فهو من تعصبهم).","فيُذَكِّرُهم موسى ماضيَ بني إسرائيل، وأنهم كانوا أفضل مَن في الأرض في زمانهم مثل اليونان ومصر والعراق والشام؛ لأنّ الله لم يبعث فيهم الأنبياءَ مثل ما بَعَث في بني إسرائيل، ثم استمرت هذه النبوة في بني إسرائيل بعد موسى عليه السلام، وخُتِمت نبوّةُ بني إسرائيل بعيسى عليه السلام.ثم بعثَ اللهُ محمدَ بنَ عبدالله صلى الله عليه وسلم رسولاً ونبيًّا للناس جميعًا، وبه خُتِمت النبوّةُ إلى يوم القيامة.","وقوله: مُلُوكًا فيه إشارة إلى ما وردَ في سورة يوسف في قوله: وَكَذَلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَاءُ نُصِيبُ بِرَحْمَتِنَا مَنْ نَشَاءُ وَلَا نُضِيعُ أَجْرَ الْمُحْسِنِينَ (56)","وإلى قوله: رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ سورة يوسف [101] أي: مِنْ مُلْكِ مصرَ.","وهذا التاريخُ سوفَ يُعيدُ نفسه، فيكونُ فيكم أنبياءُ وملوكٌ ، فعليكم أن تشكروا الله سبحانه وتعالى، ولا تعثوا في الأرض مفسدين.","وعلى هذا فلا يحتاج إلى تأويل قوله تعالى مُلُوكًا أي: مالكين على أنفسكم وأموالكم ومواشيكم بعد ما كنتم لفرعون وقومه عبيدين، كما فعلَ ابنُ جرير الطبري، وتبِعَه ابنُ كثيرٍ وغيرُه."],"239":["أي لما نكل بنو إسرائيل من طاعة نبي الله موسى عليه السلام نصَحَهم رجلان ممن يخافان اللهَ تعالى، قيل: أحدهما يوشع بن نون، والثاني: كالب بن يوفنا."],"241":["قوله: ابْنَيْ آدَمَ هما هابيل وقابيل فعدا أحدهما على الآخر، فقتله بغيا عليه، وحسدا منه، ففاز المقتول برضا الله وخاب القاتل."],"242":["قوله: وَمَنْ أَحْيَاهَا أي كان سببا في بقاء حياته بالتداوي له، أو بالتبرع بالدم ونحوه."],"244":["الوسيلة: على وزن فعيلة من قولهم: توسلت إلى فلان بكذا بمعنى تقربت إليه.","وقوله: وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ أي أطلبوا القربة إلى الله تعالى بامتثال أوامره واجتناب نواهي، وأما التوسل في الدعاء فالكلام عليه مبسوط في كتاب الأدعية."],"249":["في هذه الآية إشارة إلى ما سيحدث من رِدّة قومٍ ودخول قومٍ في الإسلام، وقد حصلت كما أخبر الله سبحانه وتعالى، فارتدّتْ جماعةٌ من العرب بعد وفاة رسول الله صلى الله عليه وسلم، فقاتلهم أبو بكر الصديق رضي الله عنه، ثم أتى الله بقومٍ هم الروم والفارس، فدخول في الإسلام، وكذلك أهل اليمن وغيرهم كما جاءت في الأخبار."],"251":["قوله تعالى: مَغْلُولَةٌ أي بخيلة، فإن اليد الموثقة لا تُنفق بل تُمسِك.","مثل قوله تعالى: وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [سورة الإسراء:29]."],"253":["قال سفيان (ابن عيينة): ما في القرآن آيةٌ أشدُّ عليَّ من هذه الآية.","ذكره البخاري في كتاب الرقاق، باب الرجاء مع الخوف.","وقول سفيان هذا يُحمل على أنه كان يرى أن هذه الآية الكريمة تقتضي أن نعرف بما في الكتب الإلهية السابقة من العلم، وهذا قد لا يتيسّر لكثيرٍ من الناس.","ومعنى إقامة التوراة والإنجيل: الإيمانُ بما جاء في هذه الكتب من التبشير بالنبي صلى الله عليه وسلم، والإيمانُ بما أنزل عليه في القرآن، لأنه آخرُ كتاب ربّ العالمين وهو يحتوي على ما جاء به الأنبياءُ السابقونَ من العقيدةِ، وبعض الشرائع السابقة كما قال تعالى: وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ فَاحْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ عَمَّا جَاءَكَ مِنَ الْحَقِّ [المائدة: ٤٨]","مصدّقا أي: شاهدًا، ومهيمنًا أي: شاملاً.إلا أن أهل الكتاب حرّفوا كتابَ الله وبدّلوه، فجاء القرآنُ مصحِّحًا لما حرّفوه وبدّلوه، وناسخًا لكثيرٍ من الأحكام التي لا تحتاج إليها البشريّةُ، وأمرنا فقال: فَاحْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ فجعلَ الآن القرآنَ هو الميزان لمعرفة الحقّ والباطل، فمَنْ أخَذَ به نجَا، ومَنْ تركَه هلكَ."],"254":["وقوله: إِنَّ الَّذِينَ آمَنُوا هم مسلمون.","وقوله: وَالَّذِينَ هَادُوا هم اليهود.","وقوله: وَالصَّابِئُونَ هم طائفة من المجوس من الفرس وغيرهم، كان لهم كتاب فضيّعوه، وكانوا يقولون: \"لا إله إلا الله\".ولكنهم لم يؤمنوا بالنبي صلى الله عليه وسلم، وكانوا يرون أن العمل الصالح ينفعهم في الآخرة، ولكن العمل الصالح في نظر الإسلام ما كان موافقا للشريعة الإسلامية بعد إرسال آخر الرسل محمد بن عبدالله صلى الله عليه وسلم، فهؤلاء المؤمنون بالنبي صلى الله عليه وسلم، واليهود والصابئون والنصارى إذا آمنوا بالله الواحد، لاشريك له، وآمنوا باليوم الآخر وهو يوم المعاد يوم الجزاء، وعملوا وفق شريعة النبي صلى الله عليه وسلم مؤمنين به، فهؤلاء لاخوف عليهم في يوم المعاد، ولاهم يحزنون في الدنيا.","وقيل: إن اليهود والنصارى والصابئين الذين كانوا مؤمنين بأنبيائهم قبل بعثة النبي صلى الله عليه وسلم كاليهود الذين آمنوا بموسى عليه السلام.وعملوا وفق شريعته، والنصارى الذين آمنوا بالمسيح عليه السلام، وعملوا وفق تعاليمه، والصائبين الذين كانوا آمنوا بنبيهم في زمانه، وعملوا وفق تعاليم نبيهم، لا خوف عليهم ولا هم يحزنون.وأما الآن فلا بد من الإيمان بالنبي صلى الله عليه وسلم آخر الأنبياء والرسل، ولا نجاة لهم بدون الإيمان به.","وقوله: وَالصَّابِئُونَ بالرفع وحقه النصب، ولكن لما طال الفصل حسن العطف بالرفع.","وقوله: ﴿وَالنَّصَارَى هم أتباع المسيح عيسى عليه السلام، وسُمّوا بالنصارى لنسبة المسيح عليه السلام إلى الناصرية التي وُلِدَ فيها، وقيل: نسبتهم إلى قول المسيح عليه السلام للحواريين: مَنْ أَنْصَارِي إِلَى اللَّهِ﴾ [سورة الصف: ١٤]"],"255":["يعني النصارى الذين جعلوا المسيح وأمه إلهين مع الله.فالله هو الثالث كما جاء في آخر سورة المائدة: وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ مِنْ دُونِ اللَّهِ قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ إِنْ كُنْتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ","فردّ الله على افترائهم بقوله: وَمَا مِنْ إِلَهٍ إِلَّا إِلَهٌ وَاحِدٌ."],"256":["قوله: ﴿وَأُمُّهُ صِدِّيقَةٌ أي مصدقة لما جاء به المسيح عليه السلام ومؤمنة به، وفي انجيل لوقا (23: 49): \"وتبعت المسيحَ، واقتفت أثرَه في عمله\".وقد دلّت الآية بأن مريم ليست بنبيّةٍ، وقد زعمت بعض الفرق الإسلامية بنبوتها ونبوة سارة أم إسماعيل، ونبوة أم موسى.والصحيح الذي عليه جمهور أهل السنة، هو أن الله لم يبعث نبيا إلّا من الرجال لقوله تعالى: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ مِنْ أَهْلِ الْقُرَى﴾ [سورة يوسف:109]"],"257":["قوله: عَلَى لِسَانِ دَاوُودَ وَعِيسَى ذكر الله داود وعيسى عليهما السلام لعلوّ شأنهما وإلا فإنهم لُعنوا على لسان جميع أنبياء بني إسرائيل.","روي عن ابن عباس قال: \"لعنوا بكل لسان، لعنوا على عهد موسى في التوراة، ولعنوا على عهد داود في الزبور، ولعنوا على عهد عيسى في الإنجيل، ولعنوا على عهد محمد صلى الله عليه وسلم في القرآن\".","وقوله: كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ ولذا ذمّهم الله.","وروي عن عبد الله بن مسعود، قال: قال رسول الله صلى الله عليه وسلم: ((لما وقعت بنو إسرائيل في المعاصي، نهتهم علماؤهم، فلم ينتهوا، فجالسوهم في مجالسهم، وواكلوهم وشاربوهم، فضرب الله قلوب بعضهم ببعض، ولعنهم على لسان داود، وعيسى ابن مريم، ذلك بما عصوا وكانوا يعتدون)).وكان رسول الله صلى الله عليه وسلم متكئا، فجلس، فقال: ((لا، والذي نفسي بيده، حتى تأطروهم على الحق أطرا)).","رواه أبو داود (4336)، والترمذي (3047،3048)، وابن ماجه (4006)، وأحمد (3713) كلهم من طريق على بن بَذيمة، عن أبي عبيدة، عن عبد الله بن مسعود فذكره واللفظ لأحمد.","والصحيح أن أبا عبيدة بن عبد الله بن مسعود لم يسمع من أبيه.ومشاه غير واحد بأن الحديث عن بعض أهل البيت.فلعله سمعه عن بعض أهله، عن أبيه.","قال الترمذي: \"قال عبد الله بن عبد الرحمن (هو شيخ الترمذي): قال يزيد: وكان سفيان الثوري لا يقول فيه عن عبد الله\".","ثم قال الترمذي: \"هذا حديث حسن غريب.وقد رُوي هذا الحديث عن محمد بن مسلم بن أبي الوضاح، عن علي بن بَذيمة، عن أبي عبيدة، عن النبي صلى الله عليه وسلم مرسل\".انتهى.","وقول الترمذي \"حسن غريب\" لعله من باب حديث أهل البيت، وإلا فالترمذي ممن يرى أن ابا عبيدة لم يسمع من أبيه.","ورواية سفيان الثوري عن علي بن بذيمة، عن أبي عبيدة، عن النبي صلى الله عليه وسلم عند الترمذي وابن ماجه بالأرقام المكررة، وابن جرير في تفسيره (8/590).","ورواه أبو داود (4337)، عن خلف بن هشام، حدثنا أبو شهاب الحناط، عن العلاء بن المسيب، عن عمرو بن مرة، عن سالم، عن أبي عبيدة، عن ابن مسعود، عن النبي صلى الله عليه وسلم بنحوه.وزاد: ((أو ليضربن الله بقلوب بعضكم على بعض، ثم ليلعنّكم كما لعنهم))","قال أبو داود: \"رواه المحاربي، عن العلاء بن المسيب، عن عبد الله بن عمرو بن مرة، عن سالم الأفطس، عن أبي عبيدة، عن عبد الله.ورواه خالد الطحان، عن العلاء، عن عمرو بن مرة، عن أبي عبيدة\" انتهى أي مرسلا.","ورُوي هذا الحديث عن أبي عبيدة، عن أبي موسى، رواه خالد بن عبد الله الواسطي، عن العلاء بن المسيب، عن عمرو بن مرة، عن أبي عبيدة، عن أبي موسى، عن النبي صلى الله عليه وسلم فذكر نحوه.","وسأل ابن أبي حاتم أباه عن هذا الحديث كما في العلل (1801): فقال: \"لا أعرف هذا الحديث من حديث عمرو بن مرة، وإنما رواه علي بن بذيمة، عن أبي عبيدة، عن عبدالله، عن النبي \"صلى الله عليه وسلم.","وهذا الذي رجّحه أيضا الدارقطني في العلل (5/287-288)."],"258":["قوله: الْيَهُودَ أي أنَّ اليهود كانوا أكثر من أظهروا العداوة للنبي صلى الله عليه وسلم مع أنهم كانوا يعرفونه كما يعرفون أبناءهم.ولذا حرص النبي صلى الله عليه وسلم على إسلامهم كما جاء في الصحيح."],"259":["قوله: ﴿طَيِّبَاتِ أي اللذيذات من الطعام التي تشتهيها النفوس، وكذلك الجميلات من النساء التي تميل إليها القلوب، فلا تمنعوها كما فعل القسيسون والرهبان، فحرموها على أنفسهم، فلم يؤدوا حقها كما قال الله تعالى: وَرَهْبَانِيَّةً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ إِلَّا ابْتِغَاءَ رِضْوَانِ اللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَآتَيْنَا الَّذِينَ آمَنُوا مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِنْهُمْ فَاسِقُونَ﴾ [سورة الحديد: 27]"],"260":["قوله: أَوْ للتخيير، بدون خلاف؛ فإن الله بدأ بالأيسر فالأسهل.وروي عن ابن عباس قال: لما نزلت آية الكفارات، قال حذيفة: يا رسول الله: نحن بالخيار؟ قال: ((أنت بالخيار، إن شئت أعتقت، وإن شئت كسوت، وإن شئت أطعمت، فمن لم يجد فصيام ثلاثة أيام متتابعات)) إلّا أنه لم يصح.","وقوله: أَوْ تَحْرِيرُ رَقَبَةٍ أخذ أبو حنيفة بإطلاقها، فقال: تجزئ الكافرة كما تجزئ المؤمنة.وقيّد الشافعي وغيره بالمؤمنة. وأخذوا تقييدها بالإيمان من كفارة القتل.","وقوله: فَصِيَامُ ثَلَاثَةِ أَيَّامٍ الآية مطلقة ليس فيها كون الصيام متتابعا.وبه قال مالك والشافعي وغيرهما.ومن ذهب إلى التتابع، أخذ بقراءة ابن مسعود فصيام ثلاثة أيام متتابعات إلّا أنها قراءة شاذة غير متواترة.والغالب أنه من تفسير ابن مسعود."],"261":["قوله: وَالْأَنْصَابُ يعني الأوثان، سميت بذلك؛ لأنهم كانوا ينصبونها، واحدها \"نصب\".وقوله: وَالْأَزْلَامُ يعني القداح التي كانوا يستقسمون بها.واحدها: زلم.","وقوله: رِجْسٌ أي خبيث مستقذر."],"262":["قوله: فَهَلْ أَنْتُمْ مُنْتَهُونَ أي: انتهوا، فإن هذا استفهام ومعناه أمر كقوله تعالى: فَهَلْ أَنْتُمْ شَاكِرُونَ [سورة الأنبياء: 80] أي: إذا كان مفاسدها معلومة فالعاقل يجب عليه أن ينتهي منها."],"264":["قوله: تَنَالُهُ أَيْدِيكُمْ مثل الفرخ والبيض، وكذا ما لا يقدر من الفرار من صغار الصيد.","وقوله: وَرِمَاحُكُمْ يعني الكبار من الصيد.وقوله: وَمَنْ قَتَلَهُ مِنْكُمْ مُتَعَمِّدًا أي ذاكرا لإحرامه بخلاف المخطئ والناسي، فلا كفارة عليه.","قال سعيد بن جبير: \"لا تجب كفارة الصيد بقتل الخطأ، بل يختص بالعمد\".","ولكن ذهب أكثر الفقهاء إلى أنّ العمد والخطأ سواء في لزوم الكفارة.","وقوله: فَجَزَاءٌ مِثْلُ مَا قَتَلَ مِنَ النَّعَمِ النعم هي البدنة والبقرة والشاة.","وأراد من النعم ما يقرب من الصيد المقتول شبها من حيث الخلقة، لا من حيث القيمة.ومثاله: حكموا في النعامة ببدنة، وهي لا تساوي بدنة، وفي الحمار الوحشي ببقرة، وهي لا تساوي بقرة، وفي الضبع بكبش، وهي لا تساوي كبشا، وفي الحمام شاة، وهي لا تساوي شاة، وفي الغزال بعنز وهي لا تساوي عنزة...هكذا في بقية الصيد.","وقوله: أَوْ كَفَّارَةٌ طَعَامُ مَسَاكِينَ أَوْ عَدْلُ ذَلِكَ صِيَامًا أي أن المحرم في جزاء الصيد مخير بين أن يذبح المثل من النعم، فيتصدق بلحمه على مساكين الحرم، وبين أن يقوم المثل دراهم، والدراهم طعاما فيتصدق بالطعام على مساكين الحرم، أو يصوم عن كل مد من الطعام يوما، وله أن يصوم حيث شاء، لأنه لا نفع فيه للمساكين."],"265":["قوله: الْبَحْرِ أطلق الخاص وأريد به العام، والمراد منه جميع المياه بحرا كان أو نهرا، أو واديا فإنّ حكم الصيد لا يختلف باختلاف التسمية.و: صَيْدُ الْبَحْرِ هو الحي من الحيوانات.","وقوله: وَطَعَامُهُ سواء حصل من الصيد، أو ما قذَفَه البحرُ إلى الساحل ميّتاً، فإنّ كله حلال لكم ولرفقائكم الذين يسيرون معكم.","وقوله: صَيْدُ الْبَحْرِ من الوحشي مأكول اللحم، أما الإنسي فلا يُسمّى صيدا، كما أن غير مأكول اللحم مثل ذي ناب لا يطلق عليه اسم الصيد."],"267":["قوله: بَحِيرَةٍ هي الناقة كانت إذا ولدت خمسة أبطن لم يركبوها، ولم يجزّوا وبرها، ولم يمنعوها الماء والكلأ.ثم نظروا إلى خامس ولدها فإن كان ذكراً نحروه وأكله الرجال والنساء.وإن كانت أنثى شقوا أذنها، وتركوها وحرموا على الناس منافعها، وكانت منافعها للرجال خاصة، فإذا ماتت حلت للرجال والنساء.","وقيل: كانت الناقة إذا تابعت اثنتي عشرة سنة إناثاً، سُيِّبت فلم يركب ظهرها، ولم يجز وبرها ولم يشرب لبنها إلا ضيف، فما نتجت بعد ذلك من أنثى شق أذنها ثم خلي سبيلها مع أمها في الإبل، فلم تركب ولم يُجزّ وبرها ولم يشرب لبنها إلّا ضيف،كما فعل بأمها، فهي البحيرة بنت السائبة.وقال أبو عبيدة: \"السائبة البعير الذي يُسيّب؛ وذلك أن الرجل من أهل الجاهلية كان إذا مرض أو غاب له قريب نذر، فقال: إن شفاني الله تعالى أو شُفي مريضي أو ردّ غائبي، فناقتي هذه سائبة ، ثم يسيّبها فلا تحبس عن رعي ولا ماء ولا يركبها أحد فكانت بمنزلة البحيرة\".","وأما الوصيلة: فمن الغنم، كانت الشاة إذا ولدت سبعة أبطن نظروا: فإن كان السابع ذكرا ذبحوه، فأكل منه الرجال والنساء، وإن كانت أنثى تركوها في الغنم، وإن كان ذكرا وأنثى استحيوا الذكر من أجل الأنثى، وقالوا: \"وصلت أخاها فلم يذبحوه، وكان لبن الأنثى حراما على النساء، فإن مات منها شيء أكله الرجال والنساء جميعا\".","وأما الحام: فهو الفحل إذا رُكب ولد ولده، ويقال: إذا نتج من صلبه عشرة أبطن، قالوا: حُمي ظهره، فلا يركب، ولا يحمل عليه، ولا يمنع من كلأ ولا ماء، فإذا مات أكله الرجال والنساء."],"268":["قيل: إنها نزلت في اليهود والنصارى من أهل الكتاب بأنهم إذا لم يدخلوا في الإسلام، فعليكم أنفسكم لا يضرّكم من ضلّ من أهل الكتاب. وقيل: إنها نزلت في المشركين المعاهدين الذين يتدينون بالشرك، وقد صولحوا عليه، فلا يضركم إذا اهتديتم أنتم أيها المسلمون.وهذا الذي فهمه أمير المؤمنين أبو بكر الصديق كما جاء في الحديث الآتي:"],"270":["قوله: بِرُوحِ الْقُدُسِ هو جبريل عليه السلام.","وقوله: تُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلًا في المهد- يعني صبيا.","كَهْلًا يعني بعد أن بلغ ثلاثين سنة، وصار نبيا. ثم بقي في الأرض ثلاث سنوات يدعو الناس إلى الله عز وجل، ثم رفع إلى السماء مع الخلاف كما سبق حيا أو ميتا.","لقد امتن الله عزوجل بهذه المعجزات التي أعطاها عبده ورسوله عيسى بن مريم فكيف يتصور منه بعد هذا كله أن يدعي الألوهية؟","والجواب: أنه لم يدّع الألوهية قط، وإنما كان ذلك من إحداث بولس ولذلك في الآيات القادمة ينكر المسيح عليه السلام أنه ادّعى الألوهية لنفسه ولأمه، ويتبرأ ممن اتخذوه إلها، وقد ذكرتُ فصلا كاملا عن بولس وإحداثه في النصرانية في كتابي: \"اليهودية والمسيحية\"."],"271":["قوله: أَوْحَيْتُ أي ألهمت، وقذفت في قلوبهم.","وقوله: الْحَوَارِيِّينَ أي خواص أصحاب عيسى وهم اثنا عشر، ورئيسهم بطرس. قوله: مَائِدَةً مِنَ السَّمَاءِ أي طعاما."],"272":["فالظاهر أنه نزّلها. وهذا الذي قال به جمهور أهل العلم. وقد وصفت هذه المائدة بأوصاف لا دليل عليها من الكتاب والسنة الصحيحة، وإنما هي أقوال الناس.","وأما كون قصة المائدة لم تذكر في الأناجيل الموجودة، فلا غرابة في ذكرها في القرآن؛ لأن الإنجيل الذي أنزله الله تعالى على عيسى عليه السلام ضيّعه النصارى في بداية عهدهم بعد تغلغل أفكار بولس في المجتمع النصراني.","وأما الأناجيل الموجودة فالصحيح أنها أشبه بالسيرة لنبي الله عيسى عليه السلام، ويُعرف من خطبه ومواعظه أنه كان يُبشّر بالإنجيل الذي ضيّعه النصارى.انظر على سبيل المثال: انجيل مرقس (1:15).","ولكن ذهبَ مجاهدٌ والحسن البصري إلى أن الحواريين الذين طلبوا المائدة تراجعوا عن طلبهم، بعد أن عرفوا أن الذين يكفرون بعد ذلك يعذّبون أشدّ العذاب، والقول الأول هو الصواب، وبه قال كثير من السلف والخلف.","قوله: فَمَنْ يَكْفُرْ بَعْدُ مِنْكُمْ فَإِنِّي أُعَذِّبُهُ عَذَابًا لَا أُعَذِّبُهُ أَحَدًا مِنَ الْعَالَمِينَ","أي من الذين يُعذّبون أشدّ العذاب يوم القيامة من كفرَ من أصحاب المائدة من الحواريّين.ومن الذين يعذّبون أشدّ العذاب المنافقون لقوله تعالى: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ [النساء: ١٤٥]","وكذلك من الذين يعذّبون أشد العذاب آل فرعون لقوله تعالى: وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ [غافر: ٤٦]","روى ابن جرير الطبري عن عبد الله بن عمرو قال: إن أشدّ الناس عذابا يوم القيامة ثلاثة: المنافقون، ومن كفر من أصحاب المائدة، وآل فرعون."],"273":["قوله: وَإِذْ قَالَ اللَّهُ عطف على قوله إِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ اذْكُرْ نِعْمَتِي عَلَيْكَ وهو يوم القيامة بحضرة من اتخذه وأمه إلهين من دون الله.وليس مما قاله في الدنيا عند الرفع كما قال به بعض المفسرين.ومن المعلوم أن عبادة عيسى عليه السلام حدثت بعد رفعه بزمان.فصلتُ القول في ذلك في كتابي: \"اليهودية والمسيحية\" فراجعه.وشُبهتهم في ذلك لفظ \"إذ\" فإنه يستعمل للماضي، وهذا صحيح لا شك فيه، ولكن في كتاب الله تعالى ذكر كثير من أمور يوم القيامة بلفظ الماضي لتحقق وقوعها.","وقوله: فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ أي يا رب ما قلت لهم إلّا ما أمرتني به من إفرادك بالتوحيد والعبادة.وكنت عليهم شاهدا ما يفعلونه، فكنت أعلمهم إن أخطأوا.فلما وفّيت أجلي في الدنيا، ورفعتني إليك حيا، كنت أنت المطلع على أعمالهم الظاهرة والباطنة؛ لأنه لاتخفى عليك خافية في الأرض، ولا في السماء. وقد جاء في الصحيح:"],"275":["قوله: ﴿وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ أي وهو يرزق خلقه، ولا يأكل وقد جاء في التنـزيل: مَا أُرِيدُ مِنْهُمْ مِنْ رِزْقٍ وَمَا أُرِيدُ أَنْ يُطْعِمُونِ إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ﴾ [سورة الذاريات:57-58]"],"276":["وقد جاء في الصحيح:"],"277":["يعني الدابة أمة، والطير أمة، مثل الإنسان فإنه أمة.","وقوله: مَا فَرَّطْنَا فِي الْكِتَابِ مِنْ شَيْءٍ أي رزقهم وأجلهم.والكتاب المراد به: اللوح المحفوظ.أي الجميع علمهم عند الله، ولا ينسى واحدًا من جميعها بريًّا أو بحريًّا أو سماويًّا. كما جاء في سورة هود [6] وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِي كِتَابٍ مُبِينٍ","وقوله: ﴿ثُمَّ إِلَى رَبِّهِمْ يُحْشَرُونَ أي يبعثون يوم القيامة كقوله تعالى: وَإِذَا الْوُحُوشُ حُشِرَتْ﴾ [سورة التكوير:5]"],"278":["قوله: فَلَمَّا نَسُوا أي تركوا العمل بما ذكّروا به.","قوله: مُبْلِسُونَ أي الآيسون."],"280":["قوله: كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ أي أنه أوجب على نفسه الرحمة تفضلا منه وإحسانا."],"282":["قوله: يَتَوَفَّاكُمْ بِاللَّيْلِ الوفاة الصغرى وهي حالة النوم، والوفاة الكبرى هي الموت الذي لا حياة بعدها إلّا بعد البعث.","ومثله قوله تعالى: اللَّهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَى عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَى إِلَى أَجَلٍ مُسَمًّى [سورة الزمر:42].","وقوله: مَا جَرَحْتُمْ بِالنَّهَارِ أي ما كسبتم، قال ابن عباس: \"ما اكتسبتم من الإثم\".","وقوله: أَجَلٌ مُسَمًّى هو الموت."],"283":["قوله: ﴿حَفَظَةً أي الملائكة الذين يحفظون بدن الإنسان كما قال تعالى: لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ﴾ [سورة الرعد:11]","وقوله: وَهُمْ لَا يُفَرِّطُونَ أي لا يقصّرون في حفظ روح المتوفى، بل يحفظونها، وينزلونها حيث شاء الله عز وجل، إن كان من الأبرار ففي عليين، وإن كان من الفجار ففي سجيين.","وقوله: ثُمَّ أي بعد الموت.","وقوله: رُدُّوا إِلَى اللَّهِ مَوْلَاهُمُ الْحَقِّ أي الخلائق يُردون بالموت إلى الله مولاهم؛ ليحكم بينهم؛ لأنه لا حكم إلّا له؛ لقوله في آخره: أَلَا لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحَاسِبِينَ لكمال علمه وقدرته، فإنه إذا حاسب يكون حسابه سريعا؛ لأنه لا يحتاج إلى فكرة وروية وعقد يد."],"284":["قوله: مِنْ فَوْقِكُمْ أي الرجم والحصب من السماء.","وقوله: ﴿أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أي الخسف.وقوله: أَوْ يَلْبِسَكُمْ شِيَعًا أي فرقا متخالفين بعد ما كنتم مجتمعين.وقوله: وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ أي في الفتنة فيُسلّط بعضكم على بعض بالعذاب والقتل. قال الله تعالى: أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ فَإِذَا هِيَ تَمُورُ أَمْ أَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ وَلَقَدْ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ﴾ [سورة الملك:16-18]"],"285":["قوله: وَلَهُ الْمُلْكُ يَوْمَ يُنْفَخُ فِي الصُّورِ يعني يوم القيامة، خصَّ له الملك يوم القيامة مع أنه مالك كل شيء، لأن يوم القيامة تنقطع أملاك الخلائق، فلا يبقى الملك إلا لله الواحد القهّار. و الصُّورِ هو القرن الذي ينفخ فيه إسرافيل."],"286":["قوله: لِأَبِيهِ آزَرَ ذهب غير واحد من أهل العلم بأن اسم أبي إبراهيم \"تارح\" اعتمادا على ما جاء في سفر التكوين:[27:11].وقالوا آزر اسم لصنم كان يعبده، فغلب عليه اسمه.","قلت: لا يمنع أن يكون لأبيه عدة أسماء: \"تارح\" و \"آزر\" أو أحدهما اسم، والآخر لقب، أو وقع تحريف في التوراة المزعومة في اسمه كما وقع في مواضع أخرى. فلا ينبغي الإنكار الصريح أن يكون اسمه آزر ما دام سماه الله تعالى به."],"287":["يعني بيّن الله له وجه الدلالة لوحدانيته تعالى في ملكه وخلقه، وأنه لا إله غيره، ولا ربَّ سواه.وقد يكون ذلك على ظاهره بأن الله تعالى بقدرته أرى إبراهيم عليه السلام ما في السماوات والأرض من العجائب، وجلّى له بواطن الأمور وظواهرها كما روي عن بعض الصحابة والتابعين إلا أنه لم يثبت مرفوعا.","فقد روي عن مجاهد قال: \"فرجت له السماوات، فنظر إلى مافيهن، حتى انتهى بصره إلى العرش، وفرجت له الأرضون السبع، فنظر إلى ما فيهن.","كذلك ما رُويَ عن سعيد بن جبير قال: \"كُشِف له عن أديم السماوات والأرض حتى نظر إليهن على صخرة، والصخرة على حوت، والحوت على خاتم رب العزة، لا إله إلا الله\".","وكذلك ما رُوي عن سلمان، وعلي، وغيرهما.ذكرها ابن جرير في تفسيره (9/350-351) ولا يثبت من ذلك شيء مرفوعا.","وقوله: مَلَكُوتَ من الملك، وزيدت فيه التاء للمبالغة كالجبروت والرحموت والرهبوت. وقوله: وَلِيَكُونَ مِنَ الْمُوقِنِينَ يعني أنه أراه ملكوت السماوات والأرض ليكون ممن يتوحد بتوحيد الله، ويعلم حقيقة ما هداه له، وبصّره إياه من معرفة وحدانيته، وما عليه قومه من الضلالة من عبادتهم الأصنام، واتخاذهم إياهم آلهة دون الله تعالى.كما قاله ابن جرير."],"288":["اختلف المفسرون في هذا المقام، هل هو مقام نظر أو مناظرة؟ فروي عن ابن عباس أنه مقام نظر.وكان ذلك في حال طفولته قبل قيام الحجة عليه، فلم يكن ذلك كفرا.وقال غيره: إنه في مقام مناظرة لقومه مبينا لهم بفلان ما كانوا عليه من عبادة الأصنام والكواكب والشمس والقمر، ومما يؤكد ذلك قوله تعالى: وَحَاجَّهُ قَوْمُهُ... الآية."],"289":["قوله: إِلَّا أَنْ يَشَاءَ رَبِّي استثناء منقطع أي أن الله هو النافع والضار لا آلهتكم؛ لأن الله قادر على كل شيء."],"291":["قوله: وَمِنْ ذُرِّيَّتِهِ قد يكون الضمير يعود إلى نوح؛ لأنه أقرب المذكورين، ولا إشكال في أن الناس كلهم من ذرية نوح.وقد يعود إلى إبراهيم؛ لأن سياق الكلام يدل على ذلك. ولكن يشكل على ذلك أمران.","أحدهما: قوله: وَلُوطًا ولوط عليه السلام ليس من ذرية إبراهيم، وإنما هو لوط بن هاران أخي إبراهيم.(التكوين:27:11).","فيقال: إنه دخل تغليبا كما في قوله تعالى: أَمْ كُنْتُمْ شُهَدَاءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنْ بَعْدِي قَالُوا نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ [سورةالبقرة:133].","فإسماعيل عمه، ودخل في آبائه تغليبا.","والثاني: ذكر عيسى في ذرية إبراهيم؛ لأنه ولد من مريم بدون أب.","ويجاب بأن ولد البنات من ذرية الرجال، كقول النبي صلى الله عليه وسلم للحسن بن علي: ((إنّ ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين)).رواه البخاري (2704) عن أبي بكرة.","وأم عيسى كانت من نسل داود، وهو من ذرية إبراهيم."],"293":["قوله: وَتَرَكْتُمْ مَا خَوَّلْنَاكُمْ أي أعطيناكم، وأنعمنا به عليكم من المال والخدم.","وقوله: وَرَاءَ ظُهُورِكُمْ أي في الدنيا. وقد جاء في الصحيح:"],"294":["قوله: بَصَائِرُ هي البينات والحجج التي اشتمل عليها القرآن.","وقوله: دَرَسْتَ بسكون السين، من الدرس وهو العلم.يعني يا محمد! أنت تعلمت من أهل الكتاب.","وروي عن ابن عباس أنه قرأ: وَلِيَقُولُوا دَارَسْتَ وهي قراءة متواترة، ومعناها: دارست أهل الكتاب، وقرأت الكتب وتعلمتها.","كما قال المشركون من قبل أنّ بشرا يُعلّم محمدا. وقد أخبر الله عن مقالتهم وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُ بَشَرٌ لِسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ وَهَذَا لِسَانٌ عَرَبِيٌّ مُبِينٌ [سورة النحل:103]","يعني لما قال المشركون إن هذا العلم الذي عند محمد يأتيه من العجم من الفرس، ردَّ الله تعالى عليهم بقوله: وَهَذَا لِسَانٌ عَرَبِيٌّ مُبِينٌ وكذلك يرد الله على هؤلاء بقوله: وَلِنُبَيِّنَهُ لِقَوْمٍ يَعْلَمُونَ أي أن هذا العلم ليس من أهل الكتاب، ولا من العجم، وإنما وحيٌ من عند الله، نوضّح ذلك لقوم من أهل الكتاب خاصة، ولغيرهم عامة."],"295":["نهى الله رسوله والمؤمنين عن سب آلهة المشركين مع أنها شجر وحجر، لا قيمة لها، ولكن فيه مفسدة عظيمة، وهي أنهم يسبون الله تعالى الذي لا إله إلا هو.","روي عن ابن عباس قال: قالوا: يا محمد! لتنتهين عن سبّ آلهتنا أو لنهجونّ ربك.فنهاهم الله أن يسبّوا أوثانهم، فيسبوا الله عدوا بغير علم."],"296":["يعني يا محمد! إن كان لك أعداء يخالفونك ويعادونك، فقد كان لكل نبي من قبلك أيضا أعداء، فلا تحزن.وجاء في الصحيح:"],"297":["فيه إخبار من الله تعالى عن حال أكثر أهل الأرض بأنهم ضالون.","وفي سورة الصافات [71]: وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ الْأَوَّلِينَ وفي سورة يوسف: [103] وَمَا أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ.","ثم إنّ ضلالهم ليس على أسس ثابتة.وإنما هي على ظنون كاذبة وحسابات باطلة."],"300":["قوله: شُرَكَاؤُهُمْ أي شياطينهم الذين زين لهم قتل أولادهم عموما خشية فقرهم عموما، وقتل بناتهم خصوصا؛ لقوله تعالى: وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَى ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ [سورة النحل:58].وقد حذر الله من قتل البنات، فقال: وَإِذَا الْمَوْءُودَةُ سُئِلَتْ (8) بِأَيِّ ذَنْبٍ قُتِلَتْ (9) [التكوير:8-9].ولا يزال هذا العمل الشنيع جاريا حتى اليوم في كثير من البلدان بالإجهاض بدون سبب شرعي."],"302":["كان أهل الجاهلية من المشركين يحرمون أشياء، ويحلون أشياء.فأخبر الله تعالى نبيه بأن يُعلن لهم بأني لا أجد من الحرام إلا ما أوحي إلي في هذه الآية الكريمة.","هذا بالنسبة لأهل الجاهلية الذين كانوا أحلوا الميتة والدم المسفوح وما ذبح على الأوثان والأنصاب.وأما بالنسبة للمسلمين، فقد حرم عليهم علاوة على هذه ما ذكر في [سورة المائدة: 3] وهي قوله تعالى: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَنْ تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَلِكُمْ فِسْقٌ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِنْ دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ","وكذا ما ذكر في الأحاديث الصحيحة.","فقال أهل العلم: وقع النسخ في الحصر الذي في سورة الأنعام.والناسخة هي آية سورة المائدة والأحاديث الصحيحية.ولا يصح الاستدلال بآية الأنعام عل حلة باقي الأشياء؛ لأن حصره مرفوع.","أَوْ دَمًا مَسْفُوحًا يعني المهراق، وأما الدم الخالط في اللحم، فلا يحرم.","روي عن عكرمة قال: \"لولا هذه الآية لتتبع المسلمون من العروق ما تتبعت اليهود\"."],"305":["قوله: ﴿فَاتَّبِعُوهُ أي السبيل الواحد الذي هو سبيل الله؛ لأن الحق واحد بخلاف الباطل؛ فإنّ طرقه كثيرة، كالنور فإنه واحد والظلمات كثيرة.كما قال الله تعالى: اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُمَاتِ أُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ﴾ [سورة البقرة:257]"],"306":["قوله: تَمَامًا أي كمالا لإحسانه.","وقوله: عَلَى الَّذِي أَحْسَنَ المراد به الجنس، فاستوى فيه مفرده وجمعه.ومعناه: الذين أحسنوا من بني إسرائيل.يؤيد هذا المعنى ما جاء في قراءة ابن مسعود تمَامًا عَلَى الَّذِين أَحْسَنُوا وقيل: معنى قوله تعالى: عَلَى الَّذِي أَحْسَنَ هو موسى عليه السلام نفسه، فإن الله جزاه بإحسانه وقيامه بأوامره أن أعطاه الكتاب، فيه هدىً ونور.والأول أصح. والله تعالى أعلم. وقوله: وَتَفْصِيلًا لِكُلِّ شَيْءٍ أي ما يحتاجون إليه من أوامر وأحكام."],"307":["قوله: وَهَذَا كِتَابٌ أي القرآن العظيم، وأخطأ من جعل اسم الإشارة للكتاب الذي أنزله الله تعالى على موسى عليه السلام وهو التوراة."],"314":["قوله تعالى: فَلَمَّا تَجَلَّى رَبُّهُ لِلْجَبَلِ"],"316":["قوله: قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ الخطاب موجه لجيمع بني آدم من العرب والعجم، والأحمر والأسود بأنه صلى الله عليه وسلم رسول للجميع.","والآيات في هذا المعنى كثيرة، منها قوله تعالى: وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ [سبأ:٢٨]."],"317":["وجاء في سورة البقرة [60]: وَإِذِ اسْتَسْقَى مُوسَى لِقَوْمِهِ فَقُلْنَا اضْرِبْ بِعَصَاكَ الْحَجَرَ فَانْفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَشْرَبَهُمْ كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ","وذلك عدد الأسباط وهم: أشير، وأفريم، منسى بن يوسف، بنيامين، جاد، دان، رأوبين، زبولون، شمعون، نفتالي، يساكر، يهوذا.","وقعت هذه القصة في التيه، قال ابن عباس: \"ذلك في التيه، ضرب لهم موسى الحجر فصار فيه اثنتا عشرة عينا من ماء، لكل سبط منهم عين يشربون منها\".","وتفاصيل هذه القصة مذكورة في سفر العدد، باب:20.وذكر فيها فصل برية صين.وهي موضع في التيه عبر به بنو إسرائيل إلى كنعان، وظن بعض المفسرين أنها بلد معروف اليوم وهو الصين."],"320":["والنـزغ: الكلام الذي يقصد به الإغراء بين الناس.","ونزغ الشيطان: وساوسه، وما يحمل به الإنسان على المعاصي.","وفي التنزيل العزيز: وَقُلْ لِعِبَادِي يَقُولُوا الَّتِي هِيَ أَحْسَنُ إِنَّ الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْ إِنَّ الشَّيْطَانَ كَانَ لِلْإِنْسَانِ عَدُوًّا مُبِينًا [الإسراء: ٥٣]","قال ابن جرير: \"وإما يغضبنّك من الشيطان غَضَبٌ يصدّك عن الإعراض عن الجاهلين، ويحملك على مجازاتهم فَاسْتَعِذْ بِاللَّهِ إِنَّهُ سَمِيعٌ عَلِيمٌ \"."],"321":["هذا حكم عام في كل من سمع كتاب الله يقرأ أن يستمع ويُنصت له.","وقوله: فَاسْتَمِعُوا لَهُ أي احضروا قلوبكم لسماع القرآن، وتدبر معانيه.","وقوله: ﴿وَأَنْصِتُوا أي اتركوا حديث الناس، ووجهوا عنايتكم في سماع القرآن.وقد كان كفار مكة يقولون كما حكى الله سبحانه وتعالى عنهم: وَقَالَ الَّذِينَ كَفَرُوا لَا تَسْمَعُوا لِهَذَا الْقُرْآنِ وَالْغَوْا فِيهِ لَعَلَّكُمْ تَغْلِبُونَ﴾ [سورة فصلت: ٢٦]","وقوله: لَعَلَّكُمْ تُرْحَمُونَ أي إنّ الاستماع والإنصات يحصل بهما الرحمة. وأما الإنصات في الصلاة الجهرية عند قراءة الإمام سورة الفاتحة فهو مختلف فيه كما مضى في كتاب الصلاة.","وأما ما روي عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال: ((من استمع إلى آية من كتاب الله عزوجل، كتِب له حسنة مضاعفة، من تلاها كانت له نورا يوم القيامة)) فهو ضعيف.","رواه أحمد (8494) عن أبي سعيد مولى بني هاشم، حدثنا عبّاد بن ميسرة، عن الحسن، عن أبي هريرة فذكره.","فيه عباد بن ميسرة، قال فيه ابن معين: \"ليس بالقوي\".وقال أبو داود: \"ليس بالقوي\".ومع ذلك ذكره ابن حبان في \"الثقات\".","وفيه الحسن وهو الإمام المعروف إلّا أنه كان يدلس، ولم يثبت سماعه من أبي هريرة.","ورواه سعيد بن منصور، حدثنا إسماعيل بن عياش، عن ليث، عن مجاهد، عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: ((من تلا آية من كتاب، كانت له نورا يوم القيامة، ومن استمع لآية من كتاب الله كتبت له حسنة مضاعفة)).","رواه البيهقي في شعب الإيمان (1828) بإسناده عن سعيد بن منصور.","وفيه إسماعيل بن عياش الشامي، روايته عن أهل بلده مقبولة، وفي غيره مضطرة، وهذا منها. وليث هو ابن سُليم، كوفي سيئ الحفظ."],"322":["يستحب أن يكون ذكر الله تعالى بالقول الوسط لا جهرًا بليغًا، ولا سرًّا لا يسمع.","وقوله: تَضَرُّعًا أي متضرعا بلسانك.","وقوله: : وَخِيفَةً أي خائفا من الله."],"325":["وَجِلَتْ أي خافت وانقادت لأمره، وخضعت لذكره.","وقوله: زَادَتْهُمْ إِيمَانًا أي تصديقا ويقينا.","قال عمير بن حبيب- وكانت له صحبة-: إن للإيمان زيادة ونقصانا.وقيل فما زيادته؟ قال: إذا ذكرنا الله عزوجل وحمدناه، فذلك زيادته، وإذا سهونا، وغفلنا، فذلك نقصانه.ذكره البغوي.","وقال ابن عباس: إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ قال: \"المنافقون لا يدخل قلوبهم شيء من ذكر الله عند أداء فرائضه، ولا يؤمنون بشيء من آيات الله، ولا يتوكلون على الله، ولا يصلّون إذا غابوا، ولا يؤدُّون زكاة أموالهم.فأخبر الله سبحانه أنهم ليسوا بمؤمنين، ثم وصف المؤمنين فقال: إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ، فأدوا فرائضه وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا يقول: تصديقًا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ، يقول: لا يرجون غيره.","رواه الطبري في التفسير (11/27-28)، قال: حدثني المثنى، قال: ثنا أبو صالح، قال: ثني: معاوية، عن علي، عن ابن عباس فذكره."],"327":["قوله: إِحْدَى الطَّائِفَتَيْنِ أي الفريقين، إحداهما أبوسفيان مع العير، والأخرى: أبو جهل مع النفير."],"334":["قوله: الصُّمُّ أي عن سماع الحق.","قوله: الْبُكْمُ أي عن فهم الحق.","شبّه الله تعالى هولاء المنافقين والمشركين بهذه الصفات الحيوانية؛ لإنكارهم عن اتباع الحق، فهم كالأنعام، مثل قوله تعالى: وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ [ البقرة: ١٧١]","وقال تعالى: أُولَئِكَ كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ أُولَئِكَ هُمُ الْغَافِلُونَ [الأعراف: ١٧٩]","وقال ابن عباس: \"المراد بهؤلاء نفر من بني عبد الدار من قريش\"."],"335":["قوله: لِمَا يُحْيِيكُمْ أي أن في استجابة الله ورسوله حياة، وفي إنكاره ممات.","وقوله: وَاعْلَمُوا أَنَّ اللَّهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ أي في حالة عدم الإستجابة لله، فإن الله يحول بين المرء وقلبه، فلا يعقل ولا يدري ما يعمل، وفيه حث على الإسراع إلى طاعة الله ورسوله."],"336":["قوله: فِتْنَةً أي إنّ الفتنة تعم الصالح والفاسق، ولا تخص أهل المعاصي، فاتقوها إن لم تتقوها أصابتكم."],"337":["قوله: لَا تَخُونُوا اللَّهَ وَالرَّسُولَ أي بترك ما أمر الله به ورسوله، وَتَخُونُوا أَمَانَاتِكُمْ أي أدوا الأمانات إلى أصحابها.","وروي عن عبد الله بن أبي قتادة قال: نزلت: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ في أبي لبابة بن عبدالمنذر.","رواه الطبري في تفسيره (11/122)، وابن أبي حاتم في تفسيره (8975) كلاهما من طريق سفيان بن عيينة، قال: ثنا إسماعيل بن أبي خالد، قال: سمعت عبدالله بن أبي قتادة، يقول: فذكره، ولكنه مرسل.","وتفصيل القصة كما ذكر ابن إسحاق (السيرة النبوية لابن هشام 2/236-237)، قال: \"ثم إنهم بعثوا (أي بنو قريظة) إلى رسول الله صلى الله عليه وسلم أن ابعث إلينا أبا لبابة بن عبد المنذر أخا بني عمرو بن عوف.وكانوا حلفاء الأوس، لنستشيره في أمرنا، فأرسله رسول الله صلى الله عليه وسلم إليهم.فلما رأوه قام إليه الرجال وجهش إليه النساء والصبيان يبكون في وجهه، فرقّ لهم، وقالوا له: يا أبا لبابة! أترى أن ننزل على حكم محمد؟ قال: نعم، وأشار بيده إلى حلقه إنه الذبح.قال أبو لبابة: فوالله ما زالت قدماي من مكانهما حتى عرفت أني قد خنتُ الله ورسوله صلى الله عليه وسلم، ثم انطلق أبو لبابة على وجهه ولم يأت رسول الله صلى الله عليه وسلم حتى ارتبط في المسجد إلى عمود من عمده.وقال: لا أبرح مكاني هذا حتى يتوب الله علي مما صنعت.وعاهد الله أن لا أطأ بني قريظة أبدا، ولا أرى في بلد خنت الله ورسوله فيه أبدا .قال ابن إسحاق : \"فلما بلغ رسول الله صلى الله عليه وسلم خبره.وكان قد استبطأه، قال: ((أما إنه لو جاءني لاستغفرتُ له، فأما إذ قد فعل ما فعل، فما أنا بالذي أطلقه من مكانه حتى يتوب الله عليه)).","قال ابن إسحاق: فحدثني يزيد بن عبد الله بن قسيط أن توبة أبى لبابة نزلت على رسول الله صلى الله عليه وسلم من السحر وهو في بيت أم سلمة.فقالت أم سلمة: فسمعت رسول الله صلى الله عليه وسلم من السحر وهو يضحك.قالت، فقلت: مم تضحك، يا رسول الله؟ أضحك الله سنك.قال: ((تيب على أبي لبابة)).قالت: قلت: أفلا أبشّره يا رسول الله؟ قال: ((بلى، إن شئت)).قال: فقامت على باب حجرتها، وذلك قبل أن يضرب عليهن الحجاب فقالت: يا أبا لبابة أبشر فقد تاب الله عليك.قالت: \"فثار الناس إليه ليطلقوه، فقال: لا، والله حتى يكون رسول الله صلى الله عليه وسلم هو الذي يطلقني بيده.فلما مر عليه رسول الله صلى الله عليه وسلم خارجا إلى صلاة الصبح أطلقه.","واستغفار النبي صلى الله عليه وسلم لمن جاء إليه خاص بحياته، والكلام عليه مبسوط في تفسير سورة النساء :64"],"339":["قوله لَوْ نَشَاءُ لَقُلْنَا مِثْلَ هَذَا هذا كذب منهم؛ فإنهم لا يستطيعون أن يقولوا مثل هذا وقد تحدوا غير مرة أن يأتوأ بسورة من مثله.","وقوله: أَسَاطِيرُ الْأَوَّلِينَ هو جمع أسطورة وهي القصص والخرافات والعجائب التي كتبها العرب والفرس قديمًا، فكانوا ادعوا أن النبي صلى الله عليه وسلم كان يقتبس منها، كما أخبر الله تعالى عنهم في آية أخرى: وَقَالُوا أَسَاطِيرُ الْأَوَّلِينَ اكْتَتَبَهَا فَهِيَ تُمْلَى عَلَيْهِ بُكْرَةً وَأَصِيلًا [الفرقان: ٥]."],"340":["هذه طريق المعاندين للدعوة، فإنهم يشترطون شروطا لقبول الدعوة."],"344":["قوله: وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ قال جمهور أهل العلم: سهم الله وسهم الرسول واحد، والغنيمة تُقسَم خمسة أخماس، أربعة أخماس للمجاهدين المقاتلين، والخمس لخمسة أصناف كما ذكرالله عز وجل: وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ إِنْ كُنْتُمْ آمَنْتُمْ بِاللَّهِ وَمَا أَنْزَلْنَا عَلَى عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ هذا في حياة الرسول صلى الله عليه وسلم، ثم جعل أبو بكر وعمر سهم النبي صلى الله عليه وسلم في الكراع والسلاح.","وقال الشافعي: \"واليوم هو لمصالح المسلمين وما فيه قوة الإسلام\"."],"346":["قوله: يُرِيكُمُوهُمْ أي في المنام، وذلك أن النبي صلى الله عليه وسلم رأى في المنام قبل لقاء العدو أن العدد قليل، وأخبر أصحابه بما رأى.","وروي عن عبد الله بن مسعود، قال: \"لقد قللوا في أعيننا يوم بدر حتى قلت لرجل إلى جنبي: أتراهم سبعين؟ قال: أراهم مائة، قال: فأسرنا رجلا منهم، فقلت: كم كنتم؟ قال: ألفا.","رواه ابن سعد (2/22)، وابن أبي شيبة (37853)، وابن جرير في تفسيره (5/251)، والبيهقي في الدلائل (3/67) كلهم من طريق إسرائيل، عن أبي إسحاق، عن أبي عبيدة، عن عبد الله بن مسعود قال: فذكره.","وأبو عبيدة لم يسمع من أبيه."],"349":["لأن الله تعالى حرّم الظلم على نفسه كما جاء في الحديث الآتي:"],"350":["قوله: فَانْبِذْ إِلَيْهِمْ عَلَى سَوَاءٍ أي أعلمهم قبل حربك إياهم أنك قد فسخت العهد بينك وبينهم حتى تكون أنت وهم في العلم بنقض العهد سواء كما ثبت في الصحيح."],"351":["قوله: مِنْ قُوَّةٍ أي من الآلات التي تساعد على حرب العدو، ومن أهمها الرمي في القديم، والطائرات القاذفات في العصر الحديث."],"352":["كانت بين الأوس والخزرج من الأنصار العداوة والبغضاء، وكانت بينهم حروب كثيرة قبل الإسلام، فألف الله بينهم بالنبي صلى الله عليه وسلم."],"354":["قوله: تُرِيدُونَ عَرَضَ الدُّنْيَا يعني الفداء."],"355":["قوله: لَوْلَا كِتَابٌ مِنَ اللَّهِ سَبَقَ يعني لولا قضاء الله سبق في اللوح المحفوظ بأنه يحل لكم الغنائم؛ فإن الغنائم لم تحل لمن سبقكم، كما جاء في الحديث:"],"357":["قوله تعالى: أُولَئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ"],"360":["قوله تعالى: بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ بعد أربعة أشهر من يوم الحج الأكبر، وذلك إلى الذين لهم عهد من المشركين، فمن كان عهده أقل من أربعة أشهر رفعه إلى أربعة أشهر، ومن كانت مدة عهدهم أكثر من أربعة أشهر حطّه إلى أربعة أشهر، ومن كانتْ مدة عهده بغير أجل محدود حدّه بأربعة أشهر، ومن ليس له عهد فأجله انسلاخ الأشهر الحرم، ثم بعد ذلك جهاد وحرب.وقد بعث النبي صلى الله عليه وسلم عليا ببراءة كما في الصحيح:"],"362":["قوله: إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ يمكن أن يكون المراد منه العمارة المعروفة من بناء المساجد ومرمتها عند الخراب، ويمكن أن يكون المراد به عمارتها بملازمتها، والعبادة فيها من الصلاة وغيرها من أنواع الطاعات.وكلا المعنيين صحيحان.والآية الكريمة تشملهما.وعليهما يدلان الحديثان الآتيان:"],"366":["قوله: إِنَّمَا الْمُشْرِكُونَ نَجَسٌ المراد بالنجاسة هنا النجاسة المعنوية، فهم نجس دينا واعتقادا من أجل شركهم بالله عز وجل، ولو اغتسلوا من الجنابة والنجاسة لم يعودوا طاهرين بخلاف المسلم فإنه لا ينجس فإنه طاهر حسا ومعنى."],"367":["وقوله: وَهُمْ صَاغِرُونَ أي أذلاء مقهورون. ولا خلاف بين الفقهاء في أخذ الجزية من أهل الكتابين والمجوس، واختلفوا فيمن سواهم كما هو مبسوط في موضعه."],"368":["قوله: عُزَيْرٌ ابْنُ اللَّهِ عزير كان رجلا عالما في بني إسرائيل، فبعد تخريب بختنصر بيت المقدس، وإحراقه نُسخَ التوراة، أعاد عزير كتابة التوراة من جديد، فكبر شأنه في اليهود، واتخذوه ابنا لله، وقالوا: \"ما أوتي عزير هذا إلا أنه ابن الله، روي نحو هذا عن ابن عباس أيضا.وللموضوع تفصيل ذكرته في \" دراسات في اليهودية والمسيحية\"."],"370":["وقد حصل ذلك، وأشار إليه النبي صلى الله عليه وسلم في حديث عدي بن حاتم."],"371":["يعني العلماء والقراء من أهل الكتاب الذين يأخذون الرشا في أحكامهم ويحرفون التوراة من أجل ثمن قليل.ويدخل في هولاء من نهج منهجهم في أكل أموال الناس بالباطل من علماء المسلمين وعامتهم.","والكنز هو المال الذي لم تؤدّ زكاته، فإذا أُدّيت زكاته، فليس بكنز."],"372":["قوله: اثْنَا عَشَرَ شَهْرًا وهي: المحرم، وصفر، وربيع الأول، وربيع الآخر، وجمادى الأولى، وجمادى الأخرى، ورجب، وشعبان، ورمضان، وشوال، وذو القعدة، وذو الحجة.وهي اثنا عشر شهرا في كتاب الله- أي في حكم الله؛ لأن هذه الأشهر كل له أحكام تخصه من التعظيم والعبادات وغيرها.","قوله: مِنْهَا أَرْبَعَةٌ حُرُمٌ وهي ذوالقعدة، وذوالحجة، والمحرم، ورجب كما سيأتي في حديث أبي بكرة المذكور في تفسير الآية التي بعدها."],"373":["قوله: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ النسيء مصدر كالنذير ومعناه التأخير، يقال: أنسأ اللهُ في أجله أي: أخّره، ومنه النسيئة في البيع، كان العرب يؤخّرون شهراً إلى شهرٍ آخر لسببين:","أحدهما: لإباحة القتال، فإنّ تحريم الشهور الأربعة كان ثابتا من زمن إبراهيم وإسماعيل عليهما السلام، وكان معاشُهم على ما يغنمون في الحروب والغارات، فكان يشُقُّ عليهم أن يمكثوا ثلاثة أشهر متتالية لا يغزون فيها، وقالوا: إن توالت ثلاثةُ أشهر لا نغزو فيها نهلك، فكانوا يطلبون من رئيس القبيلة أن يؤخّر شهر المحرم إلى شهر صفر، فيستحلّون شهر المحرم للقتال، ويحرّمون على مكانه شهرَ صفر، فوبّخَهم الله في قوله: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عَامًا وَيُحَرِّمُونَهُ عَامًا","والثاني: كانوا يحاسبون الشهور بالسنة القمرية، فيقع الحج تارةً في الصيف، وتارةً في الشتاء، فإذا كان الحج في الصيف يشقُّ عليهم السفر إلى مكة المكرمة للتجارة في موسم الحج، فغيّروا السنة القمرية بالسنة الشمسية التي كانت زائدة على السنة القمرية شهرا كاملا بعد كل ثلاث سنين، ليكون رمضان في الصيف، لأنه سُمّيَ به، يقال: رَمَضَ الشيءُ: اشتدَّ حرُّه، ورمضت الأرضُ: اشتدّت عليها حرارة الشمس، ويكون الحج في الشتاء، فوبّخهم اللهُ تعالى في قوله: إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ","فلما رجعت الشهور على أصلها كما عيّنَه اللهُ تعالى يوم خلق السموات والأرض اختار النبي صلى الله عليه وسلم حجّه في تلك السنة، فكان حجُّه في شهر ذي الحجة، ومنذ ذلك اليوم تعين الوقت الأصلي، وبطل الوقت الجاهلي، وهذا معنى قول النبي صلى الله عليه وسلم: »استدار الزمانُ كهيئته...».وهو الحديث الآتي:"],"374":["هذه الآية نزلت في الحث على غزوة تبوك، وذلك أن النبي صلى الله عليه وسلم لما رجع من الطائف أمر بالجهاد لغزوة الروم، وكان ذلك في زمان عسرة من الناس، وشدة الحر، حين طابت الثمار والظلال.","قوله: فَمَا مَتَاعُ الْحَيَاةِ الدُّنْيَا فِي الْآخِرَةِ إِلَّا قَلِيلٌ"],"376":["قوله: ثَانِيَ اثْنَيْنِ أي هو أحد الاثنين، والاثنان هما: رسول الله صلى الله عليه وسلم وأبو بكر الصديق رضي الله عنه.وهذا أمر لا خلاف فيه بين المسلمين، ومن أنكر أن يكون الثاني هو أبو بكر فقد أنكر القرآن."],"377":["قوله: فِي سَبِيلِ اللَّهِ أي الّذي يقاتل لإعلاء كلمة الله فهو في سبيل الله."],"379":["روي عن جابر بن عبد الله قال: سمعت رسول الله صلى الله عليه وسلم يقول لجد بن قيس: ((يا جد هل لك في جلاد بني الأصفر؟)) قال جد: \"أو تاذن لي يا رسول الله؟ فاني رجل أحب النساء، وإني أخشى إن أنا رأيت نساء بني الأصفر، أن افتتن\".فقال رسول الله صلى الله عليه وسلم - وهو معرض عنه -: ((قد اذنت لك، فعند ذلك أنزل الله: وَمِنْهُمْ مَنْ يَقُولُ ائْذَنْ لِي وَلَا تَفْتِنِّي أَلَا فِي الْفِتْنَةِ سَقَطُوا","رواه ابن أبي حاتم في تفسيره (6/1809) عن دحيم بن إبراهيم الدمشقي، ثنا عبدالرحمن بن بشير، عن محمد بن إسحاق، ثنا سعيد بن عبد الرحمن بن حسان بن ثابت، عن جابر بن عبد الله، قال: فذكره.","وفي إسناده عبدالرحمن بن بشير وهو الشيباني، قال أبو حاتم: \"منكر الحديث\".","وسعيد بن عبد الرحمن بن حسان لم أجد له توثيقا، وإنما ذكره ابن حبان في ثقاته على قاعدته في توثيق من لم يعرف فيه جرح."],"380":["قوله: وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي الصَّدَقَاتِ أي يُعيبك في أمرها."],"381":["قوله: لِلْفُقَرَاءِ فهي للفقراء، وليست للأغنياء ولا للأقوياء القادرين على الكسب."],"383":["قوله: فَاسْتَمْتَعْتُمْ بِخَلَاقِكُمْ كَمَا اسْتَمْتَعَ الَّذِينَ مِنْ قَبْلِكُمْ بِخَلَاقِهِمْ وَخُضْتُمْ كَالَّذِي خَاضُوا أي اتبعتم طريقهم وسلكتم سبيلهم، وهذا وارد مورد التحذير من اتباع سبيلهم، كما جاء في الصحيح:"],"384":["قوله: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ أي إنهم يتناصرون ويتعاضدون فيما بينهم، كما جاء في الصحيح."],"385":["قوله: وَمَسَاكِنَ طَيِّبَةً أي حسنة البناء من لبنة الذهب والفضة."],"388":["هذه من صفات المنافقين أنهم لا يتركون أحدا من لمزهم، ولو كانوا مخلصين في أعمالهم."],"389":["قوله: اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ لفظه لفظة أمر، ومعناه خبر، وتقديره: استغفرت لهم أم لم تستغفر لهم لن يغفر الله لهم.","وجاء في سورة المنافقين سَوَاءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَنْ يَغْفِرَ اللَّهُ لَهُمْ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ [سورة المنافقون: ٦]"],"390":["الْمُخَلَّفُونَ أي عن غزوة تبوك. بِمَقْعَدِهِمْ أي بقعودهم خِلَافَ رَسُولِ اللَّهِ أي بعد رسول الله.","وكانت غزوة تبوك في شدة الحر.فقال تعالى: قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا"],"391":["قوله: وَلَا تُصَلِّ عَلَى أَحَدٍ أي أنّ الله منع رسول الله صلى الله عليه وسلم أن يصلي بعد هذا على أحد من المنافقين، فلم يثبت أنه صلى على أحد من المنافقين بعد ذلك.","وقد تقدمت في تفسير الآية رقم (80) عدة روايات في سبب نزول هذه الآية، وحاصلها أنها نزلت بعد ما صلى رسول الله صلى الله عليه وسلم على عبد الله بن أبي بن سلول."],"395":["قوله: أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ"],"396":["نزلت هذه الآيات في جماعة من المنافقين الذين بنوا مسجدا ضِرارا لمسجد قباء جاء في صحيح مسلم (2779: 9): \"في أصحابي اثنا عشر منافقا\".","إنْ كان هولاء فهذه أسماؤهم كما ذكرهم ابن أبي حاتم في تفسيره (6/1880)، والبغوي في تفسيره (2/324): وديعة بن ثابت، وجذام بن خالد، وثعلبة بن حاطب، وجارية بن عامر، وابناه مجمع وزيد، ومعتب بن قشير، وعباد بن حنيف أخو سهل بن حنيف، وأبو حبيبة بن الأزعر، ونبتل بن الحارث، وبجاد بن عثمان، ورجل يقال له: بَحْزَج."],"399":["قوله: سَاعَةِ الْعُسْرَةِ أي في زمن العسرة، وكانت غزوة تبوك تُسمى غزوة العسرة، والجيش يسمى جيش االعسرة. وقوله: كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ أي تميل إلى التخلف والانصراف للعسرة، فإنه قد همَّ فريق منهم بالتخلف ثم لحقوهم، لا المراد منه الزيغ عن الدين، وقد وصف شدة هذه الغزوة عمر بن الخطاب في الحديث الآتي:"],"401":["قال قتادة: هذه خاصة لرسول الله صلى الله عليه وسلم إذا غزا بنفسه لم يكن لأحد أن يتخلف عنه إلا بعذرٍ أو إذنٍ، وأما غيره من الأئمة والولاة فيجوز لمن شاء من المسلمين أن يتخلف عنه إذا لم يكن بالمسلمين إليه ضرورة.وقال غيره: أنها عامة لأول هذه الأمة وآخرها.روي ذلك عن الأوزاعي وابن المبارك وغيرهما.","قلت: القول الثاني له وجه قوي فإن الأئمة والولاة تبعا لخطاب النبي صلى الله عليه وسلم، فإذا وجب الخروج مع النبي صلى الله عليه وسلم فكذلك مع الائمة والولاة إلا بعذر أو بإذن."],"402":["مِنْ أَنْفُسِكُمْ أي: من جنسكم، تعرفون نسبه وحسبه، وهو من العرب مثلكم من بني إسماعيل بن إبراهيم عليهما السلام، وهو من دعوة إبراهيم عليه السلام: رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِنْهُمْ [سورة البقرة: ١٢٩].","وقد امتن الله تعالى في موضع آخر فقال: لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِنْ أَنْفُسِهِمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَإِنْ كَانُوا مِنْ قَبْلُ لَفِي ضَلَالٍ مُبِينٍ [آل عمران: ١٦٤] وغيرها من الآيات.","كما قال جعفر بن ابي طالب للنجاشي، والمغيرة بن شعبة لرسول كسرى: إن الله بعث فينا رسولا منا، نعرف نسبه وصفته، ومدخله ومخرجه، وصدقه وأمانته فذكر الحديث، لما كان الأمر هكذا فلم تكفرون بهذا النبي الكريم وما جاء به، مع أنه حريص على إيمانكم وصلاحكم، ورؤوف رحيم بمن آمن به."],"404":["أي لو استجاب الله دعاءهم بالشر كما يستجيب دعاءهم بالخير لأهلكهم، وهذا كقوله: وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ وَكَانَ الْإِنْسَانُ عَجُولًا [سورة الإسراء: ١١]، لذا جاء النهي أن يدعوا الإنسان على نفسه وأهله وماله."],"405":["هو كقوله تعالى: ﴿وَإِذَا مَسَّهُ الشَّرُّ فَذُو دُعَاءٍ عَرِيضٍ﴾ [سورة فصلت: ٥١]","واستثنى الله من هولاء كما قال تعالى: إِلَّا الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِ [سورة هود: ١١]، فالمؤمن يشكر في السراء ويصبر في الضراء كما جاء في الصحيح:"],"406":["وذلك من تعنتهم وعنادهم، حتى لو أنزل الله عليهم قرآنا آخر لكذبوه أيضا.","وقوله: فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِنْ قَبْلِهِ أي قبل أن أكون نبيا وهو أربعون سنة، فهل أخذتم علي الكذب، بل العكس من ذلك كانوا سموه أمينا وصادقا.وقصة أبي سفيان مع هرقل مشهورة حين سأله: \"هل كنتم تتهمونه بالكذب قبل أن يقول ما قال؟\" قال أبو سفيان: \"لا \".وكان يومئذ زعيم المشركين.","وقال جعفر بن أبي طالب للنجاشي ملك الحبشة: بعث الله فينا رسولا نعرف نسبه، وصدقه، وأمانته، وقد كانت مدة مقامه بين أظهرنا قبل النبوة أربعين سنة.انظر تفاصيل ذلك في جزء السيرة النبوية."],"407":["أي لا أحد أظلم وأشد جرما ممن تقول على الله، وزعم أن الله أرسله، فإن من كذب على الله فإن الله فضحه، وجعله من الخاسرين مثل مسيلمة الكذاب الذي ادعى النبوة، ففضحه الله تعالى، وجعله من الخاسرين، ومثل غلام أحمد القادياني الذي ادعى النبوة، وهو كاذب.وقد أظهر الله كذبه للناس، وبينهما أناس آخرون ادعوا النبوة، فكان أمرهم مثل هولاء؛ لأن الله تعالى لن يترك أحدا يكذب عليه، ويدعي أنه أرسله لما في ذلك من المفسدة على الخلق أجمعين."],"409":["وقوله: لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ الحسنى هي الجنة.","والزيادة هي: تضعيف الأعمال من عشر أمثالها إلى سبعمائة ضعف.وهذا قول ابن عباس وأصحابه.","ومن الزيادة النظرُ إلى وجه الله الكريم، فإنه زيادة أعظم من جميع ما أعطوه.وهو قول جماعة من الصحابة منهم: أبو بكر وحذيفة وأبو موسى وعبادة بن الصامت.","وقد جاء في الصحيح:"],"410":["قوله: وَتَرْهَقُهُمْ أي تعتريهم، وتعلوهم ذلة من معاصيهم وخوفهم منها.كما قال تعالى في سورة الشورى [45]: وَتَرَاهُمْ يُعْرَضُونَ عَلَيْهَا خَاشِعِينَ مِنَ الذُّلِّ يَنْظُرُونَ مِنْ طَرْفٍ خَفِيٍّ."],"411":["قوله: تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ أي أنه مصدقا للكتب السابقة بأنها من عند الله من حيث الجملة، وإن كان وقع فيها من التحريف والتغيير، ومع ذلك فيها من الأخبار مايصدقها القرآن مثل البشارة ببعث النبي صلى الله عليه وسلم، وصفاته وأخلاقه.","قوله: وَتَفْصِيلَ الْكِتَابِ أي الكتب كلها؛ لأن تعريف الكتاب تعريف الجنس، فيستغرق جميع الكتب.ومعنى كون القرآن تفصيلا لها: أنه مبين لما جاء مجملا في الكتب السالفة من الأحكام والأخبار، وناسخا لما لا مصلحة للناس في دوام حكمه، ودافعا للمتشابهات التي ضل فيها أهل الكتاب، ومبينا ومميزا عما زيد فيها، وأسيء فهمها."],"412":["لأنه في جميع أعماله متفضل عادل، وجاء في الصحيح:"],"413":["أنكر الله تعالى على المشركين الذين حرموا وحلّلوا مثل تحريمهم: البحيرة، والسائبة، والوصيلة، والحام وغيرها من الأنعام، ومن الحرث ما يجعلونها لأوثانهم كما قال تعالى: وَجَعَلُوا لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعَامِ نَصِيبًا فَقَالُوا هَذَا لِلَّهِ بِزَعْمِهِمْ وَهَذَا لِشُرَكَائِنَا فَمَا كَانَ لِشُرَكَائِهِمْ فَلَا يَصِلُ إِلَى اللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَى شُرَكَائِهِمْ سَاءَ مَا يَحْكُمُونَ (136) وَكَذَلِكَ زَيَّنَ لِكَثِيرٍ مِنَ الْمُشْرِكِينَ قَتْلَ أَوْلَادِهِمْ شُرَكَاؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ وَلَوْ شَاءَ اللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ (137) [الأنعام: ١٣٦ – ١٣٨]"],"414":["قوله: أَوْلِيَاءَ اللَّهِ هم الذين ذكرهم الله تعالى في الآية التي بعدها وهم الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ يعني كل من وُصف بالإيمان والتقوى فهو من أولياء الله، وقد جاء في الأحاديث والآثار أن المتحابين في الله أيضا من الأولياء."],"415":["قوله: لَهُمُ الْبُشْرَى أي لأولياء الله، والبشرى في الدنيا: الثناء الحسن، وفي الآخرة: الجنة."],"416":["ظاهر القرآن يشير إلى أن موسى عليه السلام طلب أولا من فرعون خروج بني إسرائيل من مصر كما جاء في [سورة الشعراء: 17] أَنْ أَرْسِلْ مَعَنَا بَنِي إِسْرَائِيلَ","لما أبى فرعون من ذلك أمر الله موسى عليه السلام أن يخرج بهم ليلا وَلَقَدْ أَوْحَيْنَا إِلَى مُوسَى أَنْ أَسْرِ بِعِبَادِي فَاضْرِبْ لَهُمْ طَرِيقًا فِي الْبَحْرِ يَبَسًا لَا تَخَافُ دَرَكًا وَلَا تَخْشَى (77) فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ فَغَشِيَهُمْ مِنَ الْيَمِّ مَا غَشِيَهُمْ (78) [طه: ٧٧ – ٧٨]","قوله تعالى: وَجَاوَزْنَا بِبَنِي إِسْرَائِيلَ الْبَحْرَ أي عبرنا بهم وكان عددهم نحو ست مائة ألف ماش من الرجال عدا الأولاد كما في سفر الخروج (12: 37)، وكانت إقامتهم مصر أربع مائة وثلاثين سنة كما في سفر الخروج أيضا (12: 40)، وفي الأمرين مبالغة كما بينتُ ذلك في كتابي \"اليهودية والمسيحية\".","فنجّى الله بني إسرائيل من ظلم فرعون وهو منفتاح الذي كان حاكما على مصر (1232- 1211 ق م)، وكان مصيره الغرق.","قوله: ﴿آمَنْتُ أَنَّهُ لَا إِلَهَ إِلَّا الَّذِي آمَنَتْ بِهِ بَنُو إِسْرَائِيلَ وَأَنَا مِنَ الْمُسْلِمِينَ فهو آمن بعد ما رأى الآيات وغشيته سكرات الموت، وفي ذلك الوقت لا ينفع نفسا إيمانها لم تكن آمنت من قبل، قال تعالى: فَلَمَّا رَأَوْا بَأْسَنَا قَالُوا آمَنَّا بِاللَّهِ وَحْدَهُ وَكَفَرْنَا بِمَا كُنَّا بِهِ مُشْرِكِينَ فَلَمْ يَكُ يَنْفَعُهُمْ إِيمَانُهُمْ لَمَّا رَأَوْا بَأْسَنَا سُنَّتَ اللَّهِ الَّتِي قَدْ خَلَتْ فِي عِبَادِهِ وَخَسِرَ هُنَالِكَ الْكَافِرُونَ﴾ [سورة غافر: ٨٤ – ٨٥]"],"420":["قوله: إِلَّا الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ أي الذين صبروا في الشدائد والمكاره، وعملوا الصالحات في الرخاء والعافية لهم أجر ومغفرة.وليس ذلك إلا للمؤمن كما جاء في الصحيح:"],"423":["ذكر محمد بن إسحاق عن التوراة: أن الله أمره أن يصنعها من خشب الساج، وأن يجعل طولها ثمانين ذراعا، وعرضها خمسين ذراعا.هذا ما نقله ابنُ كثير عن ابن إسحاق.","والذي في التوراة الموجودة: طولها مائة وخمسون ذراعا، وعرضها خمسة وعشرون ذراعا، وارتفاعها خمسة وعشرون ذراعا.[لتكوين: 15] والله أعلم بالصواب."],"424":["قوله: وَأَهْلَكَ الأهل يُطلق في اللغة على الأقارب من الأبناء والأحفاد والزوجات، وهم المراد هنا، لأن الذين ركبوا مع نوح في السفينة أولاده الثلاثة، سام، وحام، ويافث، وزوجاتهم، وأما الابن الرابع يام فكان من الغارقين.","وإنْ كان المتبادر إلى الأذهان من الأهل الزوجة، مثل قوله: فَلَمَّا قَضَى مُوسَى الْأَجَلَ وَسَارَ بِأَهْلِهِ آنَسَ مِنْ جَانِبِ الطُّورِ نَارًا قَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَعَلِّي آتِيكُمْ مِنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِنَ النَّارِ لَعَلَّكُمْ تَصْطَلُونَ [القصص: ٢٩]","فإنْ كان المراد من الأهل في الآية الزوجة فتكون هي غير التي جاء ذكرها في سورة التحريم: ضَرَبَ اللَّهُ مَثَلًا لِلَّذِينَ كَفَرُوا امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ اللَّهِ شَيْئًا وَقِيلَ ادْخُلَا النَّارَ مَعَ الدَّاخِلِينَ [التحريم: ١٠ ]","يعني أن هذه الخائنة المذكورة في سورة التحريم تدخل النار لأنها سبق عليها القول، فالمراد بالأهل هنا لعلها زوجة أخرى آمنت به مع أولاده.","وقد جاء ذكرُ هذه المرأة وأبنائه الثلاثة، وأبناء الأبناء الذين حملهم نوح عليه السلام في السفينة في التوراة أيضا [التكوين 18: 6].وأهملت التوراةُ الموجودةُ ذكرَ المرأة الخائنة والولد الرابع \"يام\" الذي غرق.","وأما عددهم فكان قليلا كما في نص التنزيل، وما ذُكِرَ من عددهم أنهم كانوا كذا وكذا فهذا كله ظنّ وتخمين، وقيل: إنما كان نوح وأبناؤه الثلاثة سام وحام ويافث وأزواجهم وأولادهم، ومنهم تسلسلَ نسل بني آدم، وأما غير أهله الذين آمنوا وهم قليلون فلم يتسلسل نسلهم. وأما مُدّة بقائهم في السفينة فأكثرها مائة وخمسون يوما كما قال كعب الأحبار، وهو موافق لما في التوراة اليوم.[التكوين: 24: 7] وأما مدة المطر فكانت أربعين يوما. التكوين (4: 7).والله أعلم بالصواب."],"425":["قالت ذلك سارة زوجة إبراهيم لما بشّرت بإسحاق أنها تلده تعجبا لأنها بلغت السن التي لا يلد من كان قد بلغها من الرجال والنساء.","قال ابن إسحاق: كانت سارة يوم بشرت بإسحاق فيما ذكر لي بعض اهل العلم: ابنة تسعين سنة، وإبراهيم ابن عشرين ومئة.رواه ابن جرير وغيره.","وقوله: أَهْلَ الْبَيْتِ أي بيت إبراهيم، وقد كان النبي صلى الله عليه وسلم علّمنا كيف نصلّي عليه، وعلى آل إبراهيم؟"],"426":["جواب \"لو\" محذوف أي لقاتلتُ عنكم أو لمنعتكم عما يريدون."],"427":["يخاطب شعيب عليه السلام قومه، وكان مسكنه مدينة مدين عند خليج عقبة فيقول لهم: يصيبكم مثل ما أصاب قوم نوح من الغرق، وقوم هود من العذاب، وقوم صالح من الرجفة، وقوم لوط الذين كان مسكنهم قريبا من مسكنكم –يعني السدوم- أو قريبَ عهدٍ بالعذاب بعد قوم نوح وعاد وثمود."],"430":["قوله: طَرَفَيِ النَّهَارِ بداية من الصبح إلى قبل غروب الشمس.","قوله: وَزُلَفًا مِنَ اللَّيْلِ ابتداء من المغرب ثم العشاء ثم إلى قبل طلوع الفجر.","ويحتمل أن يكون ذلك قبل فرض الصلوات الخمس ليلة الإسراء، فإنه صلى الله عليه وسلم أمر بأداء الصلوات قبل ذلك من غير تحديد عددها أسوة بالأنبياء الآخرين، ثم نسخ ذلك بخمس صلوات."],"433":["وذلك أن رؤيا الأنبياء وحي، وعلم يعقوب عليه السلام أن الإخوة إذا سمعوها حسدوه، فأمره بالكتمان لأن الشيطان يزيّن لهم السوء، ويحملهم على الكيد، وقد جاء في الصحيح:"],"434":["قوله: وَكَذَلِكَ يَجْتَبِيكَ رَبُّكَ أي يختارك للنبوة والرسالة.","وقوله: وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ أي بالنبوة.","وقوله: وَعَلَى آلِ يَعْقُوبَ أي يجعل من أولاده الأنبياء والرسل.","وقوله: يَعْقُوبَ كَمَا أَتَمَّهَا عَلَى أَبَوَيْكَ مِنْ قَبْلُ إِبْرَاهِيمَ وَإِسْحَاقَ أي جعلهما نبيين، وقد جاء في الصحيح:"],"435":["قوله: وَجَاءُوا عَلَى قَمِيصِهِ بِدَمٍ كَذِبٍ أي بدم مفترى عليه، وهو ليس دم يوسف، وإنما هو دم حيوان آخر عملوا ذلك ليوهموا أباهم يعقوب عليه السلام بأن الذئب قد أكل يوسف، وعرف كذبهم أبوهم فقال: بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا ولكن أنا أصبر على ما تقولون.ومثّلتْ به عائشة رضي الله عنها حين افتري عليها، كما في الحديث الآتي:"],"436":["قوله: وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَرَاهِمَ مَعْدُودَةٍ أي باعوه بثمن قليل، والبخس هو النقص كما قال تعالى: فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا","قوله: وَكَانُوا فِيهِ مِنَ الزَّاهِدِينَ أي ليس لهم رغبة فيه ولا في ثمنه، بل لو سألوه بلا شيء لأجابوا."],"437":["قوله: وَرَاوَدَتْهُ أي راوغتْه لحسنه وجماله، فحملها ذلك على أن تجملت له، وغلّقت الأبواب، ودعتْه إلى نفسها."],"438":["قوله: وَهَمَّ بِهَا لَوْلَا أَنْ رَأَى بُرْهَانَ رَبِّهِ جملة مستأنفة، وليست معطوفة على قوله: وَلَقَدْ هَمَّتْ بِهِ، وقُدِّمَ جواب الشرط لأهميته أي: لولا أن رأى برهان ربه لهمَّ بها، ومعناه: أنه لم يهمّ بها، لأنه رأى برهان ربه، وبذلك يظهر أن يوسف عليه السلام لم يخالطه همٌّ بامرأة العزيز؛ لأن الله تعالى عصمه من الهمّ بالمعصية.","قال أبوحاتم: كنت أقرا غريب القرآن على أبي عبيدة فلما أتيت على قوله: وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِهَا الآية، قال أبو عبيدة: هذا على التقديم والتأخير أي تقديم الجواب وتأخير الشرط كأنه قال: ولقد همّت به ولولا أن رأى برهان ربه لهمَّ بها.","وقوله: لَوْلَا أَنْ رَأَى بُرْهَانَ رَبِّهِ أي أنه استشعر في قلبه عظمة الله سبحانه وتعالى، وأنه بكل شيء محيط."],"439":["وقوله: وَشَهِدَ شَاهِدٌ مِنْ أَهْلِهَا الظاهر منه أنه رجل كبير، وقد قال ابن عباس: \"كان ذا لحية\" كما عند ابن جرير في تفسيره.","وأما ما روي من حديث أبي هريرة مرفوعا: ((لم يتكلم في المهد إلا ثلاثة: عيسى بن مريم، وشاهد يوسف، وصاحب جريج، وابن ماشطة بنت فرعون)) فهو ضعيف.","رواه الحاكم (2/595) عن أبي الطيب محمد بن محمد الشعيري، ثنا السري بن خزيمة، ثنا مسلم بن إبراهيم، ثنا جرير بن حازم، ثنا محمد بن سيرين، عن أبي هريرة فذكره.وقال: \"صحيح الإسناد على شرط الشيخين\".","قلت: ليس كما قال، بل فيه أناس لا يُعرفون، ثم في متنه قال: لم يتكلم في المهد إلا ثلاثة، وذكر عند التفصيل أربعة.","وهو في الصحيحين من طريق جرير بن حازم، وليس فيه ذكر شاهد يوسف ولا ابن ماشطة ابنة فرعون فهي زيادة منكرة.","ورواه أحمد (2821) عن ابن عباس موقوفا قال: تكلم أربعة صغار: عيسى بن مريم عليه السلام، وصاحب جريج، وشاهد يوسف، وابن ماشطة ابنة فرعون.","وهذا يخالف قول ابن عباس كما سبق ذكره من تفسير ابن جرير."],"440":["وقوله: وَقُلْنَ حَاشَ لِلَّهِ مَا هَذَا بَشَرًا إِنْ هَذَا إِلَّا مَلَكٌ كَرِيمٌ أي: قلن ذلك لحسنه وجماله، فقد كان يوسف عليه السلام أعطي شطر الحسن، كما جاء في الصحيح:"],"441":["قوله: قَالَ رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ استعمل صيغة الجمع للإشارة إلى أن صواحب امرأة العزيز أيضا أرَدْنَ منه السوءَ.","ثم قال: وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ استعمل أيضا صيغة الجمع، وطلب من الله العون والمنعة في مراودتهن إياه على أنفسهن.","وقوله: أَصْبُ إِلَيْهِنَّ أي أميل إليهن مثل قول القائل: صبا فلان إلى كذا.","وقوله: فَاسْتَجَابَ لَهُ رَبُّهُ مع أنه لم يدع الله بصرف كيدهن، ولكن شكواه وإخباره بأن السجن أحبّ إليّ يتضمن الدعاء، فاستجاب اللهُ ليوسف دعاءه، فصرف عنه ما أرادت منه امرأة العزيز وصواحباتها من معصية الله.","وجاء في الصحيح:"],"442":["قوله: وَقَالَ الْمَلِكُ ائْتُونِي بِهِ أي أخرجوه من السجن."],"443":["يعني جزاء السارق في شريعة يعقوب أن يسلم السارق إلى المسروق منه فيسترقّه سنةً بخلاف قانون ملك مصر فإنه يمنع حبس السارق، فأراد يوسف أن يحبس أخاه عنده فردَّ الحكم إليهم ليتمكن من حبسه عنده على حكمهم، ولم يجر فيه قانون الملك الذي لم يذكر في القرآن والأحاديث.وقد قيل:: إن من قانون الملك أن يُضرب السارق، وقيل: يغرم السارق ضعفَيْ قيمة المسروق وقيل: غير ذلك.","وهذه الأقاويل رويت عن بعض التابعين وليس فيها شيء مرفوع."],"444":["قوله: فَقَدْ سَرَقَ أَخٌ لَهُ مِنْ قَبْلُ أي أن بنيامين الذي وجد السقاية في رحله هو أخوه لأمه من زوجة أبينا \"راحيل\" فهما شقيقان، وأما نحن من أولاد زوجاته الأخرى، فإن ليعقوب عليه السلام أربع زوجات وهن: راحيل أم يوسف وبنيامين، وليئة وبُلهة وزلفة، وهن أمهات بقية أولاد يعقوب.","وأما كون أخيه سرق من قبل فهذا بهتان وكذب منهم، فإن يوسف عليه السلام بريء من هذه التهمة، ولكنهم أرادوا نفي العار عن أنفسهم، وكان ذلك في مجلس يوسف ولكنه لم يظهر الغضب على كذبهم لئلا ينكشف أمره بأنه هو يوسف.","قوله: فَأَسَرَّهَا يُوسُفُ فِي نَفْسِهِ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنْتُمْ شَرٌّ مَكَانًا","وضمير التأنيث راجع إلى الكلمة التي قالها يوسف وهي قوله: أَنْتُمْ شَرٌّ مَكَانًا وَاللَّهُ أَعْلَمُ بِمَا تَصِفُونَ ذكرها سرّا في نفسه، ولم يصرح بأنكم كذابون في دعواكم.","وأما ما ذكره كثير من المفسرين من الروايات في بيان سرقة يوسف عليه السلام فكلها ضعيفة ومعلولة، ليس فيها شيء ثابت عن النبي صلى الله عليه وسلم."],"445":["قوله: وَخَرُّوا لَهُ سُجَّدًا أي: أبوه وأمه وإخوته، سجودا على وجه التعظيم والتبجيل والإكرام، وكان سائغا في شرائعهم، وحرم في هذه الملة، وجعل السجود مختصا بجانب الرب سبحانه وتعالى، كما جاء في الحديث:"],"446":["قوله: أَنَّهُمْ قَدْ كُذِبُوا بالتخفيف في قرأة الجمهور، وفي قرأة نافع، وابن كثير، وأبي عمرو، وابن عامر، ويعقوب كُذِّبوا بالتشديد، وهي مروية عن عائشة كما جاء في الصحيح:"],"448":["وقوله: قِطَعٌ مُتَجَاوِرَاتٌ أي أراضٍ يجاور بعضها بعضا، ومع ذلك فهذه طيبة، تُنبِت ما يفيد الناس، وهذه سَبَخة مالحةلا تنبت شيئا.","وكذلك يدخل في هذه الآية اختلاف ألوان بقاع الأرض، فهذه حمراء، وهذه بيضاء، وهذه سوداء، وهذه كذا وكذا.وهذا يدل على أن فاعلها قادر وحكيم.","وقوله: وَنُفَضِّلُ بَعْضَهَا عَلَى بَعْضٍ فِي الْأُكُلِ"],"454":["قوله: وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ أي: أنهم لا يقرون بهذا الاسم لله تعالى، ويأنفون من وصف الله بالرحمن والرحيم، فقد رفض المشركون يوم الحديبية أن يكتبوا: \"بسم الله الرحمن الرحيم\" كما جاء في الصحيح:"],"456":["قوله: أُكُلُهَا دَائِمٌ وَظِلُّهَا أي نعيم الجنة من المطاعم والفواكه والمشارب والسكن المريح والظل وغيرها ليس لشيء منها انقطاع ولا فناء، كما جاء في الصحيح."],"457":["أي أن الله ينسخ من الأقدار ما يشاء ويثبت منها ما يشاء، وقد يجعل له سببا ظاهرا كصلة الرحم والدعاء، وأعمال البر عموما، وقد يكون دون سبب ظاهر، وعلمه عند الله.فينبغي للإنسان أن يستمر في الدعاء والبر والصلة كما جاء عن عمر بن الخطاب أنه قال وهو يطوف بالبيت ويبكي: \"اللهم إن كنت كتبت علي شقوة أو ذنبا فامحه، فإنك تمحو ما تشاء وتثبت، وعندك أم الكتاب، فاجعله سعادة ومغفرة\".رواه ابن جرير في تفسيره (13/563) بسند حسن.","وكذلك جاء عن ابن مسعود أنه كان يقول: \"اللهم إن كنت كتبتني في أهل الشقاء فامحني وأثبتني في أهل السعادة\".","رواه ابن جرير (13/564) بإسناد جيد.وقد جاء في الصحيح:"],"459":["أي: هذه سنة الله في خلقه أنه ما بعث نبيا في أمة إلا أن يكون بلغتهم، فاختص كل نبي بإبلاغ رسالته إلى أمته دون غيرهم، واختص محمد بن عبد الله رسول الله صلى الله عليه وسلم بعموم الرسالة إلى سائر الناس، كما ثبت في الصحيح:"],"460":["قوله: بِآيَاتِنَا هي تسع آيات كما في سورة بني إسرائيل وَلَقَدْ آتَيْنَا مُوسَى تِسْعَ آيَاتٍ بَيِّنَاتٍ فَاسْأَلْ بَنِي إِسْرَائِيلَ إِذْ جَاءَهُمْ فَقَالَ لَهُ فِرْعَوْنُ إِنِّي لَأَظُنُّكَ يَا مُوسَى مَسْحُورًا [الإسراء: ١٠١] وتفصيلها في سورة الأعراف [130-135] وَلَقَدْ أَخَذْنَا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَذَّكَّرُونَ (130) فَإِذَا جَاءَتْهُمُ الْحَسَنَةُ قَالُوا لَنَا هَذِهِ وَإِنْ تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا بِمُوسَى وَمَنْ مَعَهُ أَلَا إِنَّمَا طَائِرُهُمْ عِنْدَ اللَّهِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ (131) وَقَالُوا مَهْمَا تَأْتِنَا بِهِ مِنْ آيَةٍ لِتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ (132) فَأَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ آيَاتٍ مُفَصَّلَاتٍ فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا مُجْرِمِينَ (133) وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِنْدَكَ لَئِنْ كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرَائِيلَ (134) فَلَمَّا كَشَفْنَا عَنْهُمُ الرِّجْزَ إِلَى أَجَلٍ هُمْ بَالِغُوهُ إِذَا هُمْ يَنْكُثُونَ (135) وهذه تسع آيات شاهدها فرعون وقومه المصريون، ثم أُتِيَ آيات أخرى في سيناء مثل ضرب الحجر بالعصا، وتظليلهم الغمام، وإنزال المن والسلوى وغيرها.","قوله: بِأَيَّامِ اللَّهِ أي بنعماء الله التي أنعم الله بها عليهم في الأيام التي خلت مثل إنقاذهم من ظلم فرعون، وإنزال المنّ والسلوى عليهم وغير ذلك."],"462":["أي أن الله أهلك أمما من العرب وغير العرب بعد ثمود فانقطعت أخبارهم فلا يعلم أحد إلا الله سبحانه وتعالى فلا يجوز لأحد أن ينسب نفسه إلا ما يعلمه كما كان النبي صلى الله عليه وسلم ينسب نفسه إلى عدنان ثم يمسك.ذكره البخاري في مناقب الأنصار، باب مبعث النبي صلى الله عليه وسلم، وبين عدنان وبين إسماعيل عليه السلام لا يعرف عددهم.","فقوله تعالى: لَا يَعْلَمُهُمْ إِلَّا اللَّهُ فيه ردّ على توراة اليهود التي ذكرت فيها أنساب آدم وأبناؤه إلى من بعدهم في سفر التكوين."],"463":["قوله: وَيَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ أي من كل أعضائه من جسمه.","قال ابن عباس: أنواع العذاب الذي يُعذّبه الله بها يوم القيامة في نار جهنم، وليس منها نوع إلا الموت يأتيه منه لو كان يموت، ولكن لا يموت، لأن الله تعالى قال: وَالَّذِينَ كَفَرُوا لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا كَذَلِكَ نَجْزِي كُلَّ كَفُورٍ (36) [فاطر: ٣٦] كما قال في الآية المذكورة: وَمَا هُوَ بِمَيِّتٍ هو في عذاب غليظ مستمر."],"464":["قوله: كَلِمَةً طَيِّبَةً هي: لا إله إلا الله.وقوله: كَشَجَرَةٍ طَيِّبَةٍ هي النخلة."],"465":["قوله: بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا هي كلمة التوحيد قبل الموت. وَفِي الْآخِرَةِ يعني القبر كما جاء في الصحيح:"],"467":["قوله: رَبِّ اجْعَلْ هَذَا الْبَلَدَ آمِنًا استجاب الله دعاء إبراهيم عليه السلام فجعل مكة بلدا آمنا كما قال تعالى في سورة العنكبوت [67] أَوَلَمْ يَرَوْا أَنَّا جَعَلْنَا حَرَمًا آمِنًا وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ أَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ وقال في سورة آل عمران [97] فِيهِ آيَاتٌ بَيِّنَاتٌ مَقَامُ إِبْرَاهِيمَ وَمَنْ دَخَلَهُ كَانَ آمِنًا وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَنْ كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ عَنِ الْعَالَمِينَ.","قوله: وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ أي أبعدني، أمرٌ من الثلاثي المجرد يقال: جنبه الشيء إذا جعله جانبا عنه أي أبعده عنه.استجاب الله دعاءه فيه وفي أولاده من صلبه وهما إسماعيل وإسحاق، فلم يقع منهما الشرك وعبادة الأصنام، وهذا الدعاء كان منه للتثبت على التوحيد لما رأى أن كثيرا من الناس ابتلوا بعبادة الأصنام مثل ودّ وسواع ويغوث ويعوق ونسر أصنام قوم نوح، ومثل الأصنام التي عبدها قوم إبراهيم في العراق، ومثل الأصنام التي عبدها أقوام أخرى في فلسطين والشام ومصر كما يدل عليه قوله: رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ لا أنه كان خائفا من الوقوع في الشرك وعبادة الأصنام، لأن الأنبياء معصومون عن الشرك بالله.وقيل: المراد منه أولاده من صلبه جميعا فلم يقع الشرك فيهم، وإنما وقعَ الشركُ فيمن جاء بعدهم.","وقد فهم بعض المفسرين من قوله: رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ بأن الشرك كان قد وقع في مكة قبل إبراهيم عليه السلام، واستدلوا في ذلك بآية من سورة البقرة [125]: وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِلنَّاسِ وَأَمْنًا وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى وَعَهِدْنَا إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ أَنْ طَهِّرَا بَيْتِيَ لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ.","والصحيح في هذا أن الله أمر إبراهيم وإسماعيل أن يبنيا البيت على الطهارة للطواف، والاعتكاف، والركوع، والسجود لله وحده بخلاف ما كان الناس في عهده في العراق، والشام، ومصر وغيرها من البلدان ابتلوا بالشرك وعبادة الأصنام، وأما القول بأن مكة كان ماهولة بالسكان قبل إبراهيم، وأنهم ابتلوا بالشرك فيحتاج إلى دليل واضح من الكتاب والسنة الصحيحة، ولا دليل عليه.","قوله: فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي أي من أولاده مثل الأنبياء والمؤمنين بهم، وآخرهم محمد بن عبد الله صلى الله عليه وسلم ومن آمن به، فهولاء كلهم على ملة إبراهيم سواء كانوا من نسله أو من غير نسله.","وقوله: وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ ولو كانوا من نسلي فأنا أتبرأ منهم، وأفوّض أمرهم إلى رحمتك وغفرانك، وليس المقصود منه الدعاء بالمغفرة لمن عصى، فإنه لا يدعو لهم، وهذا يدل على حلمه وصبره فلم يدع عليهم بالهلاك والاستئصال، وكان النبي صلى الله عليه وسلم على هديه كما جاء في الصحيح:"],"468":["قوله: تَشْخَصُ فِيهِ الْأَبْصَارُ أي أجفانهم لا تطرف من هول ما ترى في ذلك اليوم.يقال: فلان شخص بصره أي لم يغمضه.","وقوله: مُهْطِعِينَ مصوبين بصرهم لا يلتفتون يمينا ولا شمالا، ولا يعرفون مواطن أقدامهم، يقال: هطع الرجل ببصره إذا صوبه، وبعير مهطع إذا صوب عنقه.","وقوله: مُقْنِعِي رُءُوسِهِمْ أي رافعي رؤوسهم، أي أن وجوه الناس يوم القيامة إلى السماء، لا ينظر أحد إلى أحد، كما قال الحسن البصري.","وقوله: وَأَفْئِدَتُهُمْ هَوَاءٌ أي خالية لا تعي شيئا، ولا تعقل من شدة الخوف، كأن القلوب قد زالت عن أماكنها."],"469":["قوله: يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ أي تكون الأرض المبدّلة يوم القيامة أرضا بيضاء، عفراء كما جاء في الصحيح:"],"470":["قوله: سَرَابِيلُهُمْ مِنْ قَطِرَانٍ أي قمصهم، واحدها سربال.والقطران ما يتقطر من الهناء، وهو الذي تهنأ به الإبل، أي تطلى، وهو نوع من المرهم من تركيب كيمياوي قديم، وهو شديد الحرارة، ويشبه اليوم السائل الذي تطلى به الشوارع، ويسمى الزفت، فيؤلم الجلد، وهو لباسهم قبل دخول النار.وقد جاء في الصحيح:"],"472":["من المشهور أن الكافر يقول ذلك عند ما يرى أن المؤمنين يخرجون من النار بشفاعة النبي صلى الله عليه وسلم كما جاء في الصحيح:"],"473":["قوله: الذِّكْرَ هو القرآن الكريم.","وقوله: وَإِنَّا لَهُ لَحَافِظُونَ أي من التغيير والتبديل والزيادة والنقصان، بأن هيأ الله تعالى أسباب حفظه، فجعله أولا ثابتا في قلب النبي صلى الله عليه وسلم، ثم أن النبي صلى الله عليه وسلم علم أصحابه، فحفظه عدد لا يحصى من الصحابة عن ظهور قلوبهم في حياة النبي صلى الله عليه وسلم وبعد وفاته، وعن الصحابة تواتر حفظه في جميع البلاد الإسلامية، واستمر ذلك إلى يومنا هذا.هكذا أراد الله تعالى أن يبقى كتابه محفوظا إلى يوم القيامة بخلاف الكتب الأخرى، فإن الله تعالى لم يضمن لها حفظها، ولم يرد لها البقاء إلى يوم القيامة، ولذا وقع فيها ما وقع من التبديل والتحريف والضياع.","حكى القاضي عياض في المدارك أن القاضي إسماعيل بن إسحاق بن حماد المالكي البصري سئل عن السر في تطرق التغيير للكتب السابقة وسلامة القرآن من ذلك، فأجاب بأن الله أوكل للأحبار حفظ كتبهم، فقال: بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللَّهِ. [المائدة: 44] وتولى حفظ القرآن بذاته تعالى، فقال: إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ.","وذكر القرطبي في تفسيره (10/5-6) عن يحيى بن أكثم قال: كان للمأمون- وهو أمير إذ ذاك- مجلس نظر، فدخل في جملة الناس رجل يهودي حسن الثوب حسن الوجه طيب الرائحة، قال: فتكلم فأحسن الكلام والعبارة، قال: فلما أن تقوض المجلس دعاه المأمون، فقال له: إسرائيلي؟ قال نعم.قال له: أسلم حتى أفعل بك وأصنع، ووعده.فقال: ديني ودين آبائي! وانصرف.قال: فلما كان بعد سنة جاءنا مسلما، قال: فتكلم على الفقه، فأحسن الكلام، فلما تقوض المجلس دعاه المأمون، وقال: ألست صاحبنا بالأمس؟ قال له: بلى.قال: فما كان سبب إسلامك؟ قال: انصرفت من حضرتك، فأحببت أن أمتحن هذه الأديان، وأنت مع ما تراني حسن الخط، فعمدت إلى التوراة، فكتبت ثلاث نسخ، فزدت فيها ونقصت، وأدخلتها الكنيسة، فاشتُريت مني.وعمدت إلى الإنجيل، فكتبت ثلاث نسخ، فزدت فيها ونقصت، وأدخلتها البيعة، فاشتُريت مني، وعمدت إلى القرآن فعملت ثلاث نسخ، وزدت فيها ونقصت، وأدخلتها الوراقين، فتصفحوها، فلما أن وجدوا فيها الزيادة والنقصان رموا بها، فلم يشتروها، فعلمت أن هذا كتاب محفوظ، فكان هذا سبب إسلامي. قال يحيى بن أكثم: فحججت تلك السنة، فلقيت سفيان بن عيينة، فذكرت له الخبر، فقال لي: مصداق هذا في كتاب الله عز وجل.قال: قلت: في أي موضع؟ قال: في قول الله تبارك وتعالى في التوراة والإنجيل بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللَّهِ. [سورة المائدة: 44] فجعل حفظه إليهم، فضاع، وقال عز وجل: إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ. فحفظه الله عز وجل علينا، فلم يضع\".انتهى.","ومن العلماء من جعل الذِّكْرَ شاملا للقرآن وسنة النبي صلى الله عليه وسلم، لأنها مفسرة له، فحفظ القرآن يتضمن حفظ السنة أيضا.","وهو كذلك؛ فإن السنة الصحية عن النبي صلى الله عليه وسلم كلها محفوظة، إلا أن طريقة حفظها تخلف عن طريق حفظ القرآن، كما بينت ذلك في المقدمة."],"474":["يقال: كانت الشياطين لا يحجبون عن السموات، وكانوا يدخلونها، ويأتون بأخبارها، فلما ولد عيسى عليه السلام، منعوا من ثلاث سماوات، فلما ولد محمد بن عبد الله النبي صلى الله عليه وسلم منعوا من السماوات أجمع.فما منهم من أحد يريد استراق السمع إلا رمي بشهاب، وقد جاء في الصحيح:"],"475":["قوله: وَلَقَدْ عَلِمْنَا الْمُسْتَقْدِمِينَ مِنْكُمْ وَلَقَدْ عَلِمْنَا الْمُسْتَأْخِرِينَ أي: أن الله يعلم كل من هلك من لدن آدم عليه السلام، وكل من هو حي، ومن سيأتي إلى يوم القيامة.","وأما ماروي عن ابن عباس قال: \"كانت تصلى خلف رسول الله صلى الله عليه وسلم امرأة حسنة من أحسن الناس، فكان بعض القوم يتقدم فى الصف الأول؛ لئلا يراها، ويستأخر بعضهم حتى يكون فى الصف المؤخر، فإذا ركع نظر من تحت إبطه، فأنزل الله: وَلَقَدْ عَلِمْنَا الْمُسْتَقْدِمِينَ مِنْكُمْ. فهو منكر.","رواه الترمذي (3122)، والنسائي (2/118)، وابن ماجه (1046)، وأحمد (2783)، وابن خزيمة (1696)، وابن حبان (401)، والحاكم (2/353) كلهم من حديث نوح بن قيس، عن عمرو بن مالك النكري، عن أبى الجوزاء، عن ابن عباس فذكره.","وقد روي مرسلا.قال الترمذي: \"وروي جعفر بن سليمان هذا الحديث عن عمرو بن مالك، عن أبي الجوزاء نحوه، ولم يذكر فيه عن ابن عباس.وهذا أشبه أن يكون أصح من حديث نوح\".","وكذا رجح الحافظ ابن كثير في تفسيره بأنه من كلام أبي الجوزاء، وقال: \"وهذا الحديث فيه نكارة شديدة.وقد رواه عبد الرزاق، عن جعفر بن سليمان، عن عمرو بن مالك- وهو البكري-، أنه سمع أبا الجوزاء يقول في قوله: وَلَقَدْ عَلِمْنَا الْمُسْتَقْدِمِينَ مِنْكُمْ في الصفوف في الصلاة الْمُسْتَأْخِرِينَ فالظاهر أنه من كلام أبي الجوزاء فقط، ليس فيه لابن عباس ذكر\".ثم ذكر قول الترمذي.","قلت: مع إرساله فيه عمرو بن مالك النكري ضعيف.ذكره ابن حبان في ثقاته، وقال: \"يعتبر حديثه من غير رواية ابنه عنه، يخطئ ويغرب\".","واختلف فيه قول ابن معين في توثيقه وتضعيفه، ومن كان هذا حاله، فلا يقبل منه مثل هذه القصة في الصحابة الكرام الذين أثنى الله عليهم خيرا، وأثنى عليه رسول الله صلى الله عليه وسلم، وأجمع المسلمون على عدولهم، والله المستعان."],"477":["قوله تعالى: لَهَا سَبْعَةُ أَبْوَابٍ وأسفلها للمنافقين لقوله تعالى: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا [سورة النساء: ١٤٥] ولغيرهم من أهل النار حسب إجرامهم كما جاء في الصحيح:"],"478":["أي: أن أهل الجنة تكون قلوبهم خالية من الشحناء، والبغضاء، والحقد والحسد، لأنهم يُنقّون، ويُهذّبون من كل ذلك قبل أن يدخلوا الجنة، كما جاء في الصحيح."],"479":["أي: لا يصيبهم فيها شيء من المشقة والأذى.وممن لهم بيت في الجنة ليس فيه نصب ولا صخب، أم المؤمنين خديجة رضي الله عنها كما جاء في الصحيح:"],"481":["في هذه الآيات الكريمة يذكر الله تعالى قصة لوط عليه السلام، وهو ابن أخي إبراهيم عليه السلام، خرج مع عمه من العراق إلى الكنعانيين أرض فلسطين والشام، فتوجه إبراهيم عليه السلام إلى مصر، وبعث الله لوطا عليه السلام لهداية أهل السدوم التي تقع جنوب البحر الميت، وكان أهلها ابتلوا بإتيان الذكور دون النساء.","وفي سفر التكوين (13: 13): \"كان أهل سدوم أشرارا وخُطاةً لدى الرب جدا\" فأمطر الله عليهم حجارة من السماء، وجعل عاليها سافلها.","وأما لوط ومن معه من المؤمنين فتوجهوا إلى مدينة صوغر إلا امرأته فإنها كانت من الهالكين. وقوله تعالى: إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْمُتَوَسِّمِينَ أي المتفرسين المتفكرين.","أي أن آثار الدمار والعذاب لا تزال قائمة على حافة البحر الميت، وفي ذلك عبرة للمعتبرين، وآيات لأولي الألباب والمتوسلين.","والبحر الميت سمي بذلك لكثافته، فإن مقدار الجامدة فيه نحو ثمانية أضعاف ما في ماء البحار، ولذا لا يغرق الإنسان في الماء لكثافته، ولا يعيش فيه شيء من النبات أو الحيوان، وطوله 46 ميلا، وعرضه عشرة أميال، وهو يبعد 16 ميلاد عن أروشليم شرقا."],"482":["قوله: أَصْحَابُ الْأَيْكَةِ هم قوم شعيب عليه السلام، والأيكة: الشجر الملتف بعضه ببعض، أي أن بيوتهم كانت في غيضة من الأشجار الكثيرة الورق، وكان ظلمهم أنهم أشركوا بالله تعالى، وقطعوا الطريق، ونقصوا في المكيال والميزان، فأخذهم الله بالصيحة والرجفة.","وقوله: ﴿وَإِنَّهُمَا أي قرية لوط وأيكة قوم شعيب، وجاء في سورة هود: وَمَا قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ﴾ [سورة هود: 89]","وقوله: لَبِإِمَامٍ مُبِينٍ أي كلتا القريتين بطريق القوافل بأهل مكة عندما كانوا يذهبون إلى الشام في الصيف."],"483":["قوله: أَصْحَابُ الْحِجْرِ الحجر من الحجارة لأنهم كانوا ينحتون بيوتهم في صخر الجبل نحتا محكما كما تدل عليه الآثار الموجودة الآن، وموقعهم بين المدينة والشام، وهو المعروف اليوم باسم مدائن صالح.","وقوله: فَأَخَذَتْهُمُ الصَّيْحَةُ مُصْبِحِينَ أي في وقت الصباح.","وقوله: فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ أي يصنعون البيوت في صخر الجبل؛ فإنها لم تنجهم من العذاب وهولاء هم قوم ثمود، وهم الذين كذبوا نبيهم صالحا عليه السلام، فجاءهم العذاب، فحذر النبي صلى الله عليه وسلم من الدخول في بيوتهم إلا أن تكونوا باكين، كما جاء في الصحيح:"],"484":["وقوله: سَبْعًا مِنَ الْمَثَانِي هو سورة الفاتحة؛ لأنها تتكرر قرأتها في كل صلاة، وقد جاء في الصحيح:"],"485":["قوله تعالى: لَا تَمُدَّنَّ عَيْنَيْكَ أي نهى أن يتمنى الرجل مال صاحبه كما قال ابن عباس، وجاء في سورة طه [130- 131]: وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِنْهُمْ زَهْرَةَ الْحَيَاةِ الدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَى","وقوله: وَلَا تَحْزَنْ عَلَيْهِمْ أي في حالهم الذي كانوا عليها من الكفر والعناد، وما يحل بهم من العذاب في الدنيا مثل يوم بدر وفي الآخرة.","وقوله: وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ أي كن رفيقا للمؤمنين ومتواضعا لهم، وإن كان القلب شديدا على الكفار فلا يكن كذلك مع المؤمنين، وذكر من صفات أصحاب محمد صلى الله عليه وسلم كما في سورة الفتح [29]: مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ","وقوله تعالى: وَقُلْ إِنِّي أَنَا النَّذِيرُ الْمُبِينُ والنذير على وزن فعيل بمعنى المنذر، والمقام يقتضي أن يقول للكفار: ما أنا إلا نذير من حدث فيه ضرر لكم، وقد جاء في الصحيح عن أبي موسى:"],"486":["قوله: عِضِينَ جمع عضة، من عضّيت الشيء إذا فرّقته، وجعلته أعضاء، وأصلها عضو فحذفت الواو، وعوض عنها الهاء.","المراد بالمقتسمين هم اليهود والنصارى الذين قسموا القرآن على قسمين، منه ما صدقوا به وهو ما يوافق دينهم، ومنه ما كذبوا به وهو ما يخالف تحريفهم وتبديلهم."],"488":["أي: استمر على عبادة الله حتى يأتيك الموت.فالمراد باليقين هنا الموت، ومما يدل على ذلك قوله تعالى: إخبارا عن أهل النار أنهم قالوا: قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ (43) وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ (44) وَكُنَّا نَخُوضُ مَعَ الْخَائِضِينَ (45) وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّينِ (46) حَتَّى أَتَانَا الْيَقِينُ (47) [سورة المدثر: ٤٣ – ٤٧].","وكذلك جاء اليقين بمعنى الموت في الحديث النبوي كما جاء في الصحيح:"],"490":["أي أنهم يحملون أوزار ضلالهم في أنفسهم، وكذلك يحملون أوزار إضلالهم لغيرهم، كما جاء في الصحيح:"],"491":["قوله: فَمِنْهُمْ مَنْ هَدَى اللَّهُ هداية التوفيق من الله، وأما هداية الدلالة والإرشاد فمن العباد، وبه أرسل الله الرسل في كل أمة.","وقوله: وَمِنْهُمْ مَنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُ وذلك من أجل اختيارهم الغواية على الهداية، والضلالة على الرشد، وتركهم سبيل الأنبياء والمرسلين، وعدم إيمانهم بدعوتهم، فلم يكونوا موفقين من الله عز وجل، وعليه يدل قوله تعالى: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا [الأنعام: ١٢٥]"],"492":["فيه إثبات لقدرة الله تعالى على إحياء الموتى، وردٌّ على منكريها.","وقوله: إِنَّمَا قصر لتكوين الموجود بمجرد صدور الأمر الإلهي، ولا يستحيل عليه شيء كما كان المشركون يعتقدون استحالة إحياء الموتى وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَا يَبْعَثُ اللَّهُ مَنْ يَمُوتُ [النحل: ٣٨] وفي سورة يس [78] وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ.","وقوله: لِشَيْءٍ شامل للموجود وغير الموجود، وأما الموجود فمثل إحياء الموتى الذين صاروا كالرمائم فتعود إليهم الحياة بأمر الله تعالى: كُنْ","وأما غير الموجود فمثل خلق السموات والأرض وما فيهن، فإن الله خلقهن من العدم، وعليه يدل قوله تعالى: بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ [البقرة: ١١٧]"],"493":["قوله تعالى: وَلِلَّهِ يَسْجُدُ مَا فِي السَّمَاوَاتِ وقال تعالى في سورة الرعد [15]: وَلِلَّهِ يَسْجُدُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَالُهُمْ بِالْغُدُوِّ وَالْآصَالِ فيه إشارة إلى وجود مخلوقات في الكواكب تسجد لله كما تسجد الجمادات من الشمس والقمر والسيارات الأخرى، وأما الملائكة فيأتي ذكرهم استقلالا.","وقوله تعالى: مِنْ دَابَّةٍ الدابة تطلق على كل ما يدب على الأرض غير الإنسان، وسجود هذه الدواب الانقياد والطاعة لله عز وجل لما خُلقنَ كما جاء في سورة فصلت [11] ثُمَّ اسْتَوَى إِلَى السَّمَاءِ وَهِيَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ائْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَا أَتَيْنَا طَائِعِينَ","وقوله تعالى: وَالْمَلَائِكَةُ بالرفع، خص ذكر الملائكة مع كونهم من جملة ما في السموات بسبب اعتقاد المشركين بأنهم بنات لله، ولهم تصرف فأبطل الله هذا الاعتقاد، وأخبر أنهم من جملة المخلوقين الذين يسجدون لله عز وجل ثم ذكر من صفاتهم وَهُمْ لَا يَسْتَكْبِرُونَ."],"494":["بعد أن أبطل الله اعتقاد المشركين عموما في اتخاذ الآلهة الكثيرة، أبطل في هذه الآية الكريمة اعتقاد بعض المشركين من العرب الذين تأثروا بعقيدة الفرس الذين كانوا في جوارهم، وهم يعبدون إلهين اثنين، إله الخير يسمونه \"يزدان\"، وإله الشر ويسمونه \"أهرمن\"، وزعموا أن يزدان كان منفردا بالإلهية، وكان لا يخلق إلا الخير، فلم يكن في العالم إلا الخير، فخطر في نفسه مرة خاطر شر، فتولد عنه إله آخر شريك له، وهو إله الشر.","وقد دان بهذه العقيدة بعض القبائل العربية، فردّ الله عليه، وأحكم القول بأنه إله واحد، وهو مثل قول الله تعالى لعيسى بن مريم وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ مِنْ دُونِ اللَّهِ [المائدة: ١١٦] فلما تبرأ عيسى عليه السلام قَالَ اللَّهُ هَذَا يَوْمُ يَنْفَعُ الصَّادِقِينَ صِدْقُهُمْ [المائدة: ١١٩]"],"495":["من الأفعال القبيحة عند المشركين أنهم جعلوا لله البنات –وهو منزه عنه- وكرهوا ذلك لأنفسهم فإن من بُشّر بولادة الأنثى صار وجهه مسودا من شدة الحزن والكراهية، فيغيب عن أبصارهم للعار الذي لحقه بولادة هذه الأنثى، فهو يتردد بين إمساكها على هون، وبين دسّه في التراب حية وهو قوله تعالى أَيُمْسِكُهُ عَلَى هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ","ومن صور الوأد ما ذكره البغوي في تفسيره (2/619): \"وكان الرجل من العرب إذا ولدت له بنت، وأراد أن يستحييها، ألبسها جبة من صوف أو شعر، وتركها ترعى له الإبل والغنم في البادية، وإذا أراد أن يقتلها تركها حتى إذا صارت سداسية قال لأمها: زيّنيها حتى أذهب بها إلى أحمائها، وقد حفر لها بئرا في الصحراء، فإذا بلغ بها البئر قال لها: انظري إلى هذا البئر فيدفعها من خلفها في البئر، ثم يُهيل على رأسها التراب حتى يستوي البئر بالأرض فذلك قوله عز وجل: أَيُمْسِكُهُ عَلَى هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ"],"497":["قوله: أَرْذَلِ الْعُمُرِ أي: آخره في حال الكبر والعجز والخرف.والأرذل من كل شيء: الرديء منه، وقد جاء في الصحيح الإستعاذة منه."],"499":["قوله: وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ أي أوفوا بالعهود والمواثيق، فإن الغدر والخيانة من علامات النفاق كما جاء في الصحيح:"],"500":["قوله: فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً أي: الحياة المشتملة على وجوه الخير من الرزق الحلال والقناعة والطاعة ونحوها."],"501":["هذا أمر من الله لعباده على لسان نبيه أن يستعيذوا بالله تعالى من الشيطان الرجيم إذا أرادوا أن يقرؤوا القرآن الكريم، وهذا مثل قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ [سورة المائدة: ٦]، فالإستعاذة تكون قبل القراءة على رأي جمهور أهل العلم، وهو الصحيح."],"503":["قوله: إِنَّمَا جُعِلَ السَّبْتُ أي: فرضت عليهم أحكام السبت من تحريم العمل فيه.","وقوله: عَلَى الَّذِينَ اخْتَلَفُوا فِيهِ أي: اليهود.","فصار يوم السبت واجبا إحترامه على اليهود مع أنهم يدعون أنهم على ملة إبراهيم، وليس في ملة إبراهيم حرمة السبت، ولذا جاء عيسى عليه السلام ولم يحترم يوم السبت كاحترام اليهود، قائلا: \"السبت إنما جعل لأجل الإنسان، لا الإنسان لأجل السبت\".(إنجيل مرقس: 2/27).","وكان ذلك من جملة أسباب معاداة اليهود لعيسى عليه السلام، ثم ابتدع النصارى بعد رفع المسيح، فاتخذوا يوم الأحد، وجعلوا يجتمعون فيه للصلاة بحجة قيامة المسيح من القبر يوم الأحد، وهدى الله هذه الأمة ليوم الجمعة، كما جاء في الأحاديث الصحيحة، وأن الله تعالى يخبر يوم القيامة المحق من المبطل في ذلك."],"506":["قوله: الْمَسْجِدِ الْأَقْصَى فيه إخبار عن وجود مسجد آخر، وهو مسجد المدينة، ويكون مسجد إيليا أبعد المسجدين من المسجد الحرام.","والمسجد الأقصى هو المسجد الثاني الذي بناه إبراهيم عليه السلام بعد المسجد الحرام، وكان بينهما أربعون سنة كما جاء في الصحيحين- البخاري (3366)، ومسلم (520)- من حديث أبي ذر قال: قلت: يا رسول الله أي مسجد وُضِعَ في الأرض أوّلُ؟ قال: ((المسجد الحرام)).قلت: ثم أي؟ قال: ((المسجد الأقصى)).قلت: كم بينهما؟ قال: ((أربعون سنة)).","أي بعد أن فرغ إبراهيم عليه السلام مع ابنه إسماعيل ببناء المسجد الحرام، ورجع إلى فلسطين، وُلِدَ له إسحاق من زوجته سارة بعد أربع عشرة سنة من ولادة إسماعيل، وكان عمر إبراهيم آنذاك مائة سنة، فلما ماتت سارة تزوج إبراهيم عليه السلام بقطوراة فوُلِدَ له ستة بنين، وتزوج إسحاق بعد أربعين سنة، وولد له يعقوب وعيسو بعد عشرين سنة، فلما كثر أولاده وأحفاده احتاج إلى بناء بيت للعبادة وذلك بعد أربعين سنة كما جاء في الصحيح، فبنى له مذبحا كما تنص التوراة: \"فبنى هناك مذبحا للرب، ودعا باسم الرب\" التكوين (8:12)","ثم جدّد بناءه داود عليه السلام، واستكمله سليمان عليه السلام فنسب إليه.","والمذبح هو بمعنى المسجد وقوله: ودعا باسم الرب يعني وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن: ١٨].","ومات إبراهيم عليه السلام وعمره مائة وخمس وسبعون سنة."],"507":["وقوله: وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ أي: أن الإنسان يدعو أحيانا بالشر كدعائه بالخير في حالات الغضب وضيق النفس ونحوها، وهذا من جهل الإنسان وعجلته، ولكن الله قد لا يستجيب له رحمة منه وفضلا، وقد جاء النهي عن الدعاء على النفس والأولاد والمال، كما في الصحيح:"],"509":["وقوله: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا أي أن الله عزوجل لا يعذب أحداً إلا بعد قيام الحجة عليه بإرسال الرسول إليه، والذين لم تبلغهم الدعوة، ولم تقم عليهم الحجة في الدنيا يمتحنون يوم القيامة، كما جاء في الحديث."],"510":["قد جاء في بر الوالدين أحاديث كثيرة، منها:"],"511":["إن الله تعالى يأمر بصلة الأرحام، والإحسان إلى الأقرباء، الأقرب فالأقرب كما جاء في الحديث."],"512":["إن الله يأمر بالوسطية في الإنفاق، وينهى عن البخل وعن الإسراف، وقد جاء في الحث على الإنفاق والنهي عن البخل أحاديث كثيرة منها:"],"513":["كان أهل الجاهلية لا يورثون البنات بل منهم من يقتل ابنه خوفا من الفقر، فنهى الله تعالى عن ذلك، وقد جاءت في ذلك أحاديث كثيرة، منها:"],"514":["نهى الله عزوجل عن الزنا، وعن مقاربته، ومخالطة أسبابه ودواعيه، وقد جاء في ذم الزنا والنهي عنه أحاديث كثيرة، منها."],"515":["نهى الله عن قتل النفس بغير حق شرعي، وقد جاء في ذلك أحاديث، منها:"],"516":["إن الله عزوجل نهى عن سوء التصرف في مال اليتيم، وأمر بحسن التصرف فيه، ومما فيه مصلحة لليتيم. وقد جاء في الحديث الصحيح:"],"517":["إن الله عز وجل أمر بإيفاء الكيل والوزن، ونهى عن البخس، والتطفيف في ذلك، ومن ترك شيئا لله عز وجل أعطاه الله خيرا من ذلك، كما جاء في الحديث."],"518":["أي أن المخلوقات كلها تسبح بحمد الله تعالى، ولكن الناس لا يفقهون تسبيحها، وقد جاءت أحاديث كثيرة تدل على ذلك، منها:"],"519":["قوله: وَآتَيْنَا دَاوُودَ زَبُورًا فيه تنبيه على فضل داود عليه السلام وشرفه، وقد جاء في الحديث أنه كان خُفِّف عليه قراءته."],"523":["قوله: لَأَحْتَنِكَنَّ ذُرِّيَّتَهُ إِلَّا قَلِيلًا أي: لأضلّنّ ذريّته إلّا قليلا منهم، وقد جاء في الصحيح أن الشياطين اجتالت الناس عن دينهم الصحيح، وحرّمت عليهم ما أحلّ الله لهم."],"524":["فيه إخبار بتأييده تعالى عباده المؤمنين، وحفظه إياهم، وحراسته لهم من الشيطان الرجيم، ومن جملة الأسباب التي يحفظ الله بها عباده من الشيطان:","1- قراءة سورة البقرة:"],"525":["قوله: إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا أي: أن صلاة الفجر يشهدها ملائكة الليل والنهار، وقد جاء ذلك في أحاديث كثيرة، منها:"],"526":["وقوله: مَقَامًا مَحْمُودًا هو المقام الذي يقومه صلى الله عليه وسلم يوم القيامة لشفاعة الناس، ليريحهم ربهم من عظيم ما هم فيه من شدة ذلك اليوم، وقد جاء في أحاديث كثيرة، كما سبق ذكرها في كتاب الإيمان، منها:"],"527":["روي عن ابن عباس قال: كان النبي صلى الله عليه وسلم بمكة، ثم أمر بالهجرة، فنــزلت عليه: وَقُلْ رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَلْ لِي مِنْ لَدُنْكَ سُلْطَانًا نَصِيرًا","رواه الترمذي (3139) وغيره من طريق قابوس بن أبي ظبيان، عن أبيه عن ابن عباس، وقال: \"هذا حديث حسن صحيح\".","قلت: وليس كما قال، فإن قابوس بن أبي ظبيان ضعفه جمهور أهل العلم، وقد تفرد به، ولا يقبل تفرده.والكلام عليه مبسوط في كتاب السيرة."],"531":["قوله: تِسْعَ آيَاتٍ بَيِّنَاتٍ جاء ذكرها في آيات أخرى من القرآن الكريم، وهي:","1- قوله تعالى: فَأَرْسَلْنَا عَلَيْهِمُ الطُّوفَانَ وَالْجَرَادَ وَالْقُمَّلَ وَالضَّفَادِعَ وَالدَّمَ آيَاتٍ مُفَصَّلَاتٍ [سورة الأعراف: ١٣٣] فهذه خمسة.","2- قوله تعالى: فَأَلْقَى عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُبِينٌ (107) وَنَزَعَ يَدَهُ فَإِذَا هِيَ بَيْضَاءُ لِلنَّاظِرِينَ (108) [سورة الأعراف: ١٠٧ – ١٠٨] فصارتْ سبعة.","3- قوله تعالى: فَأَوْحَيْنَا إِلَى مُوسَى أَنِ اضْرِبْ بِعَصَاكَ الْبَحْرَ فَانْفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ (63) [سورة الشعراء: ٦٣] فصارتْ ثمانية.","4- قوله تعالى: وَلَقَدْ أَخَذْنَا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَذَّكَّرُونَ [سورة الأعراف: ١٣٠] فبهذا اكتملتْ تسعة.","وقد اختلف بعض أهل العلم في عدّ هذه الآيات، والتي ذكرتها هي أصحها.وأما الآيات التي ظهرت خلال أربعين سنة في سيناء فهي كثيرة، وليست مرادة هنا، وإنما المراد الآيات التي شاهدها فرعون وقومه من أهل مصر لإقامة الحجة عليهم."],"532":["قوله: قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ أَيًّا مَا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَى"],"536":["الاستفهام للنفي أي: لا تظن أن أصحاب الكهف من أعظم آيات الله سبحانه وتعالى، بل له آيات كثيرة، أليس خلق السموات والأرض أعظم من قصة أصحاب الكهف، بل وفي خلق الإنسان آيات وعجائب لو فكّر وتدبّر.","وقوله: وَالرَّقِيمِ أصحّ ما قيل فيه هو لوح من الحجارة الذي كتبت فيه قصص أصحاب الكهف، ثم وضع على باب الكهف.","وأما \"الرقيم\" الذي جاء ذكره في حديث النعمان بن بشير أنه سمع رسول الله صلى الله عليه وسلم يذكر الرقيم فقال: ثم ذكر قصة الثلاثة الذين آووا إلى الغار من أجل المطر ، فوقعت صخرةٌ من الجبل على باب الغار ...الحديث بطوله.","فهو اسم للوادي الذي فيه الغار.","انظر للمزيد من التفصيل : كتاب الأدعية والأذكار، باب التوسل الشرعي في الدعاء."],"537":["يُخبِرُ اللهُ تعالى أنه أَطْلعَ الناسَ على حالِ أهلِ الكهفِ بعد ما استيقظوا، وأَشهرَ اللهُ أمرَهم، ورفعَ قدرَهم. فَقَالُوا أي قال كفّارُ أهل زمانهم.","ابْنُوا عَلَيْهِمْ بُنْيَانًا أي: صدّوا عليهم باب كهفهم، وذروهم على حالهم.","قَالَ الَّذِينَ غَلَبُوا عَلَى أَمْرِهِمْ أي الذين كانتْ لهم السلطةُ والرياسةُ، وهم كفّارُ ذلك الزمان.","لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِدًا أي نَبْنِيْ عليهم معبدًا لنتذكّرَ أحوالَهم ، وهذا ليس فيه إقرارٌ من الله تعالى على فِعْلهم، وإنما فيه إخبارٌ عما قالوا.","لأنَّ بناءَ المساجد (أي المعابد) على القبور ممنوعٌ في شرائعِ جميعِ الأنبياءِ والرسلِ، ولذا لُعِنَ اليهودُ والنصارَى على لسانِ رسولِ الله صلى الله عليه وسلم في قوله: «لَعَنَ اللهُ اليهودَ والنصارَى، اتـخذوا قبورَ أنبيائِهم مساجِدَ«."],"539":["قوله: وَلَبِثُوا فِي كَهْفِهِمْ ثَلَاثَ مِائَةٍ سِنِينَ وَازْدَادُوا تِسْعًا قال بعض أهل العلم: هذا إخبار من الله عن أهل الكتاب أنهم قالوا ذلك، ويدل على صحة ذلك قولِه تعالى: قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا لأنه لو كان ذلك خبرا من الله عن مقدار لبثهم في الكهف لم يكن لقوله: قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا وجه مناسب.وهذا القول ذهب إليه قتادة وغيره من المفسرين، ولهم أقوال وتوجيهات أخرى في بيان معنى الآية."],"540":["قوله: وَالْبَاقِيَاتُ الصَّالِحَاتُ يشمل جميع العبادات الواجبة والمستحبة والأعمال الصالحة التي أمر بها الإسلام في الكتاب والسنة."],"543":["قوله: إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ إن يأجوج ومأجوج من سلالة بني آدم، من أصحاب فتنة وفساد في الأرض، وقد وردت عنهم أحاديث تدل على شدة فتنتهم وفسادهم عند خروجهم."],"544":["قوله: وَنُفِخَ فِي الصُّورِ الصور قرن ينفخ فيه، وقد التقم الملك الموكل بالنفخ القرن ينتظر متى يؤمر أن ينفخ فيه، كما جاء ذلك في الحديث."],"548":["قوله: جَنَّاتُ الْفِرْدَوْسِ الفردوس ربوة الجنة وأوسطها وأفضلها وأعلاها، كما جاء في الحديث."],"550":["وقد جاءت أحاديث كثيرة تدل على بشرية الرسول صلى الله عليه وسلم ومنها:"],"552":["قوله: يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ يرثني أي النبوة، ويرث من آل يعقوب الشرع والعلم، ومن للتبعيض أي يرث أيضا من بعض آل يعقوب النبوة لأن جميع آل يعقوب لم يكونوا أنبياء ولا علماء، وأما المال فلم يكن مرادا لأن الأنبياء لا يورّثون بل ما يتركونه يكون صدقة كما جاء في الصحيح."],"553":["قوله: سَمِيًّا له عدة معانٍ: منها: إن الله سمّاه يحيى، ولم يسم أحد قبله بهذا الاسم.","ومنها: لم يكن أحد قبله شبيها له مثل قوله: هَلْ تَعْلَمُ لَهُ سَمِيًّا أي شبيها؛ لأنه لم يعص الله قط، ولم يهم بمعصية.","ومنها: أنه ولد من امرأة عاقر كما قال زكريا حين بُشّر به. قَالَ رَبِّ أَنَّى يَكُونُ لِي غُلَامٌ وَكَانَتِ امْرَأَتِي عَاقِرًا وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ عِتِيًّا","ولم يعرف أن امرأة عاقرا قد ولدتْ.","وقوله: عِتِيًّا من عتا يعتو إذا يبس ومعناه كبر، ولم يبق له نكاح ولا جماع.","وهذا بخلاف إبراهيم وسارة فإنهما تعجّبا من البشارة يإسحاق على كبرهما لا لعقرهما كما جاء في سورة هود: قَالَتْ يَا وَيْلَتَى أَأَلِدُ وَأَنَا عَجُوزٌ وَهَذَا بَعْلِي شَيْخًا إِنَّ هَذَا لَشَيْءٌ عَجِيبٌ [سورة هود: 72] وقد وُلِدَ لإبراهيم قبل أربع عشرة سنة إسماعيل عليه السلام."],"554":["قوله يَا أُخْتَ هَارُونَ: هارون هو ابن عمران أخو مريم من سبط يهوذا من نسل داود عليه السلام، وليس هو أخو موسى عليه السلام كما فهم نصارى نجران، وإنما سمي هارون تيمنا بنبي الله هارون بن عمران بن قاهت بن يعقوب بن إسحاق بن إبراهيم وقد جاء في الصحيح:"],"555":["قوله: فَأَشَارَتْ إِلَيْهِ أي أن مريم لما تحيرت من حادثة ولادة عيسى عليه السلام بهذه الصورة ولم يكن لديها جواب شاف، فألهمت أن تُشير إلى هذا الغلام الذي لا يزال في المهد.","وقوله: قَالُوا كَيْفَ نُكَلِّمُ مَنْ كَانَ فِي الْمَهْدِ صَبِيًّا أي أنكروا أن يكلموا هذا الصبي الذي لا يزال في المهد.","وقوله: قَالَ إِنِّي عَبْدُ اللَّهِ وهذه من جملة المعجزات الكبرى التي حذفها النصارى من تراثهم الديني والتاريخي بعد مجمع نيقيا الذي عقد عام (325م) لأن فيه اعتراف المسيح بالعبودية لله تعالى، وهو يخالف دعواهم ألوهيته، ولذا بدأوا يضطهدون أتباع أريانوس المصري المتوفى سنة (336م)، وكل من دعا إلى عبودية المسيح لله، وحرّقوا جميع الكتب والصحائف التي تخالف دعواهم ألوهية المسيح كما فصّلتُ القول في ذلك في كتابي: \"دراسات في اليهودية والمسيحية\".","ومما ضيّعوا من حياة المسيح عليه السلام هذه المعجزة.","قوله: آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا معناه إن الله سيؤتيني الكتاب ويجعلني نبيا، وعبّر في الآية بالفعل الماضي عن المستقبل لتحقق وقوعه، وله نظائر كثيرة في القرآن الكريم، وهذا هو الصحيح إن شاء الله، وما نُقلَ في كتب التفاسير من أقاويل أخرى كلها ضعيفة."],"556":["قوله: مَا كَانَ لِلَّهِ أَنْ يَتَّخِذَ مِنْ وَلَدٍ سُبْحَانَهُ أي: أن الله عزوجل مُنَزَّهٌ من اتخاذ الولد، وغني عن ذلك."],"557":["قوله: فَاخْتَلَفَ الْأَحْزَابُ أي بعد أن كان النصارى متفقين على عبودية المسيح ورسالته، اختلفوا بعد رفعه، وبالضبط بعد دخول بولس في النصرانية وذلك في حدود (40) الميلادي، وادعوا ألوهية المسيح، وأنه صلب لخطايا بني بشر، وردّ عليهم رئيس الحواريين بطرس، فتفرقت النصرانية إلى ثلاث فرق رئيسية وهي: الملكانية يُمثّلها اليوم فرقة كاتوليك، واليعقوبية يُمثّلُها اليوم أرثودكس، والنسطورية يمثّلها اليوم البروتستان، ثم تفرعت عن هذه الفرق فرق كثيرة لا تُحصى ولا تُعد كما ذكرته في كتابي \"اليهودية والنصرانية\"، وهولاء كلهم متفقون على الكفر بالله، ولذا قال الله تعالى: فَوَيْلٌ لِلَّذِينَ كَفَرُوا مِنْ مَشْهَدِ يَوْمٍ عَظِيمٍ واليوم العظيم هو يوم القيامة."],"558":["قوله: يَوْمَ الْحَسْرَةِ أي حسرة أهل النار يوم يدخلون النار، كما جاء في الصحيح:"],"559":["قوله: أَضَاعُوا الصَّلَاةَ أي تركوا الصلاة المفروضة."],"560":["قوله: وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا ليس المقصود به الأوقات المعروفة في الدنيا التي تكون تبعا للشمس والقمر، بل المقصود منه التنعم في جميع الأوقات؛ لأن جمهور أهل العلم نفوا أن يكون في الجنة ليل لقوله تعالى: مُتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا [سورة الإنسان: ١٣] فإن تعاقب الليل والنهار يكون تبعا لوجود الشمس."],"563":["قوله: إِلَّا وَارِدُهَا له معنيان عند السلف:","أحدهما: الدخول في النار، فإن هذا الخطاب لسائر الخلائق، برّهم وفاجرهم، مؤمنهم وكافرهم، فما منهم من أحد إلا يرد النار.","قال البغوي في تفسيره (3/100): \"وعليه أهل السنة والجماعة أنهم جميعا يدخلون النار، ثم يخرج الله عز وجل منها أهل الإيمان بدليل قوله تعالى: ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا قال: والنجاة إنما تكون مما دخلت فيه.انتهى.","واستدلوا لهذا المعنى أيضا بقوله تعالى حكاية عن فرعون يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَةِ فَأَوْرَدَهُمُ النَّارَ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ [سورة هود: 98] أي أن فرعون يتقدم قومه إلى النار.","وإلى هذا القول ذهب علي وابن عباس، وكثير من أهل العلم سلفا وخلفا. قال القرطبي في التذكرة (2/762): \"والصحيح أن الورود الدخول لحديث أبي سعيد كما ذكرنا\" وذكر في معناه أحاديث أخرى وهي مخرجة في مواضعها.","قلت: لعل دخول المؤمنين والكفار جميعا النار، ثم خروج المؤمنين منها دون الكفار لتعذيب الكفار نفسيا وجسديا."],"565":["أي: أن الله عزوجل يغرس لعباده المؤمنين الذين يعملون الصالحات المودة في قلوب عباده الصالحين، كما جاء في الصحيح:"]});